def check_revenue_calc__a19e9874(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Compare revenue calculations against expected values.

    Args:
        result: Dict from getter with G2, G3, G37 values
        expected: Dict with expected values
        **options: Additional options (tolerance for float comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    checks = 0
    passes = 0
    if 'G2' in result and 'G2' in expected:
        checks += 1
        if result['G2'] is not None and expected['G2'] is not None:
            if abs(result['G2'] - expected['G2']) <= tolerance:
                passes += 1
    if 'G3' in result and 'G3' in expected:
        checks += 1
        if result['G3'] is not None and expected['G3'] is not None:
            if abs(result['G3'] - expected['G3']) <= tolerance:
                passes += 1
    if 'G37' in result and 'G37' in expected:
        checks += 2
        if result['G37'] is not None and expected['G37'] is not None:
            if abs(result['G37'] - expected['G37']) <= tolerance:
                passes += 2
    if checks > 0:
        score = passes / checks
    return score

def check_xlsx_bg_color__889abc06(result, expected, **options):
    """Check if cell background color matches expected color.

    Args:
        result: Background color from getter (hex string or theme marker)
        expected: Expected color (hex string like 'FF0000FF' for blue)
        **options: Options like 'color_tolerance' and 'strict_color_match'

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    strict_match = options.get('strict_color_match', False)
    tolerance = options.get('color_tolerance', 20)
    if isinstance(result, str) and result.startswith('theme_'):
        if expected.upper() in ['FF0000FF', '0000FF', 'BLUE']:
            return 1.0 if result in ['theme_4', 'theme_5'] else 0.0
        return 0.0
    result_str = str(result).upper().replace('#', '')
    expected_str = str(expected).upper().replace('#', '')
    if len(result_str) == 8:
        result_str = result_str[2:]
    if len(expected_str) == 8:
        expected_str = expected_str[2:]
    if strict_match:
        return 1.0 if result_str == expected_str else 0.0
    try:
        (r1, g1, b1) = (int(result_str[0:2], 16), int(result_str[2:4], 16), int(result_str[4:6], 16))
        (r2, g2, b2) = (int(expected_str[0:2], 16), int(expected_str[2:4], 16), int(expected_str[4:6], 16))
        distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
        return 1.0 if distance <= tolerance else 0.0
    except:
        return 0.0

def check_xlsx_complete_task__da1fee34b91e6bf475f61d4000eac0e3(result, expected, **options):
    """Comprehensive check for the complete task requirements.

    Verifies:
    1. Column E header is 'Formatted Name'
    2. Column E contains correct formatted names (Last, First)
    3. Column A still contains original employee data unchanged
    4. Columns B, C, D contain correctly split data (First Name, Last Name, Rank)
    5. Formatted names in E match the split data in B and C

    Args:
        result: Dict with 'rows' key containing all data from columns A-E
        expected: Dict with expected values for all fields

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'rows' not in result:
        return 0.0
    rows = result.get('rows', [])
    expected_formatted = expected.get('formatted_names', [])
    expected_first = expected.get('first_names', [])
    expected_last = expected.get('last_names', [])
    expected_ranks = expected.get('ranks', [])
    expected_original = expected.get('original_data', [])
    expected_header = expected.get('header_text', 'Formatted Name')
    if len(rows) < 21:
        return 0.0
    if len(rows) != len(expected_formatted):
        return 0.0
    scores = []
    for (i, row) in enumerate(rows):
        if i >= len(expected_formatted):
            break
        row_score = 0.0
        checks_passed = 0
        total_checks = 5
        original = row.get('original', '').strip()
        expected_orig = expected_original[i].strip() if i < len(expected_original) else ''
        if ' '.join(original.split()) == ' '.join(expected_orig.split()):
            checks_passed += 1
        first_name = row.get('first_name', '').strip()
        expected_fn = expected_first[i].strip() if i < len(expected_first) else ''
        if first_name == expected_fn:
            checks_passed += 1
        last_name = row.get('last_name', '').strip()
        expected_ln = expected_last[i].strip() if i < len(expected_last) else ''
        if last_name == expected_ln:
            checks_passed += 1
        rank = row.get('rank', '').strip()
        expected_rk = expected_ranks[i].strip() if i < len(expected_ranks) else ''
        if rank == expected_rk:
            checks_passed += 1
        formatted = row.get('formatted', '').strip()
        expected_fmt = expected_formatted[i].strip()
        if ' '.join(formatted.split()) == ' '.join(expected_fmt.split()):
            checks_passed += 1
        row_score = checks_passed / total_checks
        scores.append(row_score)
    return sum(scores) / len(scores) if scores else 0.0

def check_xlsx_cell_highlight__052c762f(result_state, expected_state, **options):
    """
    Check if the cell with maximum value in a range has the expected highlight/fill color.

    This function dynamically finds the cell with the maximum value in a specified range,
    then verifies that cell has a yellow (or specified color) background fill.
    It supports fuzzy color matching with a tolerance parameter.

    Args:
        result_state: Path to the result xlsx file (str)
        expected_state: Dict containing:
            - sheet: Sheet index (int) or name (str)
            - range: Cell range to search for max value (str, e.g., 'C3:O3')
            - cell: (Alternative) Specific cell coordinate if not using range (str, e.g., 'O3')
            - check_fill: Whether to check fill color (bool, default True)
            - strict_color_match: Whether to require exact color match (bool, default False)
            - color_tolerance: Max RGB distance for fuzzy matching (int, default 30)
            - expected_color: Optional specific color to check (str hex, e.g., 'FFFF00')
        **options: Additional options

    Returns:
        float: 1.0 if the cell has the expected highlight, 0.0 otherwise
    """
    if result_state is None:
        logger.error('Result file path is None')
        return 0.0
    try:
        logger.info(f'Loading result file: {result_state}')
        workbook = openpyxl.load_workbook(filename=result_state)
    except Exception as e:
        logger.error(f'Failed to load result file {result_state}: {e}')
        return 0.0
    sheet_idx = expected_state.get('sheet', 0)
    try:
        if isinstance(sheet_idx, int):
            sheet_names = workbook.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available: {sheet_names}')
                return 0.0
            sheet = workbook[sheet_names[sheet_idx]]
        else:
            sheet = workbook[sheet_idx]
        logger.info(f'Loaded sheet: {sheet.title}')
    except Exception as e:
        logger.error(f'Failed to load sheet {sheet_idx}: {e}')
        return 0.0
    cell_coord = None
    cell_range = expected_state.get('range')
    if cell_range:
        logger.info(f'Finding maximum value in range: {cell_range}')
        try:
            cells_in_range = sheet[cell_range]
            if isinstance(cells_in_range, tuple):
                all_cells = []
                for row in cells_in_range:
                    if isinstance(row, tuple):
                        all_cells.extend(row)
                    else:
                        all_cells.append(row)
            else:
                all_cells = [cells_in_range]
            max_value = None
            max_cell = None
            for cell in all_cells:
                if cell.value is not None:
                    try:
                        cell_value = float(cell.value)
                        if max_value is None or cell_value > max_value:
                            max_value = cell_value
                            max_cell = cell
                    except (ValueError, TypeError):
                        logger.warning(f'Cell {cell.coordinate} has non-numeric value: {cell.value}')
                        continue
            if max_cell is None:
                logger.error(f'No numeric values found in range {cell_range}')
                return 0.0
            cell_coord = max_cell.coordinate
            logger.info(f'Found maximum value {max_value} at cell {cell_coord}')
        except Exception as e:
            logger.error(f'Failed to process range {cell_range}: {e}')
            return 0.0
    else:
        cell_coord = expected_state.get('cell')
        if not cell_coord:
            logger.error('No cell coordinate or range specified')
            return 0.0
    try:
        cell = sheet[cell_coord]
        logger.info(f'Checking cell {cell_coord}, value: {cell.value}')
    except Exception as e:
        logger.error(f'Failed to access cell {cell_coord}: {e}')
        return 0.0
    check_fill = expected_state.get('check_fill', True)
    if not check_fill:
        logger.warning('check_fill is False, returning 1.0')
        return 1.0
    try:
        cell_fill = cell.fill
        if cell_fill is None or cell_fill.fgColor is None:
            logger.error(f'Cell {cell_coord} has no fill color')
            return 0.0
        cell_color = cell_fill.fgColor.rgb
        if cell_color is None:
            logger.error(f'Cell {cell_coord} fill color is None')
            return 0.0
        logger.info(f'Cell {cell_coord} fill color: {cell_color}')
    except Exception as e:
        logger.error(f'Failed to read cell fill color: {e}')
        return 0.0
    expected_color = expected_state.get('expected_color', 'FFFF00')
    strict_match = expected_state.get('strict_color_match', False)
    if strict_match:
        cell_color_normalized = cell_color[2:] if len(cell_color) == 8 else cell_color
        expected_color_normalized = expected_color[2:] if len(expected_color) == 8 else expected_color
        if cell_color_normalized.upper() == expected_color_normalized.upper():
            logger.info(f'Exact color match: {cell_color_normalized} == {expected_color_normalized}')
            return 1.0
        else:
            logger.warning(f'Color mismatch: {cell_color_normalized} != {expected_color_normalized}')
            return 0.0
    else:
        color_tolerance = expected_state.get('color_tolerance', 30)
        distance = _rgb_distance(cell_color, expected_color)
        logger.info(f'Color distance: {distance}, tolerance: {color_tolerance}')
        if distance <= color_tolerance:
            logger.info(f'Color match within tolerance: distance={distance} <= {color_tolerance}')
            return 1.0
        else:
            yellow_variants = ['FFFF00', 'FFFF99', 'FFFFCC', 'FFFFE0', 'FFF8DC', 'FAFAD2']
            for variant in yellow_variants:
                variant_distance = _rgb_distance(cell_color, variant)
                if variant_distance <= color_tolerance:
                    logger.info(f'Color matches yellow variant {variant}: distance={variant_distance}')
                    return 1.0
            logger.warning(f'Color does not match within tolerance: distance={distance} > {color_tolerance}')
            return 0.0

def check_xlsx_cells__7d76b171(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Excel cells contain expected values.
    
    Args:
        result: Dict mapping cell addresses to their actual values
        expected: Dict with 'cells' key containing expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', {})
    if not expected_cells:
        return 0.0
    score = 0.0
    tolerance = options.get('tolerance', 0.5)
    for (cell_addr, expected_val) in expected_cells.items():
        actual_val = result.get(cell_addr)
        if actual_val is None:
            continue
        if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
            if abs(actual_val - expected_val) <= tolerance:
                score += 1.0
        elif isinstance(expected_val, str) and isinstance(actual_val, str):
            if expected_val.strip().lower() == actual_val.strip().lower():
                score += 1.0
        elif actual_val == expected_val:
            score += 1.0
    return score / len(expected_cells) if len(expected_cells) > 0 else 0.0

def check_numeric_value__f95cf07b(result, expected, **options):
    """Check if numeric value matches expected with tolerance.

    Args:
        result: Numeric value from getter
        expected: Expected numeric value
        **options: 'tolerance' for floating point comparison (default 1.0)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    tolerance = options.get('tolerance', 1.0)
    expected_value = expected.get('value', 0)
    try:
        result_num = float(result)
        expected_num = float(expected_value)
        if abs(result_num - expected_num) <= tolerance:
            return 1.0
    except (ValueError, TypeError):
        pass
    return 0.0

def check_xlsx_weekday_highlights__945bc7e35c7c17397875064b3c531090(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all weekday cells are highlighted with the expected color.

    Args:
        result: Dict mapping cell coordinates to their actual background colors
        expected: Dict with 'expected_color' (hex RGB string) and 'weekday_cells' (list of cell coordinates)
        **options: Additional options including 'color_tolerance' for fuzzy matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_color = expected.get('expected_color', 'FF0000FF')
    weekday_cells = expected.get('weekday_cells', [])
    color_tolerance = options.get('color_tolerance', 20)
    strict_color_match = options.get('strict_color_match', False)
    if not weekday_cells:
        return 0.0

    def colors_match(color1: str, color2: str) -> bool:
        """Check if two RGB hex colors match (with optional tolerance)."""
        if not color1 or not color2:
            return False
        if len(color1) == 8:
            color1 = color1[2:]
        if len(color2) == 8:
            color2 = color2[2:]
        if strict_color_match:
            return color1.upper() == color2.upper()
        try:
            (r1, g1, b1) = (int(color1[0:2], 16), int(color1[2:4], 16), int(color1[4:6], 16))
            (r2, g2, b2) = (int(color2[0:2], 16), int(color2[2:4], 16), int(color2[4:6], 16))
            distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
            return distance <= color_tolerance
        except (ValueError, IndexError):
            return False
    correct_count = 0
    for cell_coord in weekday_cells:
        actual_color = result.get(cell_coord)
        if actual_color and colors_match(actual_color, expected_color):
            correct_count += 1
    score = correct_count / len(weekday_cells)
    return score

def check_xlsx_conditional_colors__5ae23d3f4f11b8f1328416ec40bcd398(result, expected, **options):
    """Check if cells are colored according to conditional formatting rules.

    Args:
        result: dict mapping row numbers to RGB color values
        expected: dict with 'rules' containing color ranges
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    rules = expected
    color_map = rules.get('color_map', {})
    marks_data = rules.get('marks_data', {})
    if not color_map or not marks_data:
        return 0.0
    color_tolerance = options.get('color_tolerance', 20)
    correct = 0
    total = 0
    for (row_str, mark) in marks_data.items():
        row = int(row_str)
        if mark == '--' or mark is None:
            continue
        total += 1
        expected_color = None
        if mark >= 75:
            expected_color = color_map.get('high')
        elif mark >= 50:
            expected_color = color_map.get('medium')
        else:
            expected_color = color_map.get('low')
        if not expected_color:
            continue
        actual_color = result.get(row)
        if actual_color:
            if actual_color == expected_color:
                correct += 1
            elif color_tolerance > 0:
                if _colors_similar(actual_color, expected_color, color_tolerance):
                    correct += 1
    return correct / total if total > 0 else 0.0

