def check_xlsx_passfail_logic__c664323443307fc5d8f0574c96ba787f(result: Dict[int, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Pass/Fail/Held values are correctly filled based on marks.

    Rule: >= 50 = Pass, 1-49 = Fail, '--' or None = Held

    Args:
        result: Dict mapping row_number -> {'mark': value_from_C, 'status': value_from_D}
        expected: Dict with 'expected_marks' - mapping row_number -> expected mark value

    Returns:
        Score between 0.0 and 1.0 (percentage of correct rows)
    """
    expected_marks = expected.get('expected_marks', {})
    if not expected_marks:
        return 0.0
    total_rows = len(expected_marks)
    correct_rows = 0
    for (row_num_str, expected_mark) in expected_marks.items():
        row_num = int(row_num_str) if isinstance(row_num_str, str) else row_num_str
        row_data = result.get(row_num)
        if row_data is None:
            continue
        actual_mark = row_data.get('mark')
        actual_status = row_data.get('status')
        if expected_mark == '--' or expected_mark is None:
            expected_status = 'Held'
        else:
            try:
                mark_value = int(expected_mark) if isinstance(expected_mark, str) else expected_mark
                if mark_value >= 50:
                    expected_status = 'Pass'
                elif 1 <= mark_value <= 49:
                    expected_status = 'Fail'
                else:
                    expected_status = 'Held'
            except (ValueError, TypeError):
                expected_status = 'Held'
        if actual_status is not None:
            actual_status_norm = str(actual_status).strip()
        else:
            actual_status_norm = None
        if actual_status_norm == expected_status:
            correct_rows += 1
    return correct_rows / total_rows if total_rows > 0 else 0.0

