def check_xlsx_row_content__c9cd07a3e7dacdad8a88760b0cbbf256(result: dict, expected: dict, **options) -> float:
    """
    Check if row content matches expected values.

    Args:
        result: Row data dict from getter function
        expected: Expected rules dict with field checks
        **options: Additional options

    Returns:
        float: Partial credit score based on matching fields
    """
    if not result:
        return 0.0
    required_fields = expected.get('required_fields', [])
    if not required_fields:
        return 0.0
    matches = 0
    total_checks = len(required_fields)
    for field_check in required_fields:
        field_name = field_check.get('field')
        expected_value = field_check.get('value')
        check_type = field_check.get('type', 'exact')
        if field_name in result:
            actual_value = result[field_name]
            if check_type == 'exact':
                if actual_value == expected_value:
                    matches += 1
            elif check_type == 'contains':
                if expected_value and actual_value and (str(expected_value).lower() in str(actual_value).lower()):
                    matches += 1
            elif check_type == 'exists':
                if actual_value is not None:
                    matches += 1
    if total_checks == 0:
        return 0.0
    return matches / total_checks

def check_python_file_with_cell_markers__3b7fbcc9bcd509e2386e3dc8ef7407df(result, expected, **options):
    """
    Check if Python file contains cell markers (# Cell 1, # Cell 2, etc.)
    and has valid Python content.

    Args:
        result: File content string from getter
        expected: Rules dict with validation parameters
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    if result and len(result.strip()) > 0:
        score += 0.3
    else:
        return 0.0
    min_cells = expected.get('min_cells', 1)
    cell_pattern = re.compile('#\\s*Cell\\s+\\d+')
    cell_matches = cell_pattern.findall(result)
    if len(cell_matches) >= min_cells:
        score += 0.4
    lines = result.split('\n')
    code_lines = [line.strip() for line in lines if line.strip() and (not line.strip().startswith('#'))]
    if len(code_lines) > 0:
        score += 0.3
    return score

def check_xlsx_cell_value__0162836c0e06cd4043433024edace06b(result, expected, **options):
    """Compare cell formula and value against expected value.

    Args:
        result: dict with 'formula' and 'value' keys from getter
        expected: Expected value (from rules dict)
        **options: Additional options (tolerance for numeric comparison)

    Returns:
        float: 1.0 if both formula check and value check pass, 0.0 otherwise
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    value = result.get('value')
    if formula is None:
        return 0.0
    formula_upper = str(formula).upper()
    if 'AVERAGE' not in formula_upper:
        return 0.0
    if 'B2:B20' not in formula_upper:
        return 0.0
    if value is None:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    if isinstance(value, (int, float)) and isinstance(expected, (int, float)):
        if abs(value - expected) <= tolerance:
            return 1.0
        else:
            return 0.0
    if value == expected:
        return 1.0
    return 0.0

def check_xlsx_cell_value__3d0a4b14(result, expected, **options):
    """Check if a cell value matches expected value with tolerance and formatting.

    Verifies that the cell contains:
    1. A numeric value close to the expected value (within tolerance)
    2. Proper formatting to display 2 decimal places

    This ensures both the calculated value is correct AND the cell is formatted
    as required by the instruction.

    Args:
        result: Dict from getter with keys:
            - 'value': Cell value (should be a number)
            - 'number_format': Cell number format string
            - 'decimal_places': Number of decimal places (if determinable)
        expected: Expected numeric value (e.g., 0.68)
        **options:
            - tolerance: for numeric comparison (default 0.01)
            - required_decimal_places: required number of decimal places (default 2)

    Returns:
        float: 1.0 if result matches value AND formatting requirements, 0.0 otherwise
    """
    tolerance = options.get('tolerance', 0.01)
    required_decimal_places = options.get('required_decimal_places', 2)
    if result is None or not isinstance(result, dict):
        return 0.0
    cell_value = result.get('value')
    decimal_places = result.get('decimal_places')
    if cell_value is None:
        return 0.0
    try:
        result_num = float(cell_value)
        expected_num = float(expected)
        if abs(result_num - expected_num) > tolerance:
            return 0.0
    except (ValueError, TypeError):
        return 0.0
    number_format = result.get('number_format', '')
    if decimal_places == required_decimal_places:
        return 1.0
    if required_decimal_places == 2:
        if isinstance(number_format, str) and '.00' in number_format and ('.000' not in number_format):
            return 1.0
    return 0.0

