def check_pptx_table_cells__538456b7(result, expected, **options):
    """Compare PowerPoint table cell values against expected values.
    
    Args:
        result: Dict from getter with {(row,col): text} mappings
        expected: Dict from rules with 'cells' list containing expected values
        **options: Additional options (unused)
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    cells_expected = expected.get('cells', [])
    if not cells_expected:
        return 0.0
    total_cells = len(cells_expected)
    correct_cells = 0
    for cell_spec in cells_expected:
        row = cell_spec['row']
        col = cell_spec['col']
        expected_value = cell_spec['value']
        key = f'{row},{col}'
