def check_xlsx_content__1eac1e90(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Excel table content matches expected values.

    Args:
        result: Table data from getter (list of lists)
        expected: Expected configuration with validation rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not result:
        return 0.0
    expected_header = expected.get('header', [])
    expected_rows = expected.get('rows', [])
    if not expected_rows:
        return 0.0
    if len(result) < 1:
        return 0.0
    actual_header = result[0] if result else []
    if expected_header:
        if len(actual_header) != len(expected_header):
            return 0.0
        for (idx, expected_col) in enumerate(expected_header):
            if idx >= len(actual_header):
                return 0.0
            actual_col = actual_header[idx]
            if actual_col != expected_col:
                return 0.0
    data_rows = result[1:] if len(result) > 1 else []
    if len(data_rows) != len(expected_rows):
        return 0.0
    score = 0.0
    points_per_row = 1.0 / len(expected_rows) if expected_rows else 0.0
    for (idx, actual_row) in enumerate(data_rows):
        if idx >= len(expected_rows):
            break
        expected_row = expected_rows[idx]
        row_matches = True
        for (col_idx, expected_val) in enumerate(expected_row):
            if col_idx >= len(actual_row):
                row_matches = False
                break
            actual_val = actual_row[col_idx]
            if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                if col_idx == 3:
                    if abs(float(actual_val) - float(expected_val)) > 0.01:
                        row_matches = False
                        break
                    if float(actual_val) < 1.0 and float(expected_val) > 1.0:
                        row_matches = False
                        break
                elif abs(float(actual_val) - float(expected_val)) > 0.01:
                    row_matches = False
                    break
            elif actual_val != expected_val:
                row_matches = False
                break
        if row_matches:
            score += points_per_row
    return round(score, 2)

def check_xlsx_grades_5aa3134d(result, expected, **options):
    """Check header and verify grading logic for all cells E2:E29

    Args:
        result: Dict containing header, marks, and grades extracted from vm_file
        expected: Dict with expected header_value and grading rules
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    score = 0.0
    expected_header = expected.get('header_value', '')
    if result.get('header') == expected_header:
        score += 0.2
    marks = result.get('marks', {})
    grades = result.get('grades', {})
    if not marks or not grades:
        return score

    def get_expected_grade(mark):
        """Determine expected grade based on mark value"""
        if mark is None:
            return None
        try:
            mark_val = float(mark)
            if mark_val >= 80:
                return 'A'
            elif mark_val >= 60:
                return 'B'
            elif mark_val >= 40:
                return 'C'
            elif mark_val >= 20:
                return 'D'
            else:
                return 'F'
        except (ValueError, TypeError):
            return None
    correct = 0
    total = 0
    for row in range(2, 30):
        mark_cell = f'D{row}'
        grade_cell = f'E{row}'
        mark_value = marks.get(mark_cell)
        grade_value = grades.get(grade_cell)
        if mark_value is not None:
            total += 1
            expected_grade = get_expected_grade(mark_value)
            if grade_value == expected_grade:
                correct += 1
    if total > 0:
        score += 0.8 * (correct / total)
    return score

