def check_xlsx_sheet_movies_1970s__c777e6f03caa3a1491570ab4756cb683(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if a sheet contains movies from 1970s sorted by rating.

    Args:
        result: List of rows from the Excel sheet (from getter)
        expected: Dict with 'start_year', 'end_year', 'expected_count'
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or len(result) < 2:
        return 0.0
    start_year = expected.get('start_year', 1970)
    end_year = expected.get('end_year', 1980)
    expected_count = expected.get('expected_count', None)
    score = 0.0
    header = result[0]
    expected_header = ['title', 'release year', 'ratings', 'description']
    if header[:4] == expected_header:
        score += 0.3
    else:
        return 0.0
    data_rows = result[1:]
    all_years_valid = True
    for row in data_rows:
        if len(row) < 2:
            all_years_valid = False
            break
        year = row[1]
        if year is None:
            all_years_valid = False
            break
        try:
            year_int = int(year)
            if not start_year <= year_int < end_year:
                all_years_valid = False
                break
        except (ValueError, TypeError):
            all_years_valid = False
            break
    if all_years_valid:
        score += 0.3
    else:
        return score
    ratings = []
    for row in data_rows:
        if len(row) >= 3 and row[2] is not None:
            try:
                ratings.append(float(row[2]))
            except (ValueError, TypeError):
                continue
    if not ratings:
        return score
    is_sorted = all((ratings[i] >= ratings[i + 1] for i in range(len(ratings) - 1)))
    if is_sorted:
        score += 0.2
    else:
        return score
    if expected_count is not None:
        if len(data_rows) == expected_count:
            score += 0.2
        else:
            return score
    return 1.0

