def check_calc_numeric_value__a5c05c93f424530f80ec4e47a5eb0028(result, expected, **options):
    """Check if cell contains correct SUM formula and calculated value.

    Args:
        result: dict with 'formula' and 'value' keys from getter
        expected: dict with 'value' key for expected numeric result
        **options: Additional options including 'tolerance'

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    cell_value = result.get('value')
    if formula is None:
        return 0.0
    if not isinstance(formula, str) or not formula.startswith('='):
        return 0.0
    formula_normalized = formula.upper().replace(' ', '')
    if 'SUM' not in formula_normalized:
        return 0.0
    sum_pattern = 'SUM\\(\\$?B\\$?2:\\$?B\\$?5\\)'
    if not re.search(sum_pattern, formula_normalized):
        return 0.0
    if cell_value is None:
        return 0.0
    try:
        result_value = float(cell_value)
    except (ValueError, TypeError):
        return 0.0
    expected_value = expected.get('value')
    if expected_value is None:
        return 0.0
    try:
        expected_value = float(expected_value)
    except (ValueError, TypeError):
        return 0.0
    tolerance = options.get('tolerance', 0.001)
    abs_tolerance = abs(expected_value * tolerance)
    if abs(result_value - expected_value) <= abs_tolerance:
        return 1.0
    else:
        return 0.0

