def check_xlsx_header_format__5c61a707(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if header cells have bold font and light blue background color."""
    if result is None:
        return 0.0
    try:
        sheet_idx = expected.get('sheet', 0)
        header_cells = expected.get('header_cells', [])
        is_bold = expected.get('is_bold', True)
        has_background = expected.get('has_background', True)
        expected_color = expected.get('expected_color', (173, 216, 230))
        color_tolerance = expected.get('color_tolerance', 30)
        strict_color_match = expected.get('strict_color_match', False)
        if isinstance(sheet_idx, int):
            ws = result.worksheets[sheet_idx]
        else:
            ws = result[sheet_idx]
        if not header_cells:
            result.close()
            return 0.0
        bold_count = 0
        bg_count = 0
        for cell_addr in header_cells:
            cell = ws[cell_addr]
            if cell.font and cell.font.bold:
                bold_count += 1
            if cell.fill and hasattr(cell.fill, 'fgColor'):
                fg_color = cell.fill.fgColor
                cell_rgb = _parse_rgb_color(fg_color)
                if cell_rgb is not None:
                    distance = _color_distance(cell_rgb, expected_color)
                    if strict_color_match:
                        if distance == 0:
                            bg_count += 1
                    elif distance <= color_tolerance:
                        bg_count += 1
        score = 0.0
        if is_bold:
            score += bold_count / len(header_cells) * 0.5
        if has_background:
            score += bg_count / len(header_cells) * 0.5
        result.close()
        return score
    except Exception:
        if result:
            try:
                result.close()
            except:
                pass
        return 0.0

