def check_xlsx_formula_results__3d0a4b14(result, expected, **options):
    """Check if formula results match expected values.

    Args:
        result: Dict with cell addresses and their values
        expected: Dict with expected cell values
        **options: Additional options including tolerance

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    cells_to_check = expected.get('cells', [])
