    for cell_addr in cells_to_check:
        if cell_addr in result and cell_addr in expected:
            try:
                result_val = float(result[cell_addr])
                expected_val = float(expected[cell_addr])
                if abs(result_val - expected_val) <= tolerance:
                    score += score_per_cell
            except (ValueError, TypeError):
                pass
    return score

