def check_xlsx_first_day_highlights__f5c8911b3cca16f0878e0d65734b3523(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if ONLY first-day-of-month cells are highlighted with the expected color.

    Args:
        result: Dict with 'first_day_colors' and 'non_first_day_colors' from getter
        expected: Dict with 'expected_color' (hex RGB string) and 'first_day_cells' (list of cell coordinates)
        **options: Additional options including 'color_tolerance' for fuzzy matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_color = expected.get('expected_color', 'FF00FF00')
    first_day_cells = expected.get('first_day_cells', [])
    color_tolerance = options.get('color_tolerance', 20)
    strict_color_match = options.get('strict_color_match', False)
    if not first_day_cells:
        return 0.0
    first_day_colors = result.get('first_day_colors', {})
    non_first_day_colors = result.get('non_first_day_colors', {})

    def colors_match(color1: str, color2: str) -> bool:
        """Check if two RGB hex colors match (with optional tolerance)."""
        if not color1 or not color2:
            return False
        if len(color1) == 8:
            color1 = color1[2:]
        if len(color2) == 8:
            color2 = color2[2:]
        if strict_color_match:
            return color1.upper() == color2.upper()
        try:
            (r1, g1, b1) = (int(color1[0:2], 16), int(color1[2:4], 16), int(color1[4:6], 16))
            (r2, g2, b2) = (int(color2[0:2], 16), int(color2[2:4], 16), int(color2[4:6], 16))
            distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
            return distance <= color_tolerance
        except (ValueError, IndexError):
            return False
    correct_highlights = 0
    for cell_coord in first_day_cells:
        actual_color = first_day_colors.get(cell_coord)
        if actual_color and colors_match(actual_color, expected_color):
            correct_highlights += 1
    if correct_highlights < len(first_day_cells):
        return correct_highlights / len(first_day_cells) * 0.5
    for (cell_coord, color) in first_day_colors.items():
        if color and colors_match(color, expected_color):
            if cell_coord not in first_day_cells:
                return 0.5
    for (cell_coord, color) in non_first_day_colors.items():
        if color and colors_match(color, expected_color):
            return 0.0
    return 1.0

def check_xlsx_data_completeness__474c917112587e81f547539c35fd0dc4(result: Dict[str, int], expected: dict, **options) -> float:
    """Check if all columns have minimum required data.

    Args:
        result: Dictionary with column names and their non-empty cell counts
        expected: Expected rules dict with 'min_rows_per_column' key
        **options: Additional options

    Returns:
        float: Score based on how many columns meet the minimum requirement
    """
    min_rows = expected.get('min_rows_per_column', 1)
    required_columns = expected.get('required_columns', [])
    if not required_columns:
        required_columns = list(result.keys())
    passing_count = 0
    for col in required_columns:
        if result.get(col, 0) >= min_rows:
            passing_count += 1
    if len(required_columns) == 0:
        return 1.0
    return passing_count / len(required_columns)

def check_xlsx_sheet_top_movies__d36402da007fc0db68f4bce9a44252b7(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if a sheet contains top N movies sorted by rating.

    Args:
        result: List of rows from the Excel sheet (from getter)
        expected: Dict with 'top_n', 'expected_count'
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or len(result) < 2:
        return 0.0
    top_n = expected.get('top_n', 10)
    expected_count = expected.get('expected_count', top_n)
    score = 0.0
    header = result[0]
    expected_header = ['title', 'release year', 'ratings', 'description']
    if header[:4] == expected_header:
        score += 0.3
    else:
        return 0.0
    data_rows = result[1:]
    if len(data_rows) == expected_count:
        score += 0.3
    else:
        return score
    ratings = [float(row[2]) for row in data_rows if row[2] is not None]
    is_sorted = all((ratings[i] >= ratings[i + 1] for i in range(len(ratings) - 1)))
    if is_sorted:
        score += 0.4
    else:
        return score
    return 1.0

