def check_xlsx_avg_column__e1dac4b830cceebc6b82508d5a29d2a3(result, expected, **options):
    """Check if average column header and values are correct.

    Args:
        result: Dictionary with 'header' (str) and 'averages' (dict mapping row indices to values)
        expected: Dictionary of expected averages per row
        **options: Additional options (tolerance for float comparison)

    Returns:
        float: Score between 0.0 and 1.0
            - 0.1 for correct header
            - 0.9 for correct average values (proportional)
    """
    if not result:
        return 0.0
    tolerance = options.get('tolerance', 1.0)
    expected_averages = expected.get('averages', {})
    header_score = 0.0
    result_header = result.get('header', '')
    if result_header and isinstance(result_header, str):
        if result_header.strip().lower() == 'average':
            header_score = 0.1
    avg_score = 0.0
    result_averages = result.get('averages', {})
    total_checks = len(expected_averages)
    if total_checks == 0:
        return header_score
    correct_count = 0
    for (row_idx_str, expected_avg) in expected_averages.items():
        row_idx = int(row_idx_str)
        if row_idx in result_averages:
            actual_avg = result_averages[row_idx]
            if actual_avg is not None:
                try:
                    actual_float = float(actual_avg)
                    expected_float = float(expected_avg)
                    if abs(actual_float - expected_float) <= tolerance:
                        correct_count += 1
                except (ValueError, TypeError):
                    pass
    avg_score = correct_count / total_checks * 0.9
    return header_score + avg_score

