def check_calc_chart__6d53c98d6c4b8d6ad256907b7e9092b3(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the chart matches expected properties including data verification.

    Args:
        result: Dict from getter with 'charts' list
        expected: Expected chart properties (from rules)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'charts' not in result:
        return 0.0
    charts = result.get('charts', [])
    if not charts:
        return 0.0
    expected_sheet_name = expected.get('sheet_name', '')
    expected_chart_type = expected.get('chart_type', '')
    expected_title = expected.get('chart_title', '')
    expected_data_column = expected.get('data_column_name', '')
    expected_data_row_count = expected.get('data_row_count', 0)
    score = 0.0
    for chart in charts:
        chart_score = 0.0
        if expected_sheet_name and chart.get('sheet_name', '') == expected_sheet_name:
            chart_score += 0.25
        elif not expected_sheet_name:
            chart_score += 0.25
        if expected_chart_type and chart.get('chart_type', '') == expected_chart_type:
            chart_score += 0.25
        elif not expected_chart_type:
            chart_score += 0.25
        if expected_title and chart.get('chart_title', '') == expected_title:
            chart_score += 0.25
        elif not expected_title:
            chart_score += 0.25
        if expected_data_column:
            data_column_names = chart.get('data_column_names', [])
            if expected_data_column in data_column_names:
                chart_score += 0.125
        else:
            chart_score += 0.125
        if expected_data_row_count > 0:
            actual_row_count = chart.get('data_row_count', 0)
            if actual_row_count == expected_data_row_count:
                chart_score += 0.125
        else:
            chart_score += 0.125
        score = max(score, chart_score)
    return score

