def check_calc_missing_data_highlight__5dfbbc9a(result, expected, **options):
    """Check if cells with missing data are highlighted in the expected color.

    Args:
        result: Path to the Excel file
        expected: Dict with 'missing_clockin_rows', 'employee_col', 'expected_color'
        **options: Additional options

    Returns:
        float: Score based on partial credit for highlighted cells
    """
    if not os.path.exists(result):
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        sheet_idx = expected.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        missing_rows = expected.get('missing_clockin_rows', [])
        employee_col = expected.get('employee_col', 'B')
        expected_color = expected.get('expected_color', 'red').lower()
        if not missing_rows:
            return 0.0
        highlighted_count = 0
        for row_num in missing_rows:
            cell = ws[f'{employee_col}{row_num}']
            if cell.fill and cell.fill.patternType is not None and (cell.fill.patternType != 'none'):
                if cell.fill.fgColor and hasattr(cell.fill.fgColor, 'rgb'):
                    rgb = cell.fill.fgColor.rgb
                    if rgb:
                        hex_color = rgb[-6:] if len(rgb) == 8 else rgb
                        r = int(hex_color[0:2], 16)
                        g = int(hex_color[2:4], 16)
                        b = int(hex_color[4:6], 16)
                        if expected_color == 'red':
                            if r > 200 and g < 100 and (b < 100):
                                highlighted_count += 1
                            else:
                                highlighted_count += 0.5
        wb.close()
        score = highlighted_count / len(missing_rows)
        return min(1.0, score)
    except Exception as e:
        print(f'Error checking missing data highlight: {e}')
        return 0.0

