def check_xlsx_time_value__3515efdc(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if the cell value matches the expected time value.

    Args:
        result: The actual cell value from getter (can be time, datetime, or string)
        expected: Dict with 'time_value' key containing expected time as "HH:MM" string
        **options: Additional options

    Returns:
        1.0 if time values match, 0.0 otherwise
    """
    expected_time_str = expected.get('time_value', '')
    if result is None:
        return 0.0
    try:
        expected_parts = expected_time_str.split(':')
        expected_hour = int(expected_parts[0])
        expected_minute = int(expected_parts[1])
    except:
        return 0.0
    if isinstance(result, datetime.time):
        if result.hour == expected_hour and result.minute == expected_minute:
            return 1.0
        return 0.0
    if isinstance(result, datetime.datetime):
        if result.hour == expected_hour and result.minute == expected_minute:
            return 1.0
        return 0.0
    result_str = str(result).strip()
    if ':' in result_str:
        try:
            parts = result_str.split(':')
            hour_part = parts[0].strip()
            minute_part = parts[1].strip()[:2]
            result_hour = int(hour_part)
            result_minute = int(minute_part)
            if result_hour == expected_hour and result_minute == expected_minute:
                return 1.0
        except:
            pass
    if result_str == expected_time_str:
        return 1.0
    if result_str == f'{expected_hour:02d}:{expected_minute:02d}':
        return 1.0
    return 0.0

