def check_xlsx_highlighting__e25bf6ec(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if correct cells are highlighted with correct color and no other cells are modified.

    The instruction states: 'Do not modify any other cells'
    This means we need to check:
    1. All expected cells are highlighted with the correct color
    2. NO unexpected cells are highlighted (to verify 'do not modify any other cells')

    Args:
        result: Result from getter (dict with 'highlighted_cells')
        expected: Expected cells and color from rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'highlighted_cells' not in result:
        return 0.0
    expected_cells = set(expected.get('cells', []))
    expected_color = expected.get('color', '').lower().replace('#', '')
    highlighted = result['highlighted_cells']
    correct_count = 0
    unexpected_count = 0
    highlighted_set = set()
    for item in highlighted:
        cell_addr = item['cell']
        cell_color = item.get('color', '').lower()
        highlighted_set.add(cell_addr)
        if cell_addr in expected_cells:
            if cell_color == expected_color:
                correct_count += 1
        else:
            unexpected_count += 1
    total_expected = len(expected_cells)
    if total_expected == 0:
        return 1.0
    correct_ratio = correct_count / total_expected
    if unexpected_count > 0:
        penalty = min(1.0, unexpected_count / total_expected)
        score = max(0.0, correct_ratio - penalty)
    else:
        score = correct_ratio
    return min(1.0, max(0.0, score))

def check_xlsx_range_border__a4dde445(result_state, expected_state, **options):
    """Check if border coverage meets the minimum threshold.

    Args:
        result_state: Float representing the border coverage ratio (0.0 to 1.0)
        expected_state: Dict containing 'min_coverage' threshold (when type='rule', this IS the rules dict)
        **options: Additional options

    Returns:
        float: 1.0 if border coverage meets minimum threshold, 0.0 otherwise
    """
    try:
        coverage_ratio = float(result_state)
        min_coverage = float(expected_state.get('min_coverage', 0.5))
        logger.info(f'Border coverage check: {coverage_ratio:.2%} vs min {min_coverage:.2%}')
        if coverage_ratio >= min_coverage:
            logger.info(f'Border coverage sufficient: {coverage_ratio:.2%} >= {min_coverage:.2%}')
            return 1.0
        else:
            logger.warning(f'Border coverage insufficient: {coverage_ratio:.2%} < {min_coverage:.2%}')
            return 0.0
    except (ValueError, TypeError, KeyError) as e:
        logger.error(f'Error checking border coverage: {e}')
        return 0.0

def check_xlsx_formula_results__e64652ba(result, expected, **options):
    """Check if column has correct header and formulas.

    Args:
        result: Dict with 'header' and 'formulas' from getter
        expected: Dict with 'header' and 'formula_pattern' (e.g., 'A*C' for A2*C2, A3*C3, etc.)
        **options: None used currently

    Returns:
        float: Score (0.0 to 1.0) based on header and formula correctness
    """
    import re
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    total_checks = 2
    result_header = result.get('header')
    expected_header = expected.get('header')
    if result_header and expected_header:
        if str(result_header).strip() == str(expected_header).strip():
            score += 0.5
    formulas = result.get('formulas', [])
    if not formulas:
        return score
    pattern = expected.get('formula_pattern', '')
    start_row = expected.get('start_row', 2)
    if not pattern:
        return score
    correct_formulas = 0
    total_formulas = len(formulas)
    for (i, formula) in enumerate(formulas):
        row = start_row + i
        if formula is None:
            continue
        formula_str = str(formula).strip().upper()
        expected_formula = f'=A{row}*C{row}'
        expected_formula_normalized = expected_formula.upper().replace(' ', '')
        formula_normalized = formula_str.replace(' ', '')
        if formula_normalized == expected_formula_normalized:
            correct_formulas += 1
    if total_formulas > 0:
        score += 0.5 * (correct_formulas / total_formulas)
    return score

