def check_xlsx_cell_value__a448e382(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if a cell in Excel file contains the expected value.
    
    Args:
        result: Path to Excel file (from getter)
        expected: Rules dict with 'sheet', 'cell', and 'value' keys
        **options: Additional options
        
    Returns:
        1.0 if cell value matches expected, 0.0 otherwise
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        cell_address = expected.get('cell', 'A1')
        expected_value = expected.get('value')
        tolerance = expected.get('tolerance', 0.0)
        wb = openpyxl.load_workbook(result, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_value = ws[cell_address].value
        if expected_value is None:
            return 1.0 if cell_value is None else 0.0
        if isinstance(expected_value, (int, float)) and isinstance(cell_value, (int, float)):
            if abs(cell_value - expected_value) <= tolerance:
                return 1.0
            return 0.0
        if isinstance(expected_value, str) and isinstance(cell_value, str):
            if expected_value.lower() == cell_value.lower():
                return 1.0
            return 0.0
        if cell_value == expected_value:
            return 1.0
        return 0.0
    except Exception as e:
        print(f'Error in check_xlsx_cell_value__a448e382: {e}')
        return 0.0
    finally:
        import os
        if os.path.exists(result):
            try:
                os.unlink(result)
            except:
                pass

def check_cell_value__1678fa3a(result, expected, **options):
    """Verify that the cell contains a COUNTIF formula with correct criteria."""
    if result is None:
        return 0.0
    if not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    if not formula:
        return 0.0
    formula_upper = formula.upper().replace(' ', '')
    if not formula_upper.startswith('=COUNTIF'):
        return 0.0
    if 'WEBSITESALES' not in formula_upper and '"WEBSITESALES"' not in formula_upper:
        return 0.0
    value = result.get('value')
    if value is not None:
        tolerance = options.get('tolerance', 0.01)
        if isinstance(expected, (int, float)) and isinstance(value, (int, float)):
            if abs(value - expected) > tolerance:
                return 0.5
        elif value != expected:
            return 0.5
    return 1.0

def check_calc_chart_creation__2bd59342(result_state: Dict[str, Any], expected_state: List[str], **options) -> float:
    """
    Check if column charts were created for each order ID in LibreOffice Calc file.

    This verification checks:
    1. File exists and was successfully loaded
    2. File has expected structure (Order ID, Jan, Feb, Mar, Chart columns)
    3. Number of charts matches number of order IDs (one chart per order)
    4. Charts are column charts (not bar/line/pie)
    5. Charts reference the correct data columns (Jan, Feb, Mar)

    Args:
        result_state: Data from getter (file structure, chart count, chart types)
        expected_state: List of expected rules (empty list means dynamic validation)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 indicating verification confidence
    """
    if not result_state.get('exists', False):
        return 0.0
    if 'error' in result_state:
        if 'openpyxl not available' in result_state.get('error', ''):
            return 0.3
        return 0.0
    score = 0.0
    expected_chart_count = result_state.get('order_id_count', 0)
    if expected_chart_count == 0:
        return 0.0
    if result_state.get('has_expected_structure', False):
        score += 0.15
    if result_state.get('has_chart_column', False):
        score += 0.1
    if result_state.get('has_jan_feb_mar_cols', False):
        score += 0.1
    chart_count = result_state.get('chart_count', 0)
    if chart_count == expected_chart_count:
        score += 0.4
    elif chart_count > 0:
        ratio = min(chart_count / expected_chart_count, 1.0)
        score += 0.4 * ratio
    column_chart_count = result_state.get('column_chart_count', 0)
    if column_chart_count == expected_chart_count:
        score += 0.15
    elif column_chart_count > 0 and chart_count > 0:
        ratio = min(column_chart_count / chart_count, 1.0)
        score += 0.15 * ratio
    charts_with_correct_data = result_state.get('charts_with_correct_data', 0)
    if charts_with_correct_data > 0:
        if chart_count > 0:
            ratio = min(charts_with_correct_data / chart_count, 1.0)
            score += 0.1 * ratio
    chart_cells_with_content = result_state.get('chart_cells_with_content', 0)
    if chart_count == 0 and chart_cells_with_content >= expected_chart_count * 0.5:
        score = max(score, 0.5)
    return min(score, 1.0)

