def check_thunderbird_email_xlsx__77b589a7(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Validate Thunderbird email extraction XLSX file.

    Args:
        result: Path to result XLSX file
        expected: Dict with 'email_data' (list of lists) and 'columns' (list of column names)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.active
        expected_data = expected.get('email_data', [])
        expected_columns = expected.get('columns', [])
        num_emails = len(expected_data)
        num_cols = len(expected_columns)
        if ws.max_row < num_emails + 1:
            return 0.0
        score = 0.0
        total_checks = num_emails * num_cols
        correct_checks = 0
        date_values = []
        date_col_idx = None
        folder_col_idx = None
        if 'date' in expected_columns:
            date_col_idx = expected_columns.index('date')
        if 'folder' in expected_columns:
            folder_col_idx = expected_columns.index('folder')
        for row_idx in range(num_emails):
            expected_row = expected_data[row_idx]
            actual_row_idx = row_idx + 2
            for col_idx in range(num_cols):
                cell_value = ws.cell(actual_row_idx, col_idx + 1).value
                expected_value = expected_row[col_idx]
                if cell_value is not None:
                    cell_value_str = str(cell_value).strip()
                else:
                    cell_value_str = ''
                expected_value_str = str(expected_value).strip()
                if cell_value_str == expected_value_str:
                    correct_checks += 1
                if col_idx == date_col_idx and row_idx == 0:
                    pass
        if date_col_idx is not None:
            for row_idx in range(num_emails):
                actual_row_idx = row_idx + 2
                cell_value = ws.cell(actual_row_idx, date_col_idx + 1).value
                if cell_value is not None:
                    date_values.append(str(cell_value).strip())
                else:
                    date_values.append('')
        date_ordering_correct = True
        if date_col_idx is not None and len(date_values) > 1:
            try:
                parsed_dates = []
                for date_str in date_values:
                    if date_str:
                        for fmt in ['%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y', '%Y/%m/%d']:
                            try:
                                parsed_date = datetime.strptime(date_str, fmt)
                                parsed_dates.append(parsed_date)
                                break
                            except ValueError:
                                continue
                if len(parsed_dates) == len(date_values):
                    for i in range(len(parsed_dates) - 1):
                        if parsed_dates[i] > parsed_dates[i + 1]:
                            date_ordering_correct = False
                            break
                else:
                    for i in range(len(date_values) - 1):
                        if date_values[i] > date_values[i + 1]:
                            date_ordering_correct = False
                            break
            except Exception:
                for i in range(len(date_values) - 1):
                    if date_values[i] > date_values[i + 1]:
                        date_ordering_correct = False
                        break
        score = correct_checks / total_checks if total_checks > 0 else 0.0
        if not date_ordering_correct:
            score = score * 0.5
        if folder_col_idx is not None:
            folder_verification_passed = True
            for row_idx in range(num_emails):
                actual_row_idx = row_idx + 2
                cell_value = ws.cell(actual_row_idx, folder_col_idx + 1).value
                if cell_value is not None:
                    folder_value = str(cell_value).strip().lower()
                else:
                    folder_value = ''
                if folder_value != 'daily':
                    folder_verification_passed = False
                    break
            if not folder_verification_passed:
                score = score * 0.3
        return score
    except Exception as e:
        return 0.0

