def check_xlsx_sheet_sorted__e05342d5(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if Excel sheet has correct headers, row count, is sorted correctly, and meets filtering criteria.

    Scoring breakdown:
    - headers_match: 0.15 - Headers match expected (case-insensitive, order matters)
    - min_rows_present: 0.15 - At least minimum number of rows present
    - exact_row_count: 0.15 - Exactly the expected number of rows
    - rating_filter_correct: 0.25 - All ratings meet the minimum threshold (>= 9.0)
    - sorted_correctly: 0.3 - Data is sorted by the specified column in the specified order

    Args:
        result: Dict with 'headers' and 'rows' from getter
        expected: Dict (rules dict) containing:
            - headers: List of expected header names (case-insensitive)
            - exact_rows: Expected exact number of data rows
            - min_rows: Minimum number of data rows
            - sort_column_idx: Index of column to check sorting (0-based)
            - descending: True for descending sort, False for ascending
            - min_rating: Minimum rating value that all rows must meet (optional)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    rules = expected
    expected_headers = [h.lower().strip() for h in rules.get('headers', [])]
    exact_rows = rules.get('exact_rows')
    min_rows = rules.get('min_rows')
    sort_column_idx = rules.get('sort_column_idx')
    descending = rules.get('descending', False)
    min_rating = rules.get('min_rating')
    score = 0.0
    actual_headers = result.get('headers', [])
    actual_rows = result.get('rows', [])
    if actual_headers == expected_headers:
        score += 0.15
    if min_rows is not None and len(actual_rows) >= min_rows:
        score += 0.15
    if exact_rows is not None and len(actual_rows) == exact_rows:
        score += 0.15
    if min_rating is not None and sort_column_idx is not None and (len(actual_rows) > 0):
        all_ratings_valid = True
        for row in actual_rows:
            if len(row) > sort_column_idx:
                rating_value = row[sort_column_idx]
                try:
                    rating_float = float(rating_value)
                    if rating_float < min_rating:
                        all_ratings_valid = False
                        break
                except (ValueError, TypeError):
                    all_ratings_valid = False
                    break
            else:
                all_ratings_valid = False
                break
        if all_ratings_valid:
            score += 0.25
    if sort_column_idx is not None and len(actual_rows) > 1:
        is_sorted = True
        for i in range(len(actual_rows) - 1):
            curr_value = actual_rows[i][sort_column_idx]
            next_value = actual_rows[i + 1][sort_column_idx]
            if curr_value is None or next_value is None:
                is_sorted = False
                break
            try:
                curr_comp = float(curr_value)
                next_comp = float(next_value)
            except (ValueError, TypeError):
                curr_comp = str(curr_value)
                next_comp = str(next_value)
            if descending:
                if curr_comp < next_comp:
                    is_sorted = False
                    break
            elif curr_comp > next_comp:
                is_sorted = False
                break
        if is_sorted:
            score += 0.3
    elif sort_column_idx is None:
        score += 0.3
    return score

def check_thunderbird_email_xlsx__d62a475e(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Validate Thunderbird email extraction XLSX file.
    
    Args:
        result: Path to result XLSX file
        expected: Dict with 'email_data' (list of lists) and 'columns' (list of column names)
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.active
        expected_data = expected.get('email_data', [])
        expected_columns = expected.get('columns', [])
        num_emails = len(expected_data)
        num_cols = len(expected_columns)
        if ws.max_row < num_emails + 1:
            return 0.0
        total_checks = num_cols + num_emails * num_cols
        correct_checks = 0
        for col_idx in range(num_cols):
            header_value = ws.cell(1, col_idx + 1).value
            expected_header = expected_columns[col_idx]
            if header_value is not None:
                header_value_str = str(header_value).strip().lower()
            else:
                header_value_str = ''
            expected_header_str = str(expected_header).strip().lower()
            if header_value_str == expected_header_str:
                correct_checks += 1
        for row_idx in range(num_emails):
            expected_row = expected_data[row_idx]
            actual_row_idx = row_idx + 2
            for col_idx in range(num_cols):
                cell_value = ws.cell(actual_row_idx, col_idx + 1).value
                expected_value = expected_row[col_idx]
                if cell_value is not None:
                    cell_value_str = str(cell_value).strip()
                else:
                    cell_value_str = ''
                expected_value_str = str(expected_value).strip()
                if cell_value_str == expected_value_str:
                    correct_checks += 1
        score = correct_checks / total_checks if total_checks > 0 else 0.0
        return score
    except Exception as e:
        return 0.0

