def check_calc_highlighted_values__2eb2ccdf8e0d8fb7f34f72dd50211eed(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the correct number of cells with target value are highlighted.

    Args:
        result: Dict with highlighted_values and highlighted_count
        expected: Dict with expected_highlighted_count
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    highlighted_count = result.get('highlighted_count', 0)
    expected_count = expected.get('expected_highlighted_count', 0)
    if expected_count == 0:
        return 1.0 if highlighted_count == 0 else 0.0
    if highlighted_count == expected_count:
        return 1.0
    ratio = min(highlighted_count, expected_count) / max(highlighted_count, expected_count)
    return ratio * 0.7

def check_xlsx_cell_value__f5ca3e24(result_state: Union[float, int, str, None], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if a cell value matches the expected value within a tolerance.

    This function verifies that a numeric value (e.g., average age calculated from birthdates)
    is approximately equal to the expected value.

    Args:
        result_state: The actual value from the cell (can be float, int, str, or None)
        expected_state: Dictionary containing expected 'value' (the rules dict is passed directly when type='rule')
        **options: Additional options including 'tolerance' for numeric comparison

    Returns:
        float: 1.0 if the value matches (within tolerance), 0.0 otherwise
    """
    if result_state is None:
        logger.error('Result state is None - cell may be empty or file not found')
        return 0.0
    if not isinstance(expected_state, dict):
        logger.error(f'Expected state should be a dict, got {type(expected_state)}')
        return 0.0
    expected_value = expected_state.get('value')
    if expected_value is None:
        logger.error('No expected value found in rules')
        return 0.0
    tolerance = options.get('tolerance', 0.0)
    try:
        result_numeric = float(result_state)
        expected_numeric = float(expected_value)
        difference = abs(result_numeric - expected_numeric)
        if difference <= tolerance:
            logger.info(f'Cell value matches: result={result_numeric:.4f}, expected={expected_numeric:.4f}, difference={difference:.4f}, tolerance={tolerance}')
            return 1.0
        else:
            logger.warning(f'Cell value mismatch: result={result_numeric:.4f}, expected={expected_numeric:.4f}, difference={difference:.4f} > tolerance={tolerance}')
            return 0.0
    except (ValueError, TypeError) as e:
        logger.error(f'Error comparing values: {e}. Result: {result_state} ({type(result_state)}), Expected: {expected_value} ({type(expected_value)})')
        return 0.0

def check_calc_sheet_duplication__86bfa89a4b4d2f7a30a182edda1be610(result: Dict[str, Any], expected: Dict, **options) -> float:
    """Check if a sheet was duplicated correctly.

    Args:
        result: Dict with 'count', 'names', and 'duplicates' keys from getter
        expected: Dict with 'original_sheet', 'duplicate_name', and 'expected_count' keys
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    original_sheet = expected.get('original_sheet', '')
    duplicate_name = expected.get('duplicate_name', '')
    expected_count = expected.get('expected_count', 0)
    actual_count = result.get('count', 0)
    actual_names = result.get('names', [])
    duplicates = result.get('duplicates', [])
    if not isinstance(actual_names, list):
        actual_names = []
    if not isinstance(duplicates, list):
        duplicates = []
    score = 0.0
    if actual_count == expected_count:
        score += 0.33
    if duplicate_name in actual_names:
        score += 0.34
        for dup in duplicates:
            if not isinstance(dup, dict):
                continue
            dup_original = dup.get('original', '')
            dup_copy = dup.get('copy', '')
            if dup_original == original_sheet and dup_copy == duplicate_name or (dup_original == duplicate_name and dup_copy == original_sheet):
                score += 0.33
                break
    return score

