def check_xlsx_conditional_bold__5f4b163b(result, expected, **options):
    """Check if cells meeting a condition are bolded.
    
    Args:
        result: Dict from getter with cell data
        expected: Dict from rules with threshold
        
    Returns:
        float: Proportion of correctly formatted cells
    """
    if result is None or expected is None:
        return 0.0
    threshold = expected.get('threshold', 40)
    tolerance = options.get('tolerance', 0.01)
    total_cells = 0
    correct_cells = 0
    for (cell_addr, cell_data) in result.items():
        value = cell_data.get('value')
        is_bold = cell_data.get('is_bold', False)
        if value is None:
            continue
        total_cells += 1
        should_be_bold = value > threshold
        if is_bold == should_be_bold:
            correct_cells += 1
    if total_cells == 0:
        return 0.0
    return correct_cells / total_cells

