def check_xlsx_cell_content__b926b41a(result_state, expected_state, **options):
    """
    Check if specific cells in an XLSX file contain expected content.

    Args:
        result_state: Path to the result XLSX file
        expected_state: Dict with 'sheet' (int) and 'checks' (dict of cell:value pairs)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result_state is None:
        logger.error('Result file path is None')
        return 0.0
    if not os.path.exists(result_state):
        logger.error(f'Result file not found: {result_state}')
        return 0.0
    try:
        logger.info(f'Loading result file: {result_state}')
        workbook: Workbook = openpyxl.load_workbook(filename=result_state)
        logger.info(f'Successfully loaded result file with sheets: {workbook.sheetnames}')
    except Exception as e:
        logger.error(f'Failed to load result file {result_state}: {e}')
        return 0.0
    sheet_idx = expected_state.get('sheet', 0)
    checks = expected_state.get('checks', {})
    if not checks:
        logger.warning('No checks specified in expected state')
        return 1.0
    try:
        sheet_names = workbook.sheetnames
        if isinstance(sheet_idx, int):
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available sheets: {sheet_names}')
                return 0.0
            sheet: Worksheet = workbook[sheet_names[sheet_idx]]
        else:
            sheet: Worksheet = workbook[sheet_idx]
        logger.info(f'Checking cells in sheet: {sheet.title}')
    except Exception as e:
        logger.error(f'Failed to get sheet at index {sheet_idx}: {e}')
        return 0.0
    all_passed = True
    for (cell_coord, expected_value) in checks.items():
        try:
            cell = sheet[cell_coord]
            actual_value = cell.value
            if actual_value != expected_value:
                logger.warning(f"Cell {cell_coord}: expected '{expected_value}', got '{actual_value}'")
                all_passed = False
            else:
                logger.debug(f"Cell {cell_coord}: matches expected value '{expected_value}'")
        except Exception as e:
            logger.error(f'Failed to check cell {cell_coord}: {e}')
            all_passed = False
    if all_passed:
        logger.info('All cell checks passed')
        return 1.0
    else:
        logger.warning('Some cell checks failed')
        return 0.0

