def check_docx_table_cell__95f984dd(result, expected, **options):
    """Compare a docx table cell value against expected value.

    Args:
        result: Cell text extracted by getter
        expected: Expected value (from rules dict)
        **options: Additional comparison options
            - tolerance: For numeric comparisons (default: 0.001)
            - fuzzy: Whether to use fuzzy string matching (default: False)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if result is None:
        logger.error('Result is None, cannot compare')
        return 0.0
    tolerance = options.get('tolerance', 0.001)
    fuzzy = options.get('fuzzy', False)
    try:
        result_num = float(result)
        expected_num = float(expected)
        if abs(result_num - expected_num) <= tolerance:
            logger.info(f'Numeric match: {result_num} ≈ {expected_num}')
            return 1.0
        else:
            logger.error(f'Numeric mismatch: {result_num} vs {expected_num}')
            return 0.0
    except (ValueError, TypeError):
        result_str = str(result).strip()
        expected_str = str(expected).strip()
        if fuzzy:
            from rapidfuzz import fuzz
            similarity = fuzz.ratio(result_str, expected_str) / 100.0
            logger.info(f'Fuzzy match score: {similarity}')
            return similarity
        elif result_str == expected_str:
            logger.info(f"String match: '{result_str}'")
            return 1.0
        else:
            logger.error(f"String mismatch: '{result_str}' vs '{expected_str}'")
            return 0.0

