def check_xlsx_entry__8e803f19268af9102a167deee795649f(result, expected, **options):
    """Check if the spreadsheet entry matches expected values with fuzzy matching.

    Args:
        result: Dictionary with 'title', 'link', 'date' from getter
        expected: Expected values from rules
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0 based on match quality
    """
    expected_title = expected.get('title', '')
    expected_link = expected.get('link', '')
    expected_date = expected.get('date', '')
    threshold = options.get('threshold', 90)
    score = 0.0
    total_checks = 0
    if expected_title:
        total_checks += 1
        title_ratio = fuzz.ratio(result.get('title', '').lower(), expected_title.lower())
        if title_ratio >= threshold:
            score += 0.4
    if expected_link:
        total_checks += 1
        link_ratio = fuzz.ratio(result.get('link', ''), expected_link)
        if link_ratio >= threshold:
            score += 0.4
    if expected_date:
        total_checks += 1
        date_ratio = fuzz.ratio(result.get('date', ''), expected_date)
        if date_ratio >= threshold:
            score += 0.2
    if total_checks > 0:
        return min(score, 1.0)
    else:
        return 0.0

def check_xlsx_data__26a0e22c(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    total_checks += 1
    if len(result) > 0 and len(result[0]) >= 2:
        if result[0][0] == 'Document' and result[0][1] == 'Length':
            score += 1.0
    total_checks += 1
    expected_filenames = ['zhang_appagent', 'niu_screenagent', 'koh_visualwebarena', 'deng_mind2web']
    if len(result) > 1:
        actual_filenames = [row[0] if len(row) > 0 else None for row in result[1:] if row]
        actual_filenames = [str(v).strip().lower() if v else '' for v in actual_filenames]
        if len(actual_filenames) == 4 and all((fn in actual_filenames for fn in expected_filenames)):
            score += 1.0
    total_checks += 1
    if len(result) > 1:
        all_valid = True
        for row in result[1:]:
            if row and len(row) >= 2:
                try:
                    filename = str(row[0]).strip() if row[0] else ''
                    length_value = int(row[1])
                    if length_value != len(filename):
                        all_valid = False
                        break
                except:
                    all_valid = False
                    break
            else:
                all_valid = False
                break
        if all_valid and len(result) > 1:
            score += 1.0
    if 'sorted_lengths' in expected:
        total_checks += 1
        expected_list = expected['sorted_lengths']
        if isinstance(result, list) and len(result) > 1:
            col_idx = 1
            actual_values = []
            for row in result[1:]:
                if row and len(row) > col_idx:
                    try:
                        actual_values.append(int(row[col_idx]))
                    except:
                        pass
            if len(actual_values) == len(expected_list):
                if actual_values == expected_list:
                    score += 1.0
    if 'min_rows' in expected:
        total_checks += 1
        if len(result) >= expected['min_rows']:
            score += 1.0
    if 'count' in expected:
        total_checks += 1
        if len(result) > 1 and len(result[1]) > 1:
            try:
                count_val = int(result[1][1])
                if count_val == expected['count']:
                    score += 1.0
            except:
                pass
    return score / total_checks if total_checks > 0 else 0.0

