def check_xlsx_autofilter_and_sales__b1637b1b0888330d6a80aa2fd33f5ff1(result, expected, **options):
    """Check if AutoFilter is applied and visible rows meet Sales criteria.

    This metric verifies:
    1. AutoFilter is applied to the spreadsheet
    2. Visible rows have Sales values greater than threshold
    3. Correct number of rows are visible

    Args:
        result: Dict from getter with keys:
            - autofilter_applied: bool
            - visible_count: int
            - sales_values: list of numeric values
        expected: Dict with keys:
            - sales_threshold: minimum sales value (e.g., 3000)
            - expected_count: expected number of visible rows (e.g., 6)

    Returns:
        float: Score from 0.0 to 1.0 with partial credit
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    if result.get('autofilter_applied', False):
        score += 0.4
    visible_count = result.get('visible_count', 0)
    expected_count = expected.get('expected_count', 0)
    if visible_count == expected_count:
        score += 0.3
    elif visible_count > 0 and expected_count > 0:
        diff = abs(visible_count - expected_count)
        if diff <= 2:
            score += 0.3 * (1.0 - diff / 3.0)
    sales_threshold = expected.get('sales_threshold', 0)
    sales_values = result.get('sales_values', [])
    if sales_values:
        valid_sales = [v for v in sales_values if isinstance(v, (int, float)) and v > sales_threshold]
        if len(valid_sales) == len(sales_values) and len(sales_values) == expected_count:
            score += 0.3
        elif len(valid_sales) > 0:
            proportion = len(valid_sales) / expected_count if expected_count > 0 else 0
            score += 0.3 * proportion
    return min(1.0, score)

