def check_xlsx_sales_task__50d3be1d1adc4a85b3ae89c38a5771e7(result, expected, **options):
    """Check if sales data task was completed correctly.

    Args:
        result: Data from getter function (dict with cell values and chart info)
        expected: Expected cell values (dict)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and result.get('error'):
        return 0.0
    score = 0.0
    expected_h1 = expected.get('H1', 'May-Jan Diff')
    h1_value = result.get('H1')
    if h1_value and str(h1_value).strip() == expected_h1:
        score += 0.15
    expected_a2 = expected.get('A2_after_sort')
    expected_h2 = expected.get('H2_after_sort')
    a2_value = result.get('A2')
    h2_value = result.get('H2')
    if a2_value and expected_a2:
        if str(a2_value).strip().lower() == str(expected_a2).lower():
            score += 0.15
    if h2_value is not None and expected_h2 is not None:
        try:
            if abs(float(h2_value) - float(expected_h2)) < 1.0:
                score += 0.2
        except (ValueError, TypeError):
            pass
    all_diffs_calculated = True
    numeric_count = 0
    for row_num in range(2, 12):
        cell_key = f'H{row_num}'
        cell_value = result.get(cell_key)
        if cell_value is not None:
            try:
                float(cell_value)
                numeric_count += 1
            except (ValueError, TypeError):
                all_diffs_calculated = False
                break
        else:
            all_diffs_calculated = False
            break
    if numeric_count >= 10:
        score += 0.3
    elif numeric_count >= 5:
        score += 0.15
    charts = result.get('_charts', [])
    chart_found = False
    title_correct = False
    if charts:
        for chart in charts:
            chart_type = chart.get('type', '').lower()
            chart_title = chart.get('title', '')
            if 'line' in chart_type:
                chart_found = True
                score += 0.1
                if chart_title:
                    title_lower = chart_title.lower()
                    has_may = 'may' in title_lower
                    has_jan = 'jan' in title_lower
                    has_change_or_diff = 'change' in title_lower or 'diff' in title_lower or 'sales' in title_lower
                    if has_may and has_jan and has_change_or_diff:
                        title_correct = True
                        score += 0.1
                break
    return min(score, 1.0)

def check_xlsx_sheet_order__8e891b2a(result: List[str], expected: Dict[str, Any], **options) -> float:
    """Check if sheets are in the expected order.

    Args:
        result: List of sheet names from getter
        expected: Dict with 'order' key containing expected sheet order

    Returns:
        1.0 if order matches, partial credit for partial matches
    """
    expected_order = expected.get('order', [])
    if not expected_order:
        return 0.0
    if set(expected_order) != set(result):
        missing = set(expected_order) - set(result)
        if missing:
            return 0.0
    if result == expected_order:
        return 1.0
    correct_positions = 0
    for (i, sheet) in enumerate(expected_order):
        if i < len(result) and result[i] == sheet:
            correct_positions += 1
    return correct_positions / len(expected_order)

def check_numeric_value__5d55e268(result_state: Optional[float], expected_state: dict, **options) -> float:
    """
    Check if a numeric value matches the expected value within a tolerance.

    Args:
        result_state: The numeric value from the getter (float or None)
        expected_state: Dict containing:
            - value (float): expected numeric value
            - tolerance (float): acceptable tolerance for comparison
        **options: Additional options

    Returns:
        float: Score (1.0 if match within tolerance, 0.0 otherwise)
    """
    expected_value = expected_state.get('value')
    tolerance = expected_state.get('tolerance', 0.0)
    if result_state is None:
        logger.warning('File does not exist or value could not be parsed')
        return 0.0
    if expected_value is None:
        logger.error('Expected value not provided in config')
        return 0.0
    difference = abs(result_state - expected_value)
    if difference <= tolerance:
        logger.info(f'Value {result_state} matches expected {expected_value} within tolerance {tolerance}')
        return 1.0
    else:
        logger.warning(f'Value {result_state} does not match expected {expected_value} (difference: {difference}, tolerance: {tolerance})')
        return 0.0

