def check_xlsx_complete_task__ec4be4074af0d6a31c9cd9871d5e1334(result, expected, **options):
    """Comprehensive check for task completion.

    Verifies:
    1. Pass rates are correctly filled in row 2 (50% weight)
    2. 'MIN' is entered in cell A2 (30% weight)
    3. The minimum column is correctly identified (20% weight)

    Args:
        result: dict with 'pass_rates', 'cell_a2', 'min_col'
        expected: dict with 'expected_pass_rates', 'expected_col'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    pass_rates = result.get('pass_rates', [])
    expected_rates = expected.get('expected_pass_rates', [])
    if len(pass_rates) == len(expected_rates) and len(pass_rates) > 0:
        correct_rates = 0
        total_rates = len(expected_rates)
        for (actual, expected_val) in zip(pass_rates, expected_rates):
            if actual is not None and expected_val is not None:
                if abs(actual - expected_val) <= 0.01:
                    correct_rates += 1
        rate_score = correct_rates / total_rates
        score += rate_score * 0.5
    cell_a2 = result.get('cell_a2', '')
    if cell_a2 is not None:
        cell_a2_upper = str(cell_a2).upper().strip()
        if 'MIN' in cell_a2_upper:
            score += 0.3
    actual_min_col = result.get('min_col')
    expected_col = expected.get('expected_col')
    if actual_min_col is not None and expected_col is not None:
        if actual_min_col == expected_col:
            score += 0.2
    return score

def check_multi_cell__ab85df55(result: Dict[str, Optional[str]], expected: dict, **options) -> float:
    """Check if multiple cells match their expected values.

    Args:
        result: Dictionary mapping cell names to their values
        expected: Expected rules dict with checks for each cell (this IS the rules dict directly)
        **options: Additional comparison options

    Returns:
        Score from 0.0 to 1.0 based on how many cells match their expectations
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    rules = expected
    if not rules:
        return 0.0
    total_checks = len(rules)
    passed_checks = 0
    for (cell_name, cell_rules) in rules.items():
        cell_value = result.get(cell_name)
        if 'text' in cell_rules:
            if cell_value is None:
                continue
            expected_text = cell_rules['text']
            threshold = cell_rules.get('threshold', 85)
            similarity = fuzz.ratio(cell_value.lower(), expected_text.lower())
            if similarity >= threshold:
                passed_checks += 1
        elif 'pattern' in cell_rules:
            if cell_value is None:
                continue
            pattern = cell_rules['pattern']
            check_type = cell_rules.get('type', 'contains')
            if check_type == 'contains' and pattern in cell_value:
                passed_checks += 1
            elif check_type == 'exact' and pattern == cell_value:
                passed_checks += 1
        elif cell_rules.get('type') == 'not_empty':
            if cell_value is not None and cell_value.strip():
                passed_checks += 1
    return passed_checks / total_checks if total_checks > 0 else 0.0

