def check_xlsx_data__d200c9ab(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    if 'exact_rows' in expected:
        total_checks += 1
        if len(result) == expected['exact_rows']:
            score += 1.0
    if 'headers' in expected:
        total_checks += 1
        if len(result) > 0 and result[0]:
            expected_headers = expected['headers']
            actual_headers = [str(cell).strip() if cell else '' for cell in result[0][:len(expected_headers)]]
            if actual_headers == expected_headers:
                score += 1.0
    if 'filenames' in expected:
        total_checks += 1
        expected_filenames = set(expected['filenames'])
        if len(result) > 1:
            actual_filenames = set()
            for row in result[1:]:
                if row and len(row) > 0 and row[0]:
                    actual_filenames.add(str(row[0]).strip())
            if expected_filenames == actual_filenames:
                score += 1.0
    if 'verify_numeric_sizes' in expected and expected['verify_numeric_sizes']:
        total_checks += 1
        all_numeric = True
        if len(result) > 1:
            for row in result[1:]:
                if row and len(row) > 1:
                    try:
                        size_val = float(row[1]) if row[1] is not None else None
                        if size_val is None or size_val <= 0:
                            all_numeric = False
                            break
                    except (ValueError, TypeError):
                        all_numeric = False
                        break
                else:
                    all_numeric = False
                    break
            if all_numeric:
                score += 1.0
    if 'verify_descending_sort' in expected and expected['verify_descending_sort']:
        total_checks += 1
        is_sorted_desc = True
        if len(result) > 1:
            sizes = []
            for row in result[1:]:
                if row and len(row) > 1:
                    try:
                        size_val = float(row[1]) if row[1] is not None else 0
                        sizes.append(size_val)
                    except (ValueError, TypeError):
                        is_sorted_desc = False
                        break
            if is_sorted_desc and sizes:
                for i in range(len(sizes) - 1):
                    if sizes[i] < sizes[i + 1]:
                        is_sorted_desc = False
                        break
            if is_sorted_desc and sizes:
                score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

