def check_xlsx_age_format__af4c468f(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the age values are formatted with proper decimal precision.

    This function verifies that ALL age values in column D have at least
    the minimum required decimal places (e.g., 56.73 instead of 56).

    Uses partial scoring: returns the fraction of ages that meet the requirement.

    Args:
        result: Dictionary with 'age_value', 'decimal_places', 'is_decimal_format', 'all_age_values', and 'all_age_details'
        expected: Dictionary containing rules directly (min_decimal_places, etc.)
                 Note: When expected.type='rule', the framework returns config['rules'] directly
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 representing fraction of ages with proper formatting
    """
    if result is None or not isinstance(result, dict):
        logger.error('Result is None or not a dictionary')
        return 0.0
    all_age_details = result.get('all_age_details', [])
    if not all_age_details:
        logger.error('No age details found in result')
        return 0.0
    min_decimal_places = expected.get('min_decimal_places', 2)
    passing_count = 0
    total_count = len(all_age_details)
    for (i, age_detail) in enumerate(all_age_details):
        age_value = age_detail.get('value')
        decimal_places = age_detail.get('decimal_places', 0)
        if decimal_places >= min_decimal_places:
            passing_count += 1
            logger.debug(f'Age {i + 1}: {age_value} has {decimal_places} decimal places - PASS')
        else:
            logger.warning(f'Age {i + 1}: {age_value} has {decimal_places} decimal places (required: {min_decimal_places}) - FAIL')
    score = passing_count / total_count if total_count > 0 else 0.0
    logger.info(f'Decimal formatting check: {passing_count}/{total_count} ages have {min_decimal_places}+ decimal places - Score: {score:.2f}')
    return score

def check_xlsx_sales_task__c241b6cb189da2340f0d40023e140813(result, expected, **options):
    """Check if sales data task was completed correctly.

    Args:
        result: Data from getter function (dict with cell values and chart info)
        expected: Expected cell values (dict)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and result.get('error'):
        return 0.0
    score = 0.0
    header_checks = ['H1', 'I1']
    header_score = 0.0
    for cell_addr in header_checks:
        expected_value = expected.get(cell_addr)
        actual_value = result.get(cell_addr)
        if expected_value is not None and actual_value is not None:
            if str(actual_value).strip().lower() == str(expected_value).strip().lower():
                header_score += 0.1 / len(header_checks)
    score += header_score
    q_cells = ['H2', 'I2', 'H3', 'I3', 'H4', 'I4', 'H5', 'I5', 'H6', 'I6', 'H7', 'I7', 'H8', 'I8', 'H9', 'I9', 'H10', 'I10', 'H11', 'I11']
    correct_count = 0
    filled_count = 0
    for cell_addr in q_cells:
        expected_value = expected.get(cell_addr)
        actual_value = result.get(cell_addr)
        if actual_value is not None and actual_value != '':
            filled_count += 1
            if expected_value is not None:
                if isinstance(expected_value, (int, float)):
                    if abs(float(actual_value) - float(expected_value)) < 0.01:
                        correct_count += 1
    if filled_count < len(q_cells):
        q_score = 0.6 * (correct_count / len(q_cells))
    else:
        q_score = 0.6 * (correct_count / len(q_cells))
    score += q_score
    charts = result.get('_charts', [])
    chart_score = 0.0
    if charts:
        for chart in charts:
            chart_type = chart.get('type', '').lower()
            chart_title = chart.get('title', '')
            is_stacked = chart.get('is_stacked', False)
            series_count = chart.get('series_count', 0)
            if 'bar' in chart_type:
                if is_stacked or series_count >= 2:
                    chart_score += 0.15
                else:
                    chart_score += 0.05
            if chart_title and 'quarterly performance' in chart_title.lower():
                chart_score += 0.15
                break
    score += chart_score
    return min(score, 1.0)

