def check_calc_chart__add24b51a02a759217984b6f1f257cd6(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the chart matches expected properties.

    Args:
        result: Dict from getter with 'charts' list
        expected: Expected chart properties (from rules)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'charts' not in result:
        return 0.0
    charts = result.get('charts', [])
    if not charts:
        return 0.0
    expected_sheet_name = expected.get('sheet_name', '')
    expected_chart_type = expected.get('chart_type', '')
    expected_title = expected.get('chart_title', '')
    expected_data_column = expected.get('data_column', '')
    expected_num_weeks = expected.get('num_weeks', 0)
    score = 0.0
    for chart in charts:
        chart_score = 0.0
        points_per_check = 0.25
        if expected_sheet_name:
            if chart.get('sheet_name', '') == expected_sheet_name:
                chart_score += points_per_check
        if expected_chart_type:
            if chart.get('chart_type', '') == expected_chart_type:
                chart_score += points_per_check
        if expected_title:
            if chart.get('chart_title', '') == expected_title:
                chart_score += points_per_check
        if expected_data_column or expected_num_weeks:
            data_series = chart.get('data_series', [])
            if data_series:
                data_valid = False
                for series in data_series:
                    data_range = series.get('data_range', '')
                    category_range = series.get('category_range', '')
                    sales_column_present = False
                    if expected_data_column:
                        if expected_data_column.lower() in data_range.lower():
                            sales_column_present = True
                    weeks_complete = False
                    if expected_num_weeks > 0:
                        if category_range or data_range:
                            range_to_check = data_range if data_range else category_range
                            if ':' in range_to_check:
                                try:
                                    parts = range_to_check.split(':')
                                    if len(parts) == 2:
                                        start_row = int(''.join(filter(str.isdigit, parts[0])))
                                        end_row = int(''.join(filter(str.isdigit, parts[1])))
                                        row_count = end_row - start_row + 1
                                        if row_count >= expected_num_weeks:
                                            weeks_complete = True
                                except:
                                    pass
                    checks_passed = 0
                    checks_total = 0
                    if expected_data_column:
                        checks_total += 1
                        if sales_column_present:
                            checks_passed += 1
                    if expected_num_weeks > 0:
                        checks_total += 1
                        if weeks_complete:
                            checks_passed += 1
                    if checks_total > 0 and checks_passed == checks_total:
                        data_valid = True
                        break
                if data_valid:
                    chart_score += points_per_check
        score = max(score, chart_score)
    return score

