def check_xlsx_sorted_data__a87a12b6(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if employee data is sorted by clock-in time.

    Args:
        result: openpyxl Workbook object
        expected: Dict with 'sheet', 'data_range', 'sort_column', 'ascending' keys
        **options: Additional options

    Returns:
        1.0 if sorted correctly, 0.0 otherwise
    """
    if result is None:
        return 0.0
    try:
        sheet_idx = expected.get('sheet', 0)
        data_range = expected.get('data_range', 'B12:D23')
        sort_column = expected.get('sort_column', 2)
        ascending = expected.get('ascending', True)
        if isinstance(sheet_idx, int):
            ws = result.worksheets[sheet_idx]
        else:
            ws = result[sheet_idx]
        header_row = 11
        header_name = ws[f'B{header_row}'].value
        header_clock = ws[f'C{header_row}'].value
        if header_name != 'Employee Name' or header_clock != 'Clock-In':
            result.close()
            return 0.0
        range_match = re.match('([A-Z]+)(\\d+):([A-Z]+)(\\d+)', data_range)
        if not range_match:
            result.close()
            return 0.0
        (start_col, start_row, end_col, end_row) = range_match.groups()
        (start_row, end_row) = (int(start_row), int(end_row))
        clock_in_times = []
        employee_names = []
        for row_num in range(start_row, end_row + 1):
            employee_name = ws[f'B{row_num}'].value
            clock_in_value = ws[f'C{row_num}'].value
            employee_names.append(employee_name)
            if clock_in_value is None or str(clock_in_value).strip() == '--:-- AM':
                clock_in_times.append(None)
            else:
                time_str = str(clock_in_value).strip()
                try:
                    time_obj = datetime.strptime(time_str, '%I:%M %p')
                    clock_in_times.append(time_obj)
                except ValueError:
                    clock_in_times.append(None)
        expected_names = ['Tom', 'Olivia Calme', 'Parah Salin', 'Arnold Shawarma', 'Clint Eastwood', 'John Badman', 'Elijah Plastic', 'Bey Twice', 'William Smith', 'Ling Chang', 'Jimmy Lowe', 'Elizabeth Badland']
        if set(filter(None, employee_names)) != set(expected_names):
            result.close()
            return 0.0
        valid_times = [t for t in clock_in_times if t is not None]
        none_count = clock_in_times.count(None)
        if valid_times != sorted(valid_times):
            result.close()
            return 0.0
        if ascending:
            expected_order = valid_times + [None] * none_count
            if clock_in_times != expected_order:
                result.close()
                return 0.0
        else:
            expected_order = sorted(valid_times, reverse=True) + [None] * none_count
            if clock_in_times != expected_order:
                result.close()
                return 0.0
        result.close()
        return 1.0
    except Exception:
        if result:
            try:
                result.close()
            except:
                pass
        return 0.0

