def check_xlsx_list_match__b2473f128aae355f72e4876688cba872(result, expected, **options):
    """Compare a list of values against an expected list (order matters).

    Args:
        result: List of actual values from the getter
        expected: Dictionary containing the expected list of values
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0 based on matches
    """
    expected_list = expected.get('values', [])
    if not result and (not expected_list):
        return 1.0
    if not result or not expected_list:
        return 0.0
    result_normalized = [str(v).strip() for v in result]
    expected_normalized = [str(v).strip() for v in expected_list]
    if result_normalized == expected_normalized:
        return 1.0
    result_set = set(result_normalized)
    expected_set = set(expected_normalized)
    if not expected_set:
        return 0.0
    overlap = result_set & expected_set
    return len(overlap) / len(expected_set)

