def check_xlsx_cell_value__0483d947(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if a cell in Excel file contains the expected value using a formula.

    This function verifies that:
    1. The cell contains a formula (not a hard-coded value)
    2. The formula result equals the expected value
    3. The formula uses functions that calculate top N values (LARGE, MAX, etc.)

    Args:
        result: Path to Excel file (from getter)
        expected: Rules dict with 'sheet', 'cell', and 'value' keys
        **options: Additional options

    Returns:
        1.0 if cell has correct formula and value, 0.0 otherwise
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        cell_address = expected.get('cell', 'A1')
        expected_value = expected.get('value')
        tolerance = expected.get('tolerance', 0.0)
        wb_formula = openpyxl.load_workbook(result, data_only=False)
        if isinstance(sheet_idx, int):
            ws_formula = wb_formula.worksheets[sheet_idx]
        else:
            ws_formula = wb_formula[sheet_idx]
        cell_formula = ws_formula[cell_address].value
        if not cell_formula or not isinstance(cell_formula, str) or (not cell_formula.startswith('=')):
            print(f'Cell {cell_address} does not contain a formula. Value: {cell_formula}')
            return 0.0
        formula_upper = cell_formula.upper()
        valid_formula_indicators = ['LARGE', 'MAX', 'SUMPRODUCT', 'INDEX', 'SORT']
        has_valid_function = any((indicator in formula_upper for indicator in valid_formula_indicators))
        if not has_valid_function:
            print(f"Cell {cell_address} formula doesn't use expected functions (LARGE, MAX, etc.): {cell_formula}")
            return 0.0
        wb_data = openpyxl.load_workbook(result, data_only=True)
        if isinstance(sheet_idx, int):
            ws_data = wb_data.worksheets[sheet_idx]
        else:
            ws_data = wb_data[sheet_idx]
        cell_value = ws_data[cell_address].value
        if expected_value is None:
            return 1.0 if cell_value is None else 0.0
        if isinstance(expected_value, (int, float)) and isinstance(cell_value, (int, float)):
            if abs(cell_value - expected_value) <= tolerance:
                return 1.0
            else:
                print(f"Cell {cell_address} value {cell_value} doesn't match expected {expected_value}")
                return 0.0
        if isinstance(expected_value, str) and isinstance(cell_value, str):
            if expected_value.lower() == cell_value.lower():
                return 1.0
            return 0.0
        if cell_value == expected_value:
            return 1.0
        print(f"Cell {cell_address} value {cell_value} doesn't match expected {expected_value}")
        return 0.0
    except Exception as e:
        print(f'Error in check_xlsx_cell_value__0483d947: {e}')
        return 0.0
    finally:
        import os
        if os.path.exists(result):
            try:
                os.unlink(result)
            except:
                pass

