def check_xlsx_cell_contains__603f3b90(result_state, expected_state, **options):
    """
    Check if the cell value contains the expected text.

    Args:
        result_state: The actual cell value from the getter (str, number, or None)
        expected_state: Dict with expected rules:
            - contains: The text that should be contained in the cell (required)
            - contains_any: List of texts, at least one should be contained (optional)
            - case_sensitive: Whether the comparison is case-sensitive (default: False)
        **options: Additional options (unused)

    Returns:
        float: 1.0 if the cell contains the expected text, 0.0 otherwise
    """
    logger.debug(f'Checking cell contains: result_state={result_state}, expected_state={expected_state}')
    if isinstance(expected_state, dict):
        contains_text = expected_state.get('contains')
        contains_any = expected_state.get('contains_any', [])
        case_sensitive = expected_state.get('case_sensitive', False)
    else:
        logger.error(f'Invalid expected_state format: {expected_state}')
        return 0.0
    if result_state is None or result_state == '':
        logger.debug('Result state is None or empty')
        return 0.0
    result_str = str(result_state)
    if contains_text is not None:
        if case_sensitive:
            contains_match = contains_text in result_str
        else:
            contains_match = contains_text.lower() in result_str.lower()
        if not contains_match:
            logger.debug(f"Contains check failed: '{contains_text}' not in '{result_str}'")
            return 0.0
    if contains_any:
        any_match = False
        for text in contains_any:
            if case_sensitive:
                if text in result_str:
                    any_match = True
                    break
            elif text.lower() in result_str.lower():
                any_match = True
                break
        if not any_match:
            logger.debug(f"Contains_any check failed: none of {contains_any} found in '{result_str}'")
            return 0.0
    logger.debug(f"All checks passed for cell value: '{result_str}'")
    return 1.0

