def check_xlsx_summary_stats__d86c810e(result_state: Optional[Dict[str, Any]], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the xlsx file has correct summary statistics in Summary sheet.

    Args:
        result_state: Result from getter with structure:
            {
                "sheet_name": str,
                "revenue_total": float,
                "revenue_avg": float,
                "revenue_max": float,
                "revenue_min": float,
                "expenses_total": float,
                "expenses_avg": float,
                "expenses_max": float,
                "expenses_min": float
            }
        expected_state: Expected values from task config with structure:
            {
                "sheet_name": str,
                "revenue_total": float,
                "revenue_avg": float,
                "revenue_max": float,
                "revenue_min": float,
                "expenses_total": float,
                "expenses_avg": float,
                "expenses_max": float,
                "expenses_min": float
            }
        **options: Additional options
            - tolerance (float): Tolerance for float comparison (default: 1.0)

    Returns:
        float: Score between 0.0 and 1.0
            - 0.2 for Summary sheet creation
            - 0.1 for each correct revenue statistic (4 stats = 0.4)
            - 0.1 for each correct expenses statistic (4 stats = 0.4)
    """
    if result_state is None:
        logger.error('Result state is None - file not found or could not be read')
        return 0.0
    score = 0.0
    tolerance = options.get('tolerance', 1.0)
    expected_sheet = expected_state.get('sheet_name', 'Summary')
    if result_state.get('sheet_name') == expected_sheet:
        logger.info(f'Summary sheet exists: +0.2')
        score += 0.2
    else:
        logger.warning(f"Sheet name mismatch: expected '{expected_sheet}', got '{result_state.get('sheet_name')}'")
        return score
    revenue_stats = ['revenue_total', 'revenue_avg', 'revenue_max', 'revenue_min']
    for stat in revenue_stats:
        result_val = result_state.get(stat)
        expected_val = expected_state.get(stat)
        if result_val is not None and expected_val is not None:
            diff = abs(result_val - expected_val)
            if diff <= tolerance:
                logger.info(f'{stat} matches: {result_val} (expected: {expected_val}): +0.1')
                score += 0.1
            else:
                logger.warning(f'{stat} mismatch: {result_val} vs {expected_val} (diff: {diff}, tolerance: {tolerance})')
        else:
            logger.warning(f'{stat} missing: result={result_val}, expected={expected_val}')
    expenses_stats = ['expenses_total', 'expenses_avg', 'expenses_max', 'expenses_min']
    for stat in expenses_stats:
        result_val = result_state.get(stat)
        expected_val = expected_state.get(stat)
        if result_val is not None and expected_val is not None:
            diff = abs(result_val - expected_val)
            if diff <= tolerance:
                logger.info(f'{stat} matches: {result_val} (expected: {expected_val}): +0.1')
                score += 0.1
            else:
                logger.warning(f'{stat} mismatch: {result_val} vs {expected_val} (diff: {diff}, tolerance: {tolerance})')
        else:
            logger.warning(f'{stat} missing: result={result_val}, expected={expected_val}')
    logger.info(f'Final score: {score}')
    return score

def check_xlsx_column_list__7aaf3ddd(result, expected, **options):
    """
    Check if a list of values matches the expected list.

    Args:
        result: List of actual values from the getter
        expected: Dict with 'rules' containing 'values' key (list)

    Returns:
        float: Score between 0.0 and 1.0 based on match
    """
    try:
        expected_values = expected.get('values', [])
        if not isinstance(result, list):
            return 0.0
        result_normalized = [str(v).strip() for v in result]
        expected_normalized = [str(v).strip() for v in expected_values]
        if result_normalized == expected_normalized:
            return 1.0
        else:
            matches = sum((1 for (r, e) in zip(result_normalized, expected_normalized) if r == e))
            return matches / max(len(expected_normalized), 1)
    except Exception as e:
        print(f'Error in check_xlsx_column_list__7aaf3ddd: {e}')
        return 0.0

