def check_xlsx_structure__b7944a692f72416e350636e6da98aa56(result, expected, **options):
    """
    Check if .xlsx file has proper structure with headers and data.

    Args:
        result: Dict from getter with file structure info
        expected: Dict with expected rules (row count threshold)
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on file structure
    """
    if not isinstance(result, dict):
        return 0.0
    score = 0.0
    if result.get('exists', False):
        score += 0.3
    else:
        return 0.0
    headers = result.get('headers', [])
    required_columns = ['date', 'product', 'quantity', 'amount']
    if headers:
        headers_lower = [str(h).lower().strip() if h is not None else '' for h in headers]
        matching_columns = sum((1 for req_col in required_columns if req_col in headers_lower))
        if matching_columns == 4:
            score += 0.35
        else:
            score += 0.35 * (matching_columns / 4)
    min_rows = expected.get('min_rows', 6) if isinstance(expected, dict) else 6
    row_count = result.get('row_count', 0)
    if row_count >= min_rows:
        score += 0.35
    elif row_count > 1:
        score += 0.35 * ((row_count - 1) / (min_rows - 1))
    return score

