def check_xlsx_highest_score__7fa3947afebe1c5a8c68bb99c7f09579(result: Optional[Dict[str, Any]], expected: dict, **options) -> float:
    """
    Comprehensively check grading task completion:
    1. Verify individual question scores are 0 or 1
    2. Verify total scores match sum of question scores
    3. Verify all students were graded
    4. Verify highest score matches expected

    Args:
        result: Comprehensive grading data from getter
        expected: Expected rules dict with 'max_grade' key
        **options: Additional options

    Returns:
        Score from 0.0 to 1.0 based on partial credit:
        - 0.3: Individual question scores are valid (0 or 1 only)
        - 0.3: Total scores correctly calculated from question scores
        - 0.2: All students were graded
        - 0.2: Highest score matches expected value
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    students = result.get('students', [])
    if not students:
        return 0.0
    score = 0.0
    expected_max = expected.get('max_grade')
    all_questions_valid = True
    total_questions_checked = 0
    for student in students:
        question_scores = student.get('question_scores', [])
        for q_score in question_scores:
            if q_score is not None:
                total_questions_checked += 1
                if q_score not in [0, 1]:
                    all_questions_valid = False
                    break
        if not all_questions_valid:
            break
    if all_questions_valid and total_questions_checked > 0:
        score += 0.3
    all_totals_correct = True
    for student in students:
        total_score = student.get('total_score')
        total_calculated = student.get('total_calculated')
        if total_score is not None:
            if total_score != total_calculated:
                all_totals_correct = False
                break
    if all_totals_correct:
        score += 0.3
    all_students_graded = result.get('all_students_graded', False)
    if all_students_graded:
        score += 0.2
    highest_score = result.get('highest_score')
    if highest_score is not None and expected_max is not None:
        if highest_score == expected_max:
            score += 0.2
    return score

