def check_xlsx_avg_row__6f5e8cdfe4d2f14b944ebd6268f9363a(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if average row is correctly calculated in Excel file.

    Args:
        result: Dict from getter with row_label and values
        expected: Expected values (from rules)
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.warning('Empty result from getter')
        return 0.0
    tolerance = options.get('tolerance', 1.0)
    score = 0.0
    row_label = result.get('row_label', '')
    expected_label = expected.get('row_label', 'Average')
    if row_label and str(row_label).strip().lower() == expected_label.lower():
        score += 0.2
    values = result.get('values', [])
    expected_values = expected.get('values', [])
    if len(values) == len(expected_values) and len(values) > 0:
        points_per_value = 0.8 / len(values)
        for (actual, expect) in zip(values, expected_values):
            if actual is not None and expect is not None:
                try:
                    if abs(float(actual) - float(expect)) <= tolerance:
                        score += points_per_value
                except (TypeError, ValueError):
                    pass
    return min(score, 1.0)

