def check_xlsx_column_e_upperlast__6d21c6d2bc76143ed7460e8b97a1590b(result, expected, **options):
    """Check if all requirements are met:
    1. Employee Data split into First Name, Last Name, Rank columns (B, C, D)
    2. Column E header is 'Last Name (Upper)'
    3. Column E contains correct uppercase last names

    Args:
        result: Dict with:
            - 'headers': Dict with column headers
            - 'first_names': Dict with first names from column B
            - 'last_names': Dict with last names from column C
            - 'ranks': Dict with ranks from column D
            - 'upper_lastnames': Dict with uppercase last names from column E
        expected: Dict with:
            - 'headers': Expected header values for columns B, C, D, E
            - 'first_names': Expected first names
            - 'last_names': Expected last names
            - 'ranks': Expected ranks
            - 'upper_lastnames': Expected uppercase last names

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    result_headers = result.get('headers', {})
    expected_headers = expected.get('headers', {})
    if not result_headers:
        return 0.0
    if result_headers.get('E', '') != expected_headers.get('E', 'Last Name (Upper)'):
        return 0.0
    if not result_headers.get('B') or not result_headers.get('C') or (not result_headers.get('D')):
        return 0.0
    result_first_names = result.get('first_names', {})
    result_last_names = result.get('last_names', {})
    result_ranks = result.get('ranks', {})
    expected_first_names = expected.get('first_names', {})
    expected_last_names = expected.get('last_names', {})
    expected_ranks = expected.get('ranks', {})
    split_total = len(expected_first_names)
    split_matches = 0
    for (row_num_str, expected_first) in expected_first_names.items():
        row_num = int(row_num_str)
        if row_num in result_first_names:
            if result_first_names[row_num].strip() == expected_first.strip():
                split_matches += 0.33
        if row_num in result_last_names and row_num_str in expected_last_names:
            if result_last_names[row_num].strip() == expected_last_names[row_num_str].strip():
                split_matches += 0.33
        if row_num in result_ranks and row_num_str in expected_ranks:
            if result_ranks[row_num].strip() == expected_ranks[row_num_str].strip():
                split_matches += 0.34
    split_score = split_matches / split_total if split_total > 0 else 0.0
    result_upper = result.get('upper_lastnames', {})
    expected_upper = expected.get('upper_lastnames', {})
    if not expected_upper:
        return 0.0
    upper_total = len(expected_upper)
    upper_matches = 0
    for (row_num_str, expected_name) in expected_upper.items():
        row_num = int(row_num_str)
        if row_num in result_upper:
            if result_upper[row_num].strip() == expected_name.strip():
                upper_matches += 1
    upper_score = upper_matches / upper_total if upper_total > 0 else 0.0
    final_score = split_score * 0.4 + upper_score * 0.6
    return final_score

def check_final_price_calc__4659aefa(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Compare final_price calculations against expected values.

    Args:
        result: Dict from getter with cell values
        expected: Dict with expected values
        **options: Additional options (tolerance for float comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    checks = 0
    passes = 0
    for (cell, exp_value) in expected.items():
        if cell in result:
            checks += 1
            if result[cell] is not None and exp_value is not None:
                if abs(result[cell] - exp_value) <= tolerance:
                    passes += 1
    if checks > 0:
        score = passes / checks
    return score

