def check_xlsx_total_change__27bf3ce2d1a834c90e2dae384e041eaf(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if the total change was calculated correctly with proper formula.

    Args:
        result: Dict with 'value', 'has_formula', 'formula', 'references_2014', 'references_2019'
        expected: Rules dict with 'value' key containing expected change
        **options: Additional options (tolerance, etc.)

    Returns:
        Score between 0.0 and 1.0
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    expected_value = expected.get('value')
    if expected_value is None:
        return 0.0
    result_value = result.get('value')
    if result_value is None:
        return 0.0
    try:
        expected_float = float(expected_value)
        result_float = float(result_value)
        tolerance = options.get('tolerance', 1.0)
        if abs(result_float - expected_float) > tolerance:
            return 0.0
    except (ValueError, TypeError):
        return 0.0
    has_formula = result.get('has_formula', False)
    if not has_formula:
        return 0.3
    references_2014 = result.get('references_2014', False)
    references_2019 = result.get('references_2019', False)
    if references_2014 and references_2019:
        return 1.0
    elif has_formula:
        return 0.7
    return 0.3

