    expected_cells = expected.get('cell_values', {})
    if not expected_cells:
        return 0.0
    values = result.get('values', {})
    for (cell_addr, expected_value) in expected_cells.items():
        actual_value = values.get(cell_addr)
        if actual_value != expected_value:
            return 0.0
    if not result.get('header_bold', False):
        return 0.0
    return 1.0

