def check_xlsx_vlookup__9d8a173e5cc1d70ebe98386b3a5aac30(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if VLOOKUP results in column F match expected values.

    Args:
        result: Dict of cell addresses to actual values from the file
        expected: Dict with 'expected_values' key containing cell->value mapping
        **options: Additional options (e.g., 'partial_credit')

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', {})
    if not expected_values:
        return 0.0
    total_cells = len(expected_values)
    correct_count = 0
    for (cell_addr, expected_val) in expected_values.items():
        actual_val = result.get(cell_addr)
