def check_xlsx_domains__96a8e6ef3f2d619a8a83a9a683998043(result, expected, **options):
    """Check if all URLs meet the expected requirements: domain, date, topic, and minimum count.

    Args:
        result: Dictionary from getter with 'domains', 'dates', 'row_count', 'arxiv_ids', 'titles'
        expected: Expected values including domain and date (YYYY-MM format) from rules
        **options: Additional comparison options

    Returns:
        float: Score based on:
            - All URLs use the expected domain (arxiv.org) - strict equality check
            - All papers are from the expected month (2023-10)
            - Papers are about large language models (topic verification)
            - At least one paper was added (row_count >= 1)
    """
    expected_domain = expected.get('domain', 'arxiv.org')
    expected_date = expected.get('date', '2023-10')
    min_papers = expected.get('min_papers', 1)
    domains = result.get('domains', [])
    dates = result.get('dates', [])
    titles = result.get('titles', [])
    row_count = result.get('row_count', 0)
    if not domains or row_count < min_papers:
        return 0.0
    domain_score = 0.0
    matching_domains = sum((1 for domain in domains if domain.lower() == expected_domain))
    if domains:
        domain_score = matching_domains / len(domains)
    date_score = 0.0
    if dates:
        matching_dates = sum((1 for date in dates if date == expected_date))
        date_score = matching_dates / len(dates)
    else:
        date_score = 0.0
    topic_score = 0.0
    if titles:
        llm_keywords = ['large language model', 'llm', 'language model', 'transformer', 'gpt', 'bert', 'attention', 'pre-training', 'pretrain', 'fine-tuning', 'finetune', 'neural language', 'generative', 'decoder', 'encoder']
        matching_topics = sum((1 for title in titles if title and any((keyword in title.lower() for keyword in llm_keywords))))
        topic_score = matching_topics / len(titles) if len(titles) > 0 else 0.0
    addition_score = 1.0 if row_count >= min_papers else 0.0
    final_score = domain_score * 0.35 + date_score * 0.3 + topic_score * 0.25 + addition_score * 0.1
    return final_score

def check_xlsx_cell_highlighted__2aedcc5f(result, expected, **options):
    """Check if a cell is highlighted with the expected color.

    Args:
        result: dict with 'has_fill' and 'rgb' from getter
        expected: dict from config['rules'] with 'cell' address
        **options: Additional options like 'strict_color_match', 'color_tolerance'

    Returns:
        float: 1.0 if highlighted correctly, 0.0 otherwise
    """
    strict_color = options.get('strict_color_match', False)
    tolerance = options.get('color_tolerance', 20)
    if not result.get('has_fill', False):
        return 0.0
    if not strict_color:
        return 1.0
    expected_color = options.get('expected_color', 'FFFF00')
    result_rgb = result.get('rgb', '')
    if not result_rgb:
        return 0.0
    try:
        (r1, g1, b1) = (int(result_rgb[0:2], 16), int(result_rgb[2:4], 16), int(result_rgb[4:6], 16))
        (r2, g2, b2) = (int(expected_color[0:2], 16), int(expected_color[2:4], 16), int(expected_color[4:6], 16))
        diff = abs(r1 - r2) + abs(g1 - g2) + abs(b1 - b2)
        if diff <= tolerance:
            return 1.0
    except (ValueError, IndexError):
        pass
    return 0.0

