def check_calc_chart__1ee73704d4e6cf596e2796aeb3e217f2(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the chart matches expected properties including data series.

    Args:
        result: Dict from getter with 'charts' list
        expected: Expected chart properties (from rules)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'charts' not in result:
        return 0.0
    charts = result.get('charts', [])
    if not charts:
        return 0.0
    expected_sheet_name = expected.get('sheet_name', '')
    expected_chart_type = expected.get('chart_type', '')
    expected_title = expected.get('chart_title', '')
    expected_x_column = expected.get('x_column', '')
    expected_y_column = expected.get('y_column', '')
    expected_data_points = expected.get('data_point_count', 0)
    score = 0.0
    for chart in charts:
        chart_score = 0.0
        if expected_sheet_name and chart.get('sheet_name', '') == expected_sheet_name:
            chart_score += 0.2
        elif not expected_sheet_name:
            chart_score += 0.2
        if expected_chart_type and chart.get('chart_type', '') == expected_chart_type:
            chart_score += 0.2
        elif not expected_chart_type:
            chart_score += 0.2
        if expected_title and chart.get('chart_title', '') == expected_title:
            chart_score += 0.2
        elif not expected_title:
            chart_score += 0.2
        data_series = chart.get('data_series', [])
        if data_series:
            series_match = False
            data_complete = False
            for series in data_series:
                x_col = series.get('x_column', '')
                y_col = series.get('y_column', '')
                data_count = series.get('data_point_count', 0)
                if expected_x_column and expected_y_column:
                    if x_col == expected_x_column and y_col == expected_y_column:
                        series_match = True
                if expected_data_points > 0:
                    if data_count >= expected_data_points:
                        data_complete = True
            if series_match:
                chart_score += 0.2
            elif not expected_x_column and (not expected_y_column):
                chart_score += 0.2
            if data_complete:
                chart_score += 0.2
            elif expected_data_points == 0:
                chart_score += 0.2
        elif not expected_x_column and (not expected_y_column) and (expected_data_points == 0):
            chart_score += 0.4
        score = max(score, chart_score)
    return score

