def check_calc_cell_text__a8896662f47f9f0431d9d6ec0b20825a(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if cell contains expected text value with formula verification.

    Verifies:
    1. The displayed value matches expected text (e.g., '1.9500')
    2. A formula exists in the cell (not just a typed value)
    3. The formula references the source cell (e.g., C1)
    4. The formula performs division by 10
    5. The calculation is mathematically correct (source_value/10 == numeric_value)

    Args:
        result: Dict from getter with 'value', 'formula', 'source_cell', 'source_value', 'numeric_value'
        expected: Expected value (dict with 'text' key)
        **options: Additional options

    Returns:
        1.0 if all checks pass
        0.7 if formula exists and is correct but formatting is wrong
        0.5 if correct value but no formula (manually typed)
        0.3 if formula exists but doesn't reference correct source or perform division
        0.0 otherwise
    """
    expected_text = expected.get('text', '')
    if isinstance(result, str):
        if result == expected_text:
            return 0.5
        return 0.0
    if not isinstance(result, dict):
        return 0.0
    displayed_value = result.get('value')
    formula = result.get('formula')
    source_cell = result.get('source_cell', 'C1')
    source_value = result.get('source_value')
    numeric_value = result.get('numeric_value')
    displayed_str = str(displayed_value) if displayed_value is not None else ''
    value_matches = displayed_str == expected_text
    has_formula = formula is not None and isinstance(formula, str) and formula.startswith('=')
    if not has_formula:
        if value_matches:
            return 0.5
        return 0.0
    formula_upper = formula.upper()
    source_cell_upper = source_cell.upper()
    references_source = source_cell_upper in formula_upper
    performs_division = bool(re.search('/\\s*10(?:\\.0*)?\\b', formula))
    calculation_correct = False
    if source_value is not None and numeric_value is not None:
        try:
            expected_result = float(source_value) / 10.0
            actual_result = float(numeric_value)
            calculation_correct = abs(expected_result - actual_result) < 0.0001
        except (ValueError, TypeError):
            calculation_correct = False
    if value_matches and has_formula and references_source and performs_division and calculation_correct:
        return 1.0
    elif has_formula and references_source and performs_division and calculation_correct:
        return 0.7
    elif has_formula and (references_source or performs_division):
        return 0.3
    elif value_matches:
        return 0.5
    else:
        return 0.0

