def check_xlsx_friday_highlighting__3d829d2d9ec2788176cef7f984aa8bcc(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Friday cells are highlighted with expected color.

    Args:
        result: Dict mapping cell coordinates to fill colors from getter (dynamically identified Friday cells)
        expected: Dict with 'target_cells' (list of expected Friday cell coords) and 'expected_color' (hex color string)
        **options: Additional options like 'color_tolerance' for fuzzy matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    target_cells = expected.get('target_cells', [])
    expected_color = expected.get('expected_color', 'FF800080')
    strict_match = options.get('strict_color_match', False)
    color_tolerance = options.get('color_tolerance', 20)
    if not target_cells:
        return 0.0
    expected_color = expected_color.replace('#', '').upper()
    if len(expected_color) == 6:
        expected_color = 'FF' + expected_color
    friday_cells_found = set(result.keys())
    target_cells_expected = set(target_cells)
    if friday_cells_found != target_cells_expected:
        overlap = friday_cells_found & target_cells_expected
        if len(target_cells_expected) == 0:
            return 0.0
        coverage_score = len(overlap) / len(target_cells_expected)
    else:
        coverage_score = 1.0
    if len(friday_cells_found) == 0:
        return 0.0
    correct_count = 0
    for cell_coord in friday_cells_found:
        actual_color = result.get(cell_coord)
        if actual_color is None:
            continue
        if isinstance(actual_color, str):
            actual_color = actual_color.replace('#', '').upper()
            if len(actual_color) == 6:
                actual_color = 'FF' + actual_color
        if strict_match:
            if actual_color == expected_color:
                correct_count += 1
        elif _colors_similar(actual_color, expected_color, color_tolerance):
            correct_count += 1
    color_score = correct_count / len(friday_cells_found)
    return coverage_score * color_score

def check_calc_pivot_table__07645cd9da820827262a85cd65eb3825(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if LibreOffice Calc Revenue column and pivot table were created correctly.

    Args:
        result: Data from getter including Revenue column check and pivot table data
        expected: Expected validation rules with expected_websites
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass) with partial credit
        - 0.3 for Revenue column creation with correct formula
        - 0.3 for Sheet2/pivot table structure
        - 0.4 for correct revenue values grouped by website
    """
    score = 0.0
    if result.get('revenue_column_exists'):
        revenue_score = 0.0
        revenue_formulas = result.get('revenue_formulas', [])
        has_valid_formulas = False
        if revenue_formulas:
            formula_count = sum((1 for f in revenue_formulas if f.get('is_formula', False)))
            if formula_count > 0:
                has_valid_formulas = True
                valid_formula_pattern = False
                for formula_info in revenue_formulas:
                    if formula_info.get('is_formula'):
                        formula = formula_info.get('formula', '').upper()
                        if '*' in formula and ('-' in formula or 'PRODUCT' in formula):
                            valid_formula_pattern = True
                            break
                if valid_formula_pattern:
                    revenue_score = 0.15
        revenue_values = result.get('revenue_values', [])
        if revenue_values:
            positive_values = sum((1 for v in revenue_values if v.get('value', 0) > 0))
            if positive_values > 0:
                revenue_score += 0.15
        score += revenue_score
    if result.get('has_sheet2'):
        pivot_score = 0.0
        pivot_data = result.get('pivot_data', [])
        if pivot_data and len(pivot_data) > 1:
            pivot_score = 0.3
        score += pivot_score
    expected_websites = expected.get('expected_websites', [])
    if expected_websites and result.get('has_sheet2'):
        pivot_data = result.get('pivot_data', [])
        pivot_revenues = result.get('pivot_revenues', {})
        if pivot_data:
            pivot_text = ' '.join([str(cell) for row in pivot_data for cell in row if cell is not None])
            found_websites = []
            for website in expected_websites:
                if website in pivot_text:
                    found_websites.append(website)
            if found_websites:
                website_coverage_score = 0.2 * (len(found_websites) / len(expected_websites))
                score += website_coverage_score
                expected_revenues = {'amazon.com': 5854.55, 'ebay.com': 4690.34, 'gel-boomerang.com': 1288.75, 'coloradoboomerangs.com': 1151.53}
                revenue_check_score = 0.0
                if pivot_revenues:
                    correct_revenue_count = 0
                    total_checked = 0
                    for website in found_websites:
                        if website in expected_revenues:
                            total_checked += 1
                            actual_revenue = pivot_revenues.get(website)
                            if actual_revenue is not None:
                                expected_revenue = expected_revenues[website]
                                tolerance = expected_revenue * 0.05
                                if abs(actual_revenue - expected_revenue) <= tolerance:
                                    correct_revenue_count += 1
                                elif abs(actual_revenue - expected_revenue) <= 100:
                                    correct_revenue_count += 0.5
                    if total_checked > 0:
                        revenue_check_score = 0.2 * (correct_revenue_count / total_checked)
                score += revenue_check_score
    return min(1.0, score)

