def check_calc_header_format__4d552da6(result, expected, **options):
    """Check if header row has correct values and formatting.

    Args:
        result: Path to the Excel file
        expected: Dict with 'sheet_name', 'header_row', 'headers', 'bgcolor_check'

    Returns:
        float: Score between 0.0 and 1.0
    """
    sheet_name = expected.get('sheet_name')
    header_row = expected.get('header_row', 1)
    expected_headers = expected.get('headers', [])
    bgcolor_check = expected.get('bgcolor_check', False)
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        if sheet_name not in wb.sheetnames:
            return 0.0
        ws = wb[sheet_name]
        score = 0.0
        actual_headers = [cell.value for cell in ws[header_row]]
        if actual_headers[:len(expected_headers)] == expected_headers:
            score += 0.5
        if bgcolor_check:
            has_bgcolor = False
            for cell in ws[header_row][:len(expected_headers)]:
                if cell.fill and cell.fill.start_color:
                    color_rgb = cell.fill.start_color.rgb
                    if color_rgb and isinstance(color_rgb, str):
                        if len(color_rgb) >= 6:
                            try:
                                r = int(color_rgb[-6:-4], 16)
                                g = int(color_rgb[-4:-2], 16)
                                b = int(color_rgb[-2:], 16)
                                if r > 200 and g > 200 and (b < 100):
                                    has_bgcolor = True
                                    break
                            except:
                                pass
            if has_bgcolor:
                score += 0.5
        return min(score, 1.0)
    except Exception as e:
        return 0.0

