def check_xlsx_multi_cells__183d0cc2efecbcc0ebc418468a9cbbfc(result: dict, expected: dict, **options) -> float:
    """Compare multiple cell values against expected values with weighted scoring.

    Args:
        result: Dict mapping cell coordinates to their values (from getter)
        expected: Dict from rules with keys:
            - checks: List of dicts, each containing:
                - cell: Cell coordinate (e.g., 'F3')
                - value: Expected value
                - tolerance: Allowed difference for numeric values (optional)
                - weight: Weight for this check (optional, default: equal weights)
        **options: Additional options

    Returns:
        float: Weighted score between 0.0 and 1.0
    """
    if not result or not isinstance(result, dict):
        return 0.0
    checks = expected.get('checks', [])
    if not checks:
        return 0.0
    total_weight = 0.0
    weighted_score = 0.0
    for check in checks:
        cell = check.get('cell')
        expected_value = check.get('value')
        tolerance = check.get('tolerance', 0.001)
        weight = check.get('weight', 1.0)
        if cell is None or expected_value is None:
            continue
        total_weight += weight
        actual_value = result.get(cell)
        if actual_value is None:
            continue
        try:
            actual_float = float(actual_value)
            expected_float = float(expected_value)
            if abs(actual_float - expected_float) <= tolerance:
                weighted_score += weight
        except (TypeError, ValueError):
            if actual_value == expected_value:
                weighted_score += weight
    if total_weight == 0:
        return 0.0
    return weighted_score / total_weight

