def check_xlsx_summary__eb182a58(result: bytes, expected: Dict[str, Any], **options) -> float:
    """Check if Excel summary file contains correct AWS invoice totals.

    Args:
        result: Excel file content as bytes (vm_file result)
        expected: Expected rules dict with 'sheet' and 'total_sum'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        if not isinstance(result, bytes):
            return 0.0
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(result)
            tmp_path = tmp.name
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        os.unlink(tmp_path)
        sheet_idx = expected.get('sheet', 0)
        expected_total = expected.get('total_sum', 0)
        if sheet_idx >= len(wb.sheetnames):
            return 0.0
        ws = wb.worksheets[sheet_idx]
        max_row = ws.max_row
        if max_row < 2:
            return 0.0
        score = 0.0
        max_score = 1.0
        header_row = [cell.value for cell in ws[1]]
        if len(header_row) < 2:
            return 0.0
        has_month = any((str(h).lower().strip() == 'month' for h in header_row[:2] if h))
        has_amount = any((str(h).lower().strip() == 'amount' for h in header_row[:2] if h))
        if has_month and has_amount:
            score += 0.15
        else:
            return 0.0
        month_col_idx = None
        amount_col_idx = None
        for (idx, h) in enumerate(header_row[:2]):
            if h and str(h).lower().strip() == 'month':
                month_col_idx = idx
            elif h and str(h).lower().strip() == 'amount':
                amount_col_idx = idx
        if month_col_idx is None or amount_col_idx is None:
            return 0.0
        amounts = []
        month_values = []
        expected_months = ['2308', '2309', '2310', '2311']
        for (row_idx, row) in enumerate(ws.iter_rows(min_row=2, values_only=False), start=2):
            if not row or len(row) <= max(month_col_idx, amount_col_idx):
                continue
            month_cell = row[month_col_idx]
            amount_cell = row[amount_col_idx]
            is_total_row = False
            if month_cell.value and isinstance(month_cell.value, str):
                month_str_lower = str(month_cell.value).lower().strip()
                if 'total' in month_str_lower or 'sum' in month_str_lower:
                    is_total_row = True
            if hasattr(amount_cell, 'value') and isinstance(amount_cell.value, str):
                if str(amount_cell.value).startswith('='):
                    is_total_row = True
            if is_total_row:
                continue
            try:
                amount_val = float(amount_cell.value) if amount_cell.value is not None else None
                if amount_val is not None:
                    amounts.append(amount_val)
                    month_val = str(month_cell.value).strip() if month_cell.value is not None else ''
                    month_values.append(month_val)
            except (ValueError, TypeError):
                pass
        if len(amounts) >= 4:
            score += 0.15
        else:
            return score
        month_name_map = {'2308': ['aug', '08', '8'], '2309': ['sep', '09', '9'], '2310': ['oct', '10'], '2311': ['nov', '11']}
        months_found = 0
        for month_val in month_values:
            month_val_lower = month_val.lower()
            found_match = False
            for expected_month in expected_months:
                if expected_month in month_val:
                    months_found += 1
                    found_match = True
                    break
                if expected_month in month_name_map:
                    for variant in month_name_map[expected_month]:
                        if variant in month_val_lower and ('2023' in month_val or '23' in month_val):
                            months_found += 1
                            found_match = True
                            break
                if found_match:
                    break
        if months_found >= 4:
            score += 0.2
        elif months_found == 3:
            score += 0.15
        elif months_found == 2:
            score += 0.1
        elif months_found == 1:
            score += 0.05
        expected_amounts = [1.14, 1.01, 1.02, 0.99]
        amounts_match = 0
        for expected_amt in expected_amounts:
            if any((abs(amt - expected_amt) < 0.01 for amt in amounts)):
                amounts_match += 1
        score += amounts_match * 0.05
        actual_sum = sum(amounts)
        if abs(actual_sum - expected_total) < 0.01:
            score += 0.3
        return min(max_score, score)
    except Exception as e:
        return 0.0

def check_xlsx_youngest_1990s__9391b6d6(result, expected, **options):
    """
    Multi-step verification with partial credit.

    This verifies that the user:
    1. Calculated ages of all employees in column D [40% credit]
    2. Identified and wrote the correct employee name to cell E2 [60% credit]

    Args:
        result: Dictionary from getter with:
            - 'ages_in_column_d': list of values from column D
            - 'answer_in_e2': value from cell E2
        expected: Dictionary with expected employee name (when type="rule", this is the rules dict directly)

    Returns:
        float: Score between 0.0 and 1.0 (partial credit possible)
    """
    if not result or not isinstance(result, dict):
        return 0.0
    score = 0.0
    ages_in_column_d = result.get('ages_in_column_d', [])
    if ages_in_column_d:
        numeric_count = 0
        for value in ages_in_column_d:
            if isinstance(value, (int, float)):
                numeric_count += 1
            elif isinstance(value, str):
                try:
                    float(value)
                    numeric_count += 1
                except:
                    pass
        if len(ages_in_column_d) > 0 and numeric_count / len(ages_in_column_d) >= 0.5:
            score += 0.4
    expected_name = expected.get('employee_name')
    answer_in_e2 = result.get('answer_in_e2')
    if answer_in_e2 and expected_name:
        result_normalized = str(answer_in_e2).strip().lower()
        expected_normalized = str(expected_name).strip().lower()
        if result_normalized == expected_normalized:
            score += 0.6
    return score

