def check_xlsx_margin_pct__cb5332b2b6cf51c0e5cbb690a87b30bd(result, expected, **options):
    """
    Compare margin percentage data including header and value.

    Args:
        result: Dict with 'header', 'value', and 'formula' from the getter
        expected: Dict with 'value' key containing the expected margin percentage
        **options: Optional parameters like 'tolerance' for numeric comparison

    Returns:
        float: 1.0 if both header and value match requirements, 0.0 otherwise
    """
    if result is None:
        return 0.0
    header = result.get('header', '')
    if header is None:
        return 0.0
    header_normalized = str(header).strip().lower()
    if 'margin' not in header_normalized or '%' not in header_normalized:
        return 0.0
    formula = result.get('formula')
    if formula is None or not isinstance(formula, str):
        return 0.0
    if not formula.startswith('='):
        return 0.0
    actual_value = result.get('value')
    expected_value = expected.get('value')
    tolerance = options.get('tolerance', 0.01)
    if actual_value is None and expected_value is None:
        return 1.0
    if actual_value is None or expected_value is None:
        return 0.0
    if isinstance(actual_value, (int, float)) and isinstance(expected_value, (int, float)):
        if abs(actual_value - expected_value) <= tolerance:
            return 1.0
        else:
            return 0.0
    if actual_value == expected_value:
        return 1.0
    return 0.0

