def check_average_formulas__f1a42bc1(result, expected, **options):
    """
    Check if average formulas are correctly added to specific cells.

    Args:
        result: Path to the Excel file
        expected: Dict with keys:
            - sheet: Sheet index
            - label_cell: Cell containing label (e.g., "A12")
            - label_value: Expected label text (e.g., "Average")
            - sales_cell: Cell containing sales average (e.g., "B12")
            - sales_value: Expected sales average value
            - cogs_cell: Cell containing COGS average (e.g., "C12")
            - cogs_value: Expected COGS average value
        **options: Additional options (tolerance for float comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        label_cell = expected.get('label_cell')
        label_value = expected.get('label_value')
        sales_cell = expected.get('sales_cell')
        sales_value = expected.get('sales_value')
        cogs_cell = expected.get('cogs_cell')
        cogs_value = expected.get('cogs_value')
        tolerance = options.get('tolerance', 1.0)
        wb = openpyxl.load_workbook(result, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        score = 0.0
        if label_cell:
            actual_label = ws[label_cell].value
            logger.info(f"Label cell {label_cell}: expected '{label_value}', got '{actual_label}'")
            if actual_label and str(actual_label).strip().lower() == str(label_value).strip().lower():
                score += 0.33
        if sales_cell and sales_value is not None:
            actual_sales = ws[sales_cell].value
            logger.info(f'Sales cell {sales_cell}: expected {sales_value}, got {actual_sales}')
            if actual_sales is not None:
                if isinstance(sales_value, (int, float)) and isinstance(actual_sales, (int, float)):
                    rel_tolerance = max(tolerance, abs(sales_value * 0.001))
                    if abs(float(actual_sales) - float(sales_value)) < rel_tolerance:
                        score += 0.33
                elif actual_sales == sales_value:
                    score += 0.33
        if cogs_cell and cogs_value is not None:
            actual_cogs = ws[cogs_cell].value
            logger.info(f'COGS cell {cogs_cell}: expected {cogs_value}, got {actual_cogs}')
            if actual_cogs is not None:
                if isinstance(cogs_value, (int, float)) and isinstance(actual_cogs, (int, float)):
                    rel_tolerance = max(tolerance, abs(cogs_value * 0.001))
                    if abs(float(actual_cogs) - float(cogs_value)) < rel_tolerance:
                        score += 0.34
                elif actual_cogs == cogs_value:
                    score += 0.34
        logger.info(f'Final score: {score}')
        return min(score, 1.0)
    except Exception as e:
        logger.error(f'Error checking average formulas: {e}')
        return 0.0

