def check_xlsx_rounded_values__0bfaa3c8(result, expected, **options):
    """Check if values are rounded to integers.
    
    Args:
        result: List of actual values from getter
        expected: List of expected rounded values (from rules)
        
    Returns:
        float: Proportion of correctly rounded values
    """
    if result is None or expected is None:
        return 0.0
    if not isinstance(result, list) or not isinstance(expected, list):
        return 0.0
    if len(result) != len(expected):
        return 0.0
    correct_count = 0
    total_count = len(result)
    for (r, e) in zip(result, expected):
        if r is None or e is None:
            if r == e:
                correct_count += 1
        elif isinstance(r, (int, float)) and isinstance(e, (int, float)):
            if abs(r - e) < 0.01:
                correct_count += 1
        elif r == e:
            correct_count += 1
    return correct_count / total_count if total_count > 0 else 0.0

def check_cell_highlighted__9226d69f(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if the max value cell has yellow highlighting and others don't.

    Args:
        result: Dict from getter with max_cell, max_value, max_cell_color, other_cells_colors
        expected: Dict with 'color' (required yellow color) and optional 'only_max_highlighted'
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    max_cell_color = result.get('max_cell_color')
    other_cells_colors = result.get('other_cells_colors', {})
    required_color = expected.get('color', 'FFFFFF00')
    only_max_highlighted = expected.get('only_max_highlighted', True)
    if max_cell_color is None or max_cell_color == '00000000':
        return 0.0
    max_color_normalized = max_cell_color.upper().replace('#', '')
    required_color_normalized = required_color.upper().replace('#', '')
    yellow_variants = ['FFFFFF00', 'FFFF00', 'FFFFE000', 'FFFFC000']
    is_yellow = False
    if max_color_normalized == required_color_normalized:
        is_yellow = True
    else:
        for yellow in yellow_variants:
            if max_color_normalized == yellow or max_color_normalized.endswith(yellow):
                is_yellow = True
                break
    if not is_yellow:
        return 0.0
    if only_max_highlighted and other_cells_colors:
        return 0.5
    return 1.0

def check_xlsx_text_format__3cd544cf(result_state: Optional[str], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the cell text matches the expected formatted text.

    This validates that a formula in LibreOffice Calc correctly formats a number
    with the proper decimal places within concatenated text.

    Scoring: Binary - 1.0 if exact match, 0.0 otherwise

    Args:
        result_state: The actual cell text from the getter (str)
        expected_state: Dict containing:
            - When type='rule', the 'rules' field is passed directly as expected_state (str)
        **options: Additional options

    Returns:
        float: 1.0 if the text matches exactly, 0.0 otherwise
    """
    if result_state is None:
        logger.warning('Result state is None')
        return 0.0
    if isinstance(expected_state, str):
        expected_text = expected_state
    elif isinstance(expected_state, dict):
        expected_text = expected_state.get('rules') or expected_state.get('expected') or expected_state.get('text')
    else:
        logger.error(f'Unexpected expected_state type: {type(expected_state)}')
        return 0.0
    if expected_text is None:
        logger.error('Could not extract expected text from expected_state')
        return 0.0
    result_normalized = result_state.strip()
    expected_normalized = expected_text.strip()
    logger.info(f"Comparing result: '{result_normalized}' with expected: '{expected_normalized}'")
    if result_normalized == expected_normalized:
        logger.info('Text matches exactly - PASS')
        return 1.0
    else:
        logger.warning(f'Text mismatch - FAIL')
        logger.warning(f"  Expected: '{expected_normalized}'")
        logger.warning(f"  Got:      '{result_normalized}'")
        return 0.0

