def check_xlsx_has_formula__27a99669(result: Any, expected: Any, **options) -> float:
    """Check if cell contains a formula that sums all marks."""
    if result is None:
        return 0.0
    if not isinstance(result, str) or not result.startswith('='):
        return 0.0
    expected_function = expected.get('contains')
    if expected_function and expected_function.upper() not in result.upper():
        return 0.0
    env = options.get('env')
    config = options.get('config', {})
    if not env or not config:
        return _validate_formula_structure(result)
    file_path = config.get('path')
    if not file_path:
        return _validate_formula_structure(result)
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return _validate_formula_structure(result)
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, data_only=True)
            ws = wb.worksheets[0]
            marks_columns = []
            header_row = 1
            data_start_row = 2
            for col_idx in range(1, ws.max_column + 1):
                col_letter = openpyxl.utils.get_column_letter(col_idx)
                has_numeric_data = False
                for row_idx in range(data_start_row, min(data_start_row + 10, ws.max_row + 1)):
                    cell_value = ws.cell(row=row_idx, column=col_idx).value
                    if isinstance(cell_value, (int, float)):
                        has_numeric_data = True
                        break
                if has_numeric_data:
                    marks_columns.append(col_letter)
            actual_data_rows = ws.max_row - header_row
            wb.close()
            return _validate_formula_against_file(result, marks_columns, data_start_row, ws.max_row)
        finally:
            os.unlink(tmp_path)
    except Exception:
        return _validate_formula_structure(result)

