def check_xlsx_sheet_movies_title_sorted__543edcc02255a6341a79f9a357652a1d(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if a sheet contains movies from a year range sorted by title.

    Args:
        result: List of rows from the Excel sheet (from getter)
        expected: Dict with 'start_year', 'end_year', 'expected_count'
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or len(result) < 2:
        return 0.0
    start_year = expected.get('start_year', 2000)
    end_year = expected.get('end_year', 2010)
    expected_count = expected.get('expected_count', None)
    score = 0.0
    header = result[0]
    expected_header = ['title', 'release year', 'ratings', 'description']
    if header[:4] == expected_header:
        score += 0.3
    else:
        return 0.0
    data_rows = result[1:]
    all_years_valid = True
    for row in data_rows:
        if len(row) < 2:
            all_years_valid = False
            break
        year = row[1]
        if year is None or not start_year <= int(year) <= end_year:
            all_years_valid = False
            break
    if all_years_valid:
        score += 0.3
    else:
        return score
    titles = [str(row[0]).lower() for row in data_rows if row[0] is not None]
    is_sorted = all((titles[i] <= titles[i + 1] for i in range(len(titles) - 1)))
    if is_sorted:
        score += 0.2
    else:
        return score
    if expected_count is not None:
        if len(data_rows) == expected_count:
            score += 0.2
        else:
            return score
    return 1.0

def check_tb_xlsx_last5__83b26915b95d527995983f7266629d4a(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the Excel spreadsheet contains the correct last 5 emails from Thunderbird daily folder.

    Args:
        result: Dict from getter containing extracted email data
        expected: Dict with expected email data (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        logger.error(f"Getter error: {result['error']}")
        return 0.0
    if not isinstance(result, dict) or 'emails' not in result:
        logger.error('Invalid result format')
        return 0.0
    expected_emails = expected.get('expected_emails', [])
    result_emails = result.get('emails', [])
    if len(result_emails) != 5:
        logger.error(f'Expected 5 emails, got {len(result_emails)}')
        return 0.0
    score = 0.0
    total_checks = len(expected_emails)
    for (i, (expected_email, result_email)) in enumerate(zip(expected_emails, result_emails)):
        email_score = 0.0
        checks = 0
        if 'sender_name' in expected_email:
            checks += 1
            if result_email.get('sender_name', '').strip() == expected_email['sender_name'].strip():
                email_score += 0.2
        if 'sender_email' in expected_email:
            checks += 1
            if result_email.get('sender_email', '').strip() == expected_email['sender_email'].strip():
                email_score += 0.2
        if 'subject' in expected_email:
            checks += 1
            if result_email.get('subject', '').strip() == expected_email['subject'].strip():
                email_score += 0.2
        if 'cc' in expected_email:
            checks += 1
            result_cc = result_email.get('cc', '').strip()
            expected_cc = expected_email['cc'].strip()
            if not result_cc and (not expected_cc) or result_cc == expected_cc:
                email_score += 0.2
        if 'attachment_count' in expected_email:
            checks += 1
            if result_email.get('attachment_count', 0) == expected_email['attachment_count']:
                email_score += 0.2
        if checks > 0:
            score += email_score / checks
    return score

def check_xlsx_cell_formula_and_value__183d0cc2efecbcc0ebc418468a9cbbfc(result: dict, expected: dict, **options) -> float:
    """Check both cell formula pattern and calculated value.

    Args:
        result: Dict from getter with 'formula' and 'value' keys
        expected: Dict from rules with keys:
            - value: Expected numeric value
            - tolerance: Allowed difference (default: 0.001)
            - formula_contains: List of strings that formula must contain (e.g., ['MAX', 'B3:B7'])
        **options: Additional options

    Returns:
        float: 1.0 if both formula pattern and value match, 0.0 otherwise
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    expected_value = expected.get('value')
    tolerance = expected.get('tolerance', 0.001)
    formula_contains = expected.get('formula_contains', [])
    if expected_value is None:
        return 0.0
    formula = result.get('formula')
    if formula is None:
        return 0.0
    formula_upper = formula.upper()
    for pattern in formula_contains:
        pattern_upper = pattern.upper()
        if pattern_upper not in formula_upper:
            return 0.0
    cell_value = result.get('value')
    if cell_value is None:
        return 0.0
    try:
        result_float = float(cell_value)
        expected_float = float(expected_value)
        if abs(result_float - expected_float) <= tolerance:
            return 1.0
        else:
            return 0.0
    except (TypeError, ValueError):
        return 0.0

def check_xlsx_period_rate_min__fb10ed6d3d541f23d60c3749f2188910(result, expected, **options):
    """Check if the minimum period rate is correctly identified and highlighted.

    Verifies:
    1. Column header is exactly "Period Rate (%)"
    2. All 24 data rows have Period Rate values
    3. Values are formatted as numbers (not text)
    4. Minimum value is correct
    5. Minimum is at expected row
    6. Minimum cell has blue font color
    7. Calculations are correct (sample verification)

    Args:
        result: dict from getter with keys: min_row, min_value, cell, has_blue_font,
            column_header, total_data_rows, all_numeric, calculation_sample_correct
        expected: dict with keys: expected_row, expected_value (tolerance allowed)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    score = 0.0
    max_score = 7.0
    if result.get('column_header') == 'Period Rate (%)':
        score += 1.0
    if result.get('total_data_rows') == 24:
        score += 1.0
    if result.get('all_numeric', False):
        score += 1.0
    expected_value = expected.get('expected_value')
    if expected_value is not None and result.get('min_value') is not None:
        tolerance = 0.0001
        if abs(result['min_value'] - expected_value) < tolerance:
            score += 1.0
    expected_row = expected.get('expected_row')
    if expected_row is not None and result.get('min_row') == expected_row:
        score += 1.0
    if result.get('has_blue_font', False):
        score += 1.0
    if result.get('calculation_sample_correct', False):
        score += 1.0
    return score / max_score

def check_calc_pivot_table__f6d5a0db6745bedf062e13e7470e2c1c(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if LibreOffice Calc Total Revenue column and pivot table were created correctly.

    Args:
        result: Data from getter containing:
            - Sheet1 data with Total Revenue column
            - Sheet2 pivot table data
        expected: Expected validation rules including expected_types
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass) with partial credit
            - 0.2 for Total Revenue column existence
            - 0.2 for Total Revenue formula correctness (spot-check)
            - 0.2 for Sheet2 existence
            - 0.2 for pivot data presence
            - 0.2 for both sale types in pivot table
    """
    score = 0.0
    if result.get('has_total_revenue_column'):
        score += 0.2
        total_rev_idx = result.get('total_revenue_column_index', -1)
        quantity_idx = result.get('quantity_column_index', -1)
        retail_price_idx = result.get('retail_price_column_index', -1)
        discount_idx = result.get('discount_column_index', -1)
        if total_rev_idx >= 0 and quantity_idx >= 0 and (retail_price_idx >= 0) and (discount_idx >= 0):
            sample_rows = result.get('sample_rows', [])
            correct_count = 0
            total_checked = 0
            for row in sample_rows[:5]:
                if len(row) > max(total_rev_idx, quantity_idx, retail_price_idx, discount_idx):
                    quantity = row[quantity_idx]
                    retail_price = row[retail_price_idx]
                    discount = row[discount_idx]
                    total_revenue = row[total_rev_idx]
                    if quantity is not None and retail_price is not None and (discount is not None) and (total_revenue is not None):
                        try:
                            expected_value = float(quantity) * float(retail_price) * (1 - float(discount))
                            actual_value = float(total_revenue)
                            if abs(expected_value - actual_value) < 0.01:
                                correct_count += 1
                            total_checked += 1
                        except (ValueError, TypeError):
                            pass
            if total_checked >= 3 and correct_count >= total_checked * 0.8:
                score += 0.2
    if result.get('has_sheet2'):
        score += 0.2
        pivot_data = result.get('pivot_data', [])
        if pivot_data and len(pivot_data) > 1:
            score += 0.2
            expected_types = expected.get('expected_types', [])
            if expected_types:
                pivot_text = ' '.join([str(cell) for row in pivot_data for cell in row if cell is not None])
                found_count = sum((1 for sale_type in expected_types if sale_type in pivot_text))
                if found_count > 0:
                    score += 0.2 * (found_count / len(expected_types))
    return score

