def check_xlsx_multi_merge__740219c6(result, expected, **options):
    """
    Check if a new sheet exists with multiple merged cell regions and specific text.

    Args:
        result: Path to the Excel file
        expected: Dictionary with rules containing:
            - sheet_name: Name of the sheet to check
            - merges: List of merge specifications, each with:
                - start: Starting cell (e.g., "A1")
                - end: Ending cell (e.g., "E1")
                - text: Expected text in the merged cell
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (partial credit given)
    """
    try:
        sheet_name = expected.get('sheet_name')
        merges = expected.get('merges', [])
        if not os.path.exists(result):
            return 0.0
        wb = openpyxl.load_workbook(result, data_only=True)
        if sheet_name not in wb.sheetnames:
            return 0.0
        ws = wb[sheet_name]
        total_checks = len(merges) * 2
        if total_checks == 0:
            return 0.0
        passed_checks = 0
        for merge_spec in merges:
            start_cell = merge_spec.get('start')
            end_cell = merge_spec.get('end')
            expected_text = merge_spec.get('text')
            cell = ws[start_cell]
            is_merged = isinstance(cell, openpyxl.cell.cell.MergedCell) or start_cell in ws.merged_cells
            if is_merged:
                passed_checks += 1
            actual_text = ws[start_cell].value
            if actual_text == expected_text:
                passed_checks += 1
        score = passed_checks / total_checks if total_checks > 0 else 0.0
        return score
    except Exception as e:
        return 0.0

def check_xlsx_product_revenue__e8c9685c4501202760efdbd71ab284b6(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Compare actual product revenue against expected values with strict verification.

    Verifies:
    1. Exactly 5 products are listed in Sheet2
    2. All 5 products match the expected top 5 products
    3. Revenue values match within tolerance
    4. Products are sorted by revenue in descending order

    Args:
        result: Dict with 'products' (list of tuples) and 'count' from getter
        expected: Expected product revenue mapping (from rules)
        **options: Additional options (tolerance, etc.)

    Returns:
        float: 1.0 if all requirements met, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_products = expected.get('product_revenue', {})
    if not expected_products:
        return 0.0
    products_list = result.get('products', [])
    actual_count = result.get('count', 0)
    expected_count = len(expected_products)
    if actual_count != expected_count:
        return 0.0
    if len(products_list) != expected_count:
        return 0.0
    actual_products_dict = {product: revenue for (product, revenue) in products_list}
    for (product, expected_revenue) in expected_products.items():
        if product not in actual_products_dict:
            return 0.0
        actual_revenue = actual_products_dict[product]
        if abs(actual_revenue - expected_revenue) > tolerance:
            return 0.0
    for i in range(len(products_list) - 1):
        current_revenue = products_list[i][1]
        next_revenue = products_list[i + 1][1]
        if current_revenue < next_revenue:
            return 0.0
    return 1.0

def check_xlsx_avg_value__1588f42a77f2a48430625df9217ab1e4(result, expected, **options):
    """
    Verify that a cell contains an AVERAGE formula and that the calculated value matches expected.

    Args:
        result: Dict from getter with 'formula' (formula string or None) and 'value' (calculated value)
        expected: Dict with 'value' key containing the expected average value
        **options: Optional parameters like 'tolerance' for numeric comparison

    Returns:
        float: 1.0 if cell has AVERAGE formula and correct value, 0.0 otherwise
    """
    expected_value = expected.get('value')
    tolerance = options.get('tolerance', 1.0)
    if not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    calculated_value = result.get('value')
    if not formula or not isinstance(formula, str):
        return 0.0
    formula_upper = formula.upper()
    if 'AVERAGE(' not in formula_upper:
        return 0.0
    if calculated_value is None or expected_value is None:
        return 0.0
    if isinstance(calculated_value, (int, float)) and isinstance(expected_value, (int, float)):
        if abs(calculated_value - expected_value) <= tolerance:
            return 1.0
        else:
            return 0.0
    if calculated_value == expected_value:
        return 1.0
    return 0.0

