def check_xlsx_cell_value__6604f75b(result_state, expected_state, **options):
    """
    Check if a new row in the tally book has been added correctly with:
    - Service column: 'Receipt Count'
    - Month column: empty
    - Amount column: count value (5)
    - Verify that a new row was actually added (not just modified)

    Args:
        result_state: Path to the result xlsx file
        expected_state: Dict containing:
            - sheet: Sheet index (int) or name (str)
            - cell: Cell coordinate for amount (e.g., "C7") - used to determine row
            - value: Expected count value (5)
        **options: Additional options including:
            - original_file: Path to the original xlsx file for comparison (optional)

    Returns:
        float: Score based on passed checks (max 1.0)
    """
    if result_state is None:
        logger.error('Result file path is None')
        return 0.0
    if not os.path.exists(result_state):
        logger.error(f'Result file not found: {result_state}')
        return 0.0
    try:
        logger.info(f'Loading result file: {result_state}')
        workbook: Workbook = openpyxl.load_workbook(filename=result_state)
        sheet_idx = expected_state.get('sheet', 0)
        if isinstance(sheet_idx, int):
            sheet_names = workbook.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available sheets: {sheet_names}')
                return 0.0
            sheet_name = sheet_names[sheet_idx]
            sheet: Worksheet = workbook[sheet_name]
        else:
            if sheet_idx not in workbook.sheetnames:
                logger.error(f"Sheet '{sheet_idx}' not found. Available sheets: {workbook.sheetnames}")
                return 0.0
            sheet: Worksheet = workbook[sheet_idx]
        cell_coordinate = expected_state.get('cell')
        if not cell_coordinate:
            logger.error('Cell coordinate not specified in expected_state')
            return 0.0
        row_num = int(''.join(filter(str.isdigit, cell_coordinate)))
        expected_count = expected_state.get('value')
        service_col = None
        month_col = None
        amount_col = None
        for cell in sheet[1]:
            if cell.value:
                header_value = str(cell.value).strip().lower()
                if 'service' in header_value:
                    service_col = cell.column
                elif 'month' in header_value:
                    month_col = cell.column
                elif 'amount' in header_value:
                    amount_col = cell.column
        logger.info(f'Identified columns - Service: {service_col}, Month: {month_col}, Amount: {amount_col}')
        if service_col is None or month_col is None or amount_col is None:
            logger.warning('Could not identify all columns from headers, using default positions')
            service_col = 1
            month_col = 2
            amount_col = 3
        data_rows_before_target = 0
        for r in range(2, row_num):
            row_has_content = False
            for col in [service_col, month_col, amount_col]:
                if sheet.cell(row=r, column=col).value is not None:
                    row_has_content = True
                    break
            if row_has_content:
                data_rows_before_target = r - 1
        logger.info(f'Last data row before target row {row_num}: row {data_rows_before_target + 1}')
        if data_rows_before_target < 1:
            logger.warning(f'No existing data rows found before target row {row_num}. This suggests the file structure may be unexpected.')
        service_value = sheet.cell(row=row_num, column=service_col).value
        month_value = sheet.cell(row=row_num, column=month_col).value
        amount_value = sheet.cell(row=row_num, column=amount_col).value
        logger.info(f'Row {row_num} values - Service: {service_value}, Month: {month_value}, Amount: {amount_value}')
        total_checks = 4
        passed_checks = 0
        if service_value and str(service_value).strip() == 'Receipt Count':
            logger.info(f"✓ Service column correct: '{service_value}'")
            passed_checks += 1
        else:
            logger.warning(f"✗ Service column incorrect. Expected: 'Receipt Count', Got: '{service_value}'")
        if month_value is None or (isinstance(month_value, str) and month_value.strip() == ''):
            logger.info(f'✓ Month column is empty')
            passed_checks += 1
        else:
            logger.warning(f"✗ Month column not empty. Expected: empty, Got: '{month_value}'")
        if isinstance(expected_count, (int, float)) and isinstance(amount_value, (int, float)):
            if float(amount_value) == float(expected_count):
                logger.info(f'✓ Amount column correct: {amount_value} == {expected_count}')
                passed_checks += 1
            else:
                logger.warning(f'✗ Amount column incorrect. Expected: {expected_count}, Got: {amount_value}')
        elif amount_value == expected_count:
            logger.info(f'✓ Amount column correct: {amount_value} == {expected_count}')
            passed_checks += 1
        else:
            logger.warning(f'✗ Amount column incorrect. Expected: {expected_count}, Got: {amount_value}')
        expected_existing_rows = row_num - 2
        if data_rows_before_target >= 1 and service_value is not None:
            logger.info(f'✓ Target row {row_num} appears to contain new data (found {data_rows_before_target} data rows before it)')
            passed_checks += 1
        else:
            logger.warning(f'✗ Cannot verify that row {row_num} is a newly added row. Found {data_rows_before_target} data rows before it.')
        score = passed_checks / total_checks
        logger.info(f'Final score: {passed_checks}/{total_checks} checks passed = {score}')
        return score
    except Exception as e:
        logger.error(f'Error checking cell values: {e}', exc_info=True)
        return 0.0

def check_xlsx_sheet_swap__39f39486(result, expected, **options):
    """Check that first two sheets are swapped.

    Args:
        result: List with first two sheet names
        expected: Dict with 'first_two_sheets' list
        **options: Additional options

    Returns:
        float: 1.0 if both match, 0.5 if one matches, 0.0 otherwise
    """
    if not isinstance(result, list):
        return 0.0
    expected_first_two = expected.get('first_two_sheets', [])
    if len(result) < 2 or len(expected_first_two) < 2:
        return 0.0
    if result == expected_first_two:
        return 1.0
    matches = sum((1 for i in range(2) if i < len(result) and result[i] == expected_first_two[i]))
    return matches * 0.5

def check_calc_column_widths__3034b074583ce9ab21b47631e96b9a57(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if column widths have been adjusted (auto-fitted).

    Args:
        result: Dict with 'column_widths' from getter
        expected: Dict with validation rules (data_columns, min_changes)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'column_widths' not in result:
        return 0.0
    column_widths = result['column_widths']
    default_width = result.get('default_width', 8.43)
    TOLERANCE = 0.1
    data_columns = expected.get('data_columns', list(column_widths.keys()))
    changed_data_columns = []
    for col in data_columns:
        if col in column_widths:
            width = column_widths[col]
            if width is not None and abs(width - default_width) > TOLERANCE:
                changed_data_columns.append(col)
    if 'changed_columns' in expected:
        expected_cols = set(expected['changed_columns'])
        actual_cols = set(changed_data_columns)
        if expected_cols == actual_cols:
            return 1.0
        elif expected_cols.issubset(actual_cols):
            return 0.8
        else:
            return 0.0
    if 'min_changes' in expected:
        min_required = expected['min_changes']
        if len(changed_data_columns) >= min_required:
            return 1.0
        else:
            return len(changed_data_columns) / min_required if min_required > 0 else 0.0
    return 1.0 if len(changed_data_columns) > 0 else 0.0

def check_xlsx_sorted_asc__723ebfae(result, expected, **options):
    """Check if column values are sorted in ascending order.

    Args:
        result: List of cell values from getter
        expected: Expected sorted values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('values', [])
    if not isinstance(result, list):
        return 0.0
    if len(result) != len(expected_values):
        return 0.0
    correct_count = 0
    for (actual, expected_val) in zip(result, expected_values):
        try:
            if actual == expected_val:
                correct_count += 1
        except (ValueError, TypeError):
            pass
    return correct_count / len(expected_values) if expected_values else 0.0

def check_cell_highlighted__ff94cef0(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if a cell has highlighting/fill applied with the correct color.

    Args:
        result: Cell formatting info from getter
        expected: Dict with 'has_fill' (bool), optional 'value' and 'fill_color'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_value = expected.get('value')
    if expected_value is not None:
        if result.get('value') != expected_value:
            return 0.0
    expected_has_fill = expected.get('has_fill', True)
    if result.get('has_fill') != expected_has_fill:
        return 0.0
    expected_color = expected.get('fill_color')
    if expected_color is not None:
        result_color = result.get('fill_color')
