def check_xlsx_duplicates_highlighted__910e7ef5(result, expected, **options):
    """Check if duplicate names are highlighted correctly.

    Verifies that:
    1. ALL occurrences of duplicate names are highlighted
    2. Non-duplicate names are NOT highlighted
    3. Scoring based on cell-level accuracy

    Args:
        result: Dict with highlighted cells info from getter
        expected: Dict with expected duplicate names
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    expected_duplicates = expected.get('duplicate_names', [])
    highlighted_values = result.get('highlighted_values', [])
    non_highlighted_values = result.get('non_highlighted_values', [])
    all_cell_values = result.get('all_cell_values', [])
    if not expected_duplicates or not all_cell_values:
        return 0.0
    from collections import Counter
    all_counts = Counter(all_cell_values)
    should_be_highlighted = set((name for (name, count) in all_counts.items() if count > 1))
    should_not_be_highlighted = set((name for (name, count) in all_counts.items() if count == 1))
    expected_highlight_counts = {name: all_counts[name] for name in should_be_highlighted}
    highlighted_counts = Counter(highlighted_values)
    non_highlighted_counts = Counter(non_highlighted_values)
    correct_cells = 0
    total_cells = len(all_cell_values)
    for (dup_name, expected_count) in expected_highlight_counts.items():
        actual_highlighted = highlighted_counts.get(dup_name, 0)
        correct_cells += min(actual_highlighted, expected_count)
    for name in should_not_be_highlighted:
        actual_non_highlighted = non_highlighted_counts.get(name, 0)
        expected_non_highlighted = all_counts[name]
        correct_cells += min(actual_non_highlighted, expected_non_highlighted)
    score = correct_cells / total_cells if total_cells > 0 else 0.0
    return min(score, 1.0)

