def check_xlsx_total_row__621a0526(result: bytes, expected: Dict[str, Any], **options) -> float:
    """Check if Excel file has a total row added with correct sum.

    Args:
        result: Excel file content as bytes (vm_file result)
        expected: Expected rules dict with 'sheet', 'service_text', and 'total_value'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    import tempfile
    import os
    try:
        if not result or len(result) == 0:
            return 0.0
        file_path = None
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(result)
            file_path = tmp.name
        wb = openpyxl.load_workbook(file_path, data_only=True)
        os.unlink(file_path)
        sheet_idx = expected.get('sheet', 0)
        expected_text = expected.get('service_text', 'AWS Total')
        expected_total = expected.get('total_value', 0)
        if sheet_idx >= len(wb.sheetnames):
            return 0.0
        ws = wb.worksheets[sheet_idx]
        max_row = ws.max_row
        if max_row < 2:
            return 0.0
        header_row = list(ws.iter_rows(min_row=1, max_row=1, values_only=True))[0]
        amount_col_idx = None
        service_col_idx = 0
        for (idx, header) in enumerate(header_row):
            if header and 'amount' in str(header).lower():
                amount_col_idx = idx
            if header and 'service' in str(header).lower():
                service_col_idx = idx
        if amount_col_idx is None:
            amount_col_idx = 2
        score = 0.0
        found_total_row = False
        total_row_index = None
        for (idx, row) in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            if row and len(row) > max(service_col_idx, amount_col_idx):
                service = str(row[service_col_idx]) if row[service_col_idx] is not None else ''
                if expected_text.lower() in service.lower():
                    found_total_row = True
                    total_row_index = idx
                    score += 0.5
                    try:
                        actual_total = float(row[amount_col_idx]) if row[amount_col_idx] is not None else 0
                        if abs(actual_total - expected_total) < 0.01:
                            score += 0.5
                    except (ValueError, TypeError):
                        pass
                    break
        if found_total_row and total_row_index is not None:
            has_data_after = False
            for row in ws.iter_rows(min_row=total_row_index + 1, values_only=True):
                if row and any((cell is not None and str(cell).strip() for cell in row)):
                    has_data_after = True
                    break
            if has_data_after:
                score *= 0.9
        return min(1.0, score)
    except Exception as e:
        return 0.0

def check_xlsx_header_bold__b01b36e4(result, expected, **options):
    """
    Check if header row cells in an xlsx file are formatted as bold.

    Args:
        result: Path to the xlsx file (from vm_file getter)
        expected: Dict with 'sheet', 'row', and 'columns' keys
                  - sheet: Sheet index (0-based) or name
                  - row: Row number (1-based) for the header row
                  - columns: List of column letters (e.g., ["A", "B", "C"])
        **options: Additional options

    Returns:
        float: 1.0 if all specified cells are bold, 0.0 otherwise
    """
    if result is None or not os.path.exists(result):
        logger.error(f'Result file not found: {result}')
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=False)
        sheet_idx = expected.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        row_num = expected.get('row', 1)
        columns = expected.get('columns', [])
        if not columns:
            logger.error('No columns specified in expected configuration')
            return 0.0
        all_bold = True
        for col_letter in columns:
            cell_addr = f'{col_letter}{row_num}'
            cell = ws[cell_addr]
            is_bold = cell.font.bold if cell.font else False
            if is_bold:
                logger.info(f"Cell {cell_addr} is bold: '{cell.value}'")
            else:
                logger.error(f"Cell {cell_addr} is NOT bold: '{cell.value}'")
                all_bold = False
        if all_bold:
            logger.info(f'All header cells in row {row_num} columns {columns} are bold')
            return 1.0
        else:
            logger.error(f'Not all header cells in row {row_num} columns {columns} are bold')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking header bold formatting: {e}')
        return 0.0

def check_xlsx_sheet_cells__c18ab3d43b1c909fcfe0dd91da5bd04c(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if sheet cells match expected values and merge status.

    Args:
        result: Dict from getter with sheet data
        expected: Rules dict with sheet_name and cell checks
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'data' not in result:
        return 0.0
    sheet_name = expected.get('sheet_name')
    if not sheet_name or sheet_name not in result['data']:
        return 0.0
    sheet_data = result['data'][sheet_name]
    cells = sheet_data.get('cells', {})
    checks = expected.get('checks', [])
    if not checks:
        return 0.0
    passed = 0
    total = len(checks)
    for check in checks:
        cell_coord = check.get('coord')
        expected_value = check.get('value')
        expected_merged = check.get('merged')
        if cell_coord not in cells:
            continue
        cell_data = cells[cell_coord]
        if expected_value is not None:
            if cell_data['value'] == expected_value:
                if expected_merged is not None:
                    passed += 0.5
                else:
                    passed += 1
            else:
                continue
        if expected_merged is not None:
            if cell_data['merged'] == expected_merged:
                if expected_value is not None:
                    passed += 0.5
                else:
                    passed += 1
    return min(1.0, passed / total) if total > 0 else 0.0

