def check_xlsx_sheet_cells__b3f46920ac8342bdc9e139283e141eb9(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if sheet cells match expected values and merge status.

    Args:
        result: Dict from getter with sheet data
        expected: Rules dict with sheet_name, merged_groups, and non_merged_cells
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'data' not in result:
        return 0.0
    sheet_name = expected.get('sheet_name')
    if not sheet_name or sheet_name not in result['data']:
        return 0.0
    sheet_data = result['data'][sheet_name]
    cells = sheet_data.get('cells', {})
    passed = 0.0
    total = 0.0
    merged_groups = expected.get('merged_groups', [])
    for group in merged_groups:
        group_cells = group.get('cells', [])
        expected_value = group.get('value')
        expected_range = group.get('expected_range')
        if not group_cells:
            continue
        for cell_coord in group_cells:
            total += 1
            if cell_coord not in cells:
                continue
            cell_data = cells[cell_coord]
            if not cell_data.get('merged'):
                continue
            total += 1
            actual_range = cell_data.get('merged_range')
            if actual_range != expected_range:
                continue
            passed += 2
        if expected_value is not None:
            total += 1
            first_cell = group_cells[0]
            if first_cell in cells:
                if cells[first_cell].get('value') == expected_value:
                    passed += 1
    non_merged_cells = expected.get('non_merged_cells', [])
    for cell_coord in non_merged_cells:
        total += 1
        if cell_coord not in cells:
            continue
        cell_data = cells[cell_coord]
        if not cell_data.get('merged'):
            passed += 1
    return passed / total if total > 0 else 0.0

