def check_xlsx_column_width__7805c65b(result, expected, **options):
    """Check if column width meets criteria.

    Args:
        result: Column width from getter
        expected: Expected width criteria

    Returns:
        float: 1.0 if matches, 0.0 otherwise
    """
    if result is None:
        return 0.0
    method = expected.get('method', 'gt')
    ref_value = expected.get('value', 20)
    if method == 'gt':
        return 1.0 if result > ref_value else 0.0
    elif method == 'gte':
        return 1.0 if result >= ref_value else 0.0
    elif method == 'lt':
        return 1.0 if result < ref_value else 0.0
    elif method == 'lte':
        return 1.0 if result <= ref_value else 0.0
    elif method == 'eq':
        return 1.0 if abs(result - ref_value) < 0.1 else 0.0
    else:
        return 0.0

