def check_xlsx_borders__8a8ea694(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if all cells in the specified range have borders applied."""
    if result is None:
        return 0.0
    try:
        sheet_idx = expected.get('sheet', 0)
        check_range = expected.get('check_range', '')
        has_borders = expected.get('has_borders', True)
        if isinstance(sheet_idx, int):
            ws = result.worksheets[sheet_idx]
        else:
            ws = result[sheet_idx]
        if not check_range:
            result.close()
            return 0.0
        (min_col, min_row, max_col, max_row) = range_boundaries(check_range)
        total_cells = 0
        bordered_cells = 0
        for row in range(min_row, max_row + 1):
            for col in range(min_col, max_col + 1):
                cell = ws.cell(row=row, column=col)
                border = cell.border
                total_cells += 1
                if border:
                    has_any_border = border.left.style or border.right.style or border.top.style or border.bottom.style
                    if has_any_border:
                        bordered_cells += 1
        if has_borders:
            if bordered_cells == total_cells:
                result.close()
                return 1.0
            else:
                score = bordered_cells / total_cells
                result.close()
                return 1.0 if score >= 0.95 else 0.0
        elif bordered_cells == 0:
            result.close()
            return 1.0
        else:
            result.close()
            return 0.0
    except Exception:
        if result:
            try:
                result.close()
            except:
                pass
        return 0.0

