def check_xlsx_sheet_sorted__bcc8f272(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if Excel sheet matches expected rules.

    Validates:
    - Headers match expected headers
    - Row count meets minimum and exact requirements
    - Data is sorted by specified column
    - All movie titles contain 'The' (if required_substring is specified)

    Args:
        result: Dict with 'file_path' (path to Excel file) and 'sheet_name'
        expected: Rules dict containing:
            - headers: List of expected column headers
            - exact_rows: Expected exact number of data rows
            - min_rows: Minimum acceptable number of data rows
            - sort_column_idx: Column index to check for sorting (0-based)
            - descending: Whether sort should be descending (False = ascending)
            - required_substring: Optional substring that must appear in each title
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on scoring breakdown
    """
    if result is None:
        return 0.0
    try:
        file_path = result.get('file_path')
        sheet_name = result.get('sheet_name')
        if not file_path or not sheet_name:
            return 0.0
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            wb.close()
            return 0.0
        ws = wb[sheet_name]
        expected_headers = expected.get('headers', [])
        exact_rows = expected.get('exact_rows')
        min_rows = expected.get('min_rows')
        sort_column_idx = expected.get('sort_column_idx', 0)
        descending = expected.get('descending', False)
        required_substring = expected.get('required_substring')
        score = 0.0
        actual_headers = []
        for cell in ws[1]:
            actual_headers.append(cell.value)
        normalized_actual = [str(h).lower().strip() if h else '' for h in actual_headers]
        normalized_expected = [str(h).lower().strip() for h in expected_headers]
        if normalized_actual == normalized_expected:
            score += 0.2
        data_rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if any((cell is not None and str(cell).strip() for cell in row)):
                data_rows.append(row)
        num_rows = len(data_rows)
        if min_rows is not None and num_rows >= min_rows:
            score += 0.2
        if exact_rows is not None and num_rows == exact_rows:
            score += 0.2
        if required_substring is not None and num_rows > 0:
            all_contain_substring = True
            for row in data_rows:
                if len(row) > 0:
                    title = row[0]
                    if title is None or required_substring.lower() not in str(title).lower():
                        all_contain_substring = False
                        break
            if not all_contain_substring:
                return score * 0.2
        if num_rows > 0:
            sort_values = []
            for row in data_rows:
                if sort_column_idx < len(row):
                    val = row[sort_column_idx]
                    sort_values.append(val)
                else:
                    sort_values.append(None)
            non_none_values = [v for v in sort_values if v is not None]
            none_count = len(sort_values) - len(non_none_values)
            if non_none_values:
                sorted_non_none = sorted(non_none_values, reverse=descending)
                expected_sorted = sorted_non_none + [None] * none_count
                if sort_values == expected_sorted:
                    score += 0.4
        wb.close()
        return score
    except Exception as e:
        return 0.0

def check_pivot_week__b35ebe18(result, expected, **options):
    """Check if pivot table has week data with sufficient entries.

    Args:
        result: dict with 'has_numeric_data' and 'entry_count'
        expected: dict with 'has_numeric_data' and 'min_entries'
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    has_data = result.get('has_numeric_data', False)
    entry_count = result.get('entry_count', 0)
    min_entries = expected.get('min_entries', 1)
    if not has_data:
        return 0.0
    if entry_count >= min_entries:
        return 1.0
    else:
        return max(0.0, entry_count / min_entries)

def check_xlsx_employee_order__e01489de2ab1797e3760671ef906919d(result: Dict[str, List], expected: Dict[str, Any], **options) -> float:
    """
    Verify that employees are sorted by Employee ID in ascending order.

    Args:
        result: Dict with 'names' (list of employee names) and 'ids' (list of employee IDs)
        expected: Expected order (from rules) with 'expected_order' (names) and 'expected_ids'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_order = expected.get('expected_order', [])
    expected_ids = expected.get('expected_ids', [11223, 12345, 44556, 67890, 77889, 88901, 99012])
    result_names = result.get('names', [])
    result_ids = result.get('ids', [])
    if not expected_order or not result_names:
        return 0.0
    if result_ids != expected_ids:
        if result_ids == sorted(result_ids):
            partial_score = 0.5
        else:
            return 0.0
    else:
        partial_score = 0.7
    if result_names == expected_order:
        return 1.0
    correct_positions = 0
    min_len = min(len(result_names), len(expected_order))
    for i in range(min_len):
        if result_names[i] == expected_order[i]:
            correct_positions += 1
    name_score = correct_positions / len(expected_order) if expected_order else 0.0
    return partial_score * 0.7 + name_score * 0.3

