def check_thunderbird_xlsx_content__ec6d7e2a(result: Dict[str, Any], expected: Any, **options) -> float:
    """
    Compare xlsx data from Thunderbird email export against expected values.

    Validates:
    - Column headers are correct
    - Row count matches expected
    - Cell values match expected (with flexible date parsing)

    NOTE: This evaluator has inherent limitations:
    - Cannot verify emails came from 'daily folder' (only checks final xlsx output)
    - Cannot verify these are the 'first 7 emails' (agent could cherry-pick matching data)
    - These limitations are acceptable as we validate the final output correctness

    Args:
        result: Dict with 'headers' and 'data' keys from getter
        expected: Dict with 'expected_data' key containing expected rows
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(expected, dict) or not isinstance(result, dict):
        return 0.0
    expected_data = expected.get('expected_data', [])
    actual_headers = result.get('headers', [])
    actual_data = result.get('data', [])
    expected_headers = ['sender_name', 'subject', 'date', 'cc']
    if len(actual_headers) != len(expected_headers):
        return 0.0
    for (actual_h, expected_h) in zip(actual_headers, expected_headers):
        if actual_h != expected_h:
            return 0.0
    if len(actual_data) != len(expected_data):
        return 0.0
    for (i, (actual_row, expected_row)) in enumerate(zip(actual_data, expected_data)):
        if len(actual_row) != len(expected_row):
            return 0.0
        for (j, (actual_cell, expected_cell)) in enumerate(zip(actual_row, expected_row)):
            actual_norm = str(actual_cell).strip()
            expected_norm = str(expected_cell).strip()
            if j == 2:
                if not _compare_dates(actual_norm, expected_norm):
                    return 0.0
            elif actual_norm != expected_norm:
                return 0.0
    return 1.0

