def check_xlsx_first_row_match__e9cbe8d5d63bcae148f15303a9be4cd6(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Order ID column is sorted in ascending order and first row matches expected values.

    Args:
        result: Dict with 'order_ids' (list of Order ID values) and 'first_row' (dict of first row values)
        expected: Dict with expected column values (from rules)
        **options: Additional options

    Returns:
        1.0 if Order IDs are sorted ascending and first row matches expected, 0.0 otherwise
    """
    if not result:
        return 0.0
    order_ids = result.get('order_ids', [])
    if not order_ids:
        return 0.0
    for i in range(len(order_ids) - 1):
        if order_ids[i] > order_ids[i + 1]:
            return 0.0
    first_row = result.get('first_row', {})
    expected_values = expected.get('expected_values', {})
    if not first_row or not expected_values:
        return 1.0 if not expected_values else 0.0
    for (col_name, expected_val) in expected_values.items():
        actual_val = first_row.get(col_name)
        if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
            if abs(actual_val - expected_val) >= 0.01:
                return 0.0
        elif actual_val != expected_val:
            return 0.0
    return 1.0

def check_xlsx_cell_contains__f6055ba6(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Check if a cell value contains a specific keyword.

    Args:
        result: The actual cell value (string)
        expected: Dict with validation rules directly (when expected.type='rule',
                  the framework calls get_rule() which returns config['rules'] directly):
            - 'contains': The keyword to search for
            - 'case_sensitive': Whether the search is case-sensitive (default: False)
        **options: Additional options

    Returns:
        float: 1.0 if the cell contains the keyword, 0.0 otherwise
    """
    if not result:
        return 0.0
    keyword = expected.get('contains', '')
    case_sensitive = expected.get('case_sensitive', False)
    if not keyword:
        return 0.0
    if case_sensitive:
        return 1.0 if keyword in result else 0.0
    else:
        return 1.0 if keyword.lower() in result.lower() else 0.0

def check_xlsx_highlighting__462e6eae(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if correct cells are highlighted with correct color.
    
    Args:
        result: Result from getter (dict with 'highlighted_cells')
        expected: Expected cells and color from rules
        **options: Additional options
        
    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or 'highlighted_cells' not in result:
        return 0.0
    expected_cells = set(expected.get('cells', []))
    expected_color = expected.get('color', '').lower().replace('#', '')
    highlighted = result['highlighted_cells']
    correct_count = 0
    highlighted_set = set()
    extra_cells = []
    for item in highlighted:
        cell_addr = item['cell']
        cell_color = item.get('color', '').lower()
        highlighted_set.add(cell_addr)
        if cell_addr in expected_cells:
            if cell_color == expected_color:
                correct_count += 1
        else:
            extra_cells.append(cell_addr)
    total_expected = len(expected_cells)
    if total_expected == 0:
        return 1.0
    base_score = correct_count / total_expected
    if extra_cells:
        num_extra = len(extra_cells)
        penalty = min(0.5, 0.1 * num_extra)
        penalty_factor = 1.0 - penalty
    else:
        penalty_factor = 1.0
    score = base_score * penalty_factor
    return min(1.0, max(0.0, score))

def check_thunderbird_email_xlsx__c6bff852(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Validate Thunderbird email extraction XLSX file.

    Checks:
    1. Header row contains correct column names
    2. Exactly 6 emails are present
    3. Email data matches expected values
    4. Emails are sorted chronologically (oldest to newest)

    Args:
        result: Path to result XLSX file
        expected: Dict with 'email_data' (list of lists) and 'columns' (list of column names)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.active
        expected_data = expected.get('email_data', [])
        expected_columns = expected.get('columns', [])
        num_emails = len(expected_data)
        num_cols = len(expected_columns)
        header_valid = True
        for col_idx in range(num_cols):
            header_value = ws.cell(1, col_idx + 1).value
            if header_value is None:
                header_valid = False
                break
            header_value_str = str(header_value).strip().lower()
            expected_header = expected_columns[col_idx].strip().lower()
            if header_value_str != expected_header:
                header_valid = False
                break
        if not header_valid:
            return 0.0
        data_row_count = 0
        for row_idx in range(2, ws.max_row + 1):
            has_content = False
            for col_idx in range(1, num_cols + 1):
                if ws.cell(row_idx, col_idx).value is not None:
                    has_content = True
                    break
            if has_content:
                data_row_count += 1
        if data_row_count != num_emails:
            return 0.0
        total_checks = num_emails * num_cols
        correct_checks = 0
        for row_idx in range(num_emails):
            expected_row = expected_data[row_idx]
            actual_row_idx = row_idx + 2
            for col_idx in range(num_cols):
                cell_value = ws.cell(actual_row_idx, col_idx + 1).value
                expected_value = expected_row[col_idx]
                if cell_value is not None:
                    cell_value_str = str(cell_value).strip()
                else:
                    cell_value_str = ''
                expected_value_str = str(expected_value).strip()
                if cell_value_str == expected_value_str:
                    correct_checks += 1
        if correct_checks != total_checks:
            return correct_checks / total_checks if total_checks > 0 else 0.0
        dates = []
        subject_col_idx = None
        for col_idx in range(num_cols):
            if expected_columns[col_idx].lower() == 'subject':
                subject_col_idx = col_idx
                break
        if subject_col_idx is not None:
            for row_idx in range(num_emails):
                actual_row_idx = row_idx + 2
                subject = ws.cell(actual_row_idx, subject_col_idx + 1).value
                parsed_date = None
                if subject:
                    subject_str = str(subject).strip()
                    date_pattern1 = '\\(?\\b(\\d{1,2})\\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)\\s+(\\d{4})\\b\\)?'
                    match1 = re.search(date_pattern1, subject_str, re.IGNORECASE)
                    if match1:
                        day = match1.group(1)
                        month = match1.group(2)
                        year = match1.group(3)
                        date_str = f'{day} {month} {year}'
                        try:
                            parsed_date = datetime.strptime(date_str, '%d %b %Y')
                        except ValueError:
                            pass
                    if parsed_date is None:
                        date_pattern2 = '\\b(\\d{4})\\b'
                        match2 = re.search(date_pattern2, subject_str)
                        if match2:
                            mmdd_str = match2.group(1)
                            if len(mmdd_str) == 4:
                                try:
                                    month_num = int(mmdd_str[:2])
                                    day_num = int(mmdd_str[2:])
                                    if 1 <= month_num <= 12 and 1 <= day_num <= 31:
                                        parsed_date = datetime(2024, month_num, day_num)
                                except ValueError:
                                    pass
                if parsed_date:
                    dates.append(parsed_date)
            if len(dates) != num_emails:
                return 0.5
            for i in range(len(dates) - 1):
                if dates[i] > dates[i + 1]:
                    return 0.5
        return 1.0
    except Exception as e:
        return 0.0

