def check_xlsx_pass_fail_formulas__250d25333050b1223301c3f7022accab(result, expected, **options):
    """Check if Pass/Fail/Held formulas are correctly applied.

    Verifies two things:
    1. Formulas exist in all required rows (not manually typed values)
    2. Calculated results match expected values

    Args:
        result: dict with 'formulas' (row->formula) and 'values' (row->value)
        expected: dict with 'rules' containing expected mappings
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    formulas = result.get('formulas', {})
    values = result.get('values', {})
    rules = expected
    expected_values = rules.get('expected_values', {})
    if not expected_values:
        return 0.0
    correct = 0
    total = len(expected_values)
    for (row_str, expected_val) in expected_values.items():
        row = int(row_str)
        has_formula = row in formulas and formulas[row] is not None
        actual_val = values.get(row, None)
        correct_value = actual_val == expected_val
        if has_formula and correct_value:
            correct += 1
    return correct / total if total > 0 else 0.0

