def check_xlsx_average_value__8d510ae714d061a8ca29f27b3ad7923b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the calculated average values match expected values for all sales reps.

    This metric verifies:
    1. The column header is correctly labeled as "Average"
    2. All sales reps have calculated averages in column H
    3. The averages are mathematically correct (within tolerance)

    Args:
        result: Dict from getter containing:
            - header: The column header value
            - averages: List of calculated averages
            - row_count: Number of data rows
        expected: Dict (rules) containing:
            - expected_header: Expected column header (default "Average")
            - expected_averages: List of expected average values for each rep
            - min_row_count: Minimum number of rows expected (optional)
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0 based on:
            - Header correctness (weight: 0.2)
            - Row count match (weight: 0.2)
            - Average values correctness with partial credit (weight: 0.6)
    """
    score = 0.0
    header_weight = 0.2
    count_weight = 0.2
    averages_weight = 0.6
    result_header = result.get('header')
    expected_header = expected.get('expected_header', 'Average')
    if result_header is not None:
        if str(result_header).strip().lower() == expected_header.lower():
            score += header_weight
    result_count = result.get('row_count', 0)
    expected_averages_list = expected.get('expected_averages', [])
    min_row_count = expected.get('min_row_count', len(expected_averages_list))
    if result_count >= min_row_count and min_row_count > 0:
        score += count_weight
    result_averages = result.get('averages', [])
    if expected_averages_list and result_averages:
        tolerance = options.get('tolerance', 0.01)
        correct_count = 0
        max_checks = min(len(result_averages), len(expected_averages_list))
        for i in range(max_checks):
            try:
                result_val = float(result_averages[i])
                expected_val = float(expected_averages_list[i])
                if abs(result_val - expected_val) <= tolerance:
                    correct_count += 1
            except (ValueError, TypeError):
                pass
        if len(expected_averages_list) > 0:
            averages_score = correct_count / len(expected_averages_list)
            score += averages_weight * averages_score
    return min(score, 1.0)

