def check_xlsx_comma_format__50457e3e(result, expected, **options):
    """Check if cells in column B contain comma-formatted values with 2 decimals.

    Args:
        result: File bytes from VM
        expected: Dict with 'rules' containing 'sheet' and 'values' dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        expected_values = expected.get('values', {})
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(result)
            tmp_path = tmp.name
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        correct = 0
        total = len(expected_values)
        for (cell_addr, expected_val) in expected_values.items():
            actual_val = ws[cell_addr].value
            actual_str = str(actual_val).strip() if actual_val is not None else ''
            expected_str = str(expected_val).strip()
            if actual_str == expected_str:
                correct += 1
            elif isinstance(actual_val, (int, float)):
                formatted = f'{actual_val:,.2f}'
                if formatted == expected_str:
                    correct += 1
        wb.close()
        import os
        os.unlink(tmp_path)
        return correct / total if total > 0 else 0.0
    except Exception as e:
        print(f'Error in check_xlsx_comma_format__50457e3e: {e}')
        return 0.0

