def check_xlsx_font_color__8241b6ab(result, expected, **options):
    """Check if cell font color matches expected color.

    Args:
        result: Font color from getter (hex string or theme marker)
        expected: Expected color (hex string like 'FFFF0000' for red)
        **options: Options like 'color_tolerance' and 'strict_color_match'

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    strict_match = options.get('strict_color_match', False)
    tolerance = options.get('color_tolerance', 20)
    if isinstance(result, str) and result.startswith('theme_'):
        if expected.upper() in ['FFFF0000', 'FF0000', 'RED']:
            return 1.0 if result == 'theme_1' else 0.0
        return 0.0
    result_str = str(result).upper().replace('#', '')
    expected_str = str(expected).upper().replace('#', '')
    if len(result_str) == 8:
        result_str = result_str[2:]
    if len(expected_str) == 8:
        expected_str = expected_str[2:]
    if strict_match:
        return 1.0 if result_str == expected_str else 0.0
    try:
        (r1, g1, b1) = (int(result_str[0:2], 16), int(result_str[2:4], 16), int(result_str[4:6], 16))
        (r2, g2, b2) = (int(expected_str[0:2], 16), int(expected_str[2:4], 16), int(expected_str[4:6], 16))
        distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
        return 1.0 if distance <= tolerance else 0.0
    except:
        return 0.0

