def check_xlsx_sorted_desc__f634ad45f361e5517df392d47fa16327(result, expected, **options):
    """Check if values are sorted in descending order and match expected top values.

    Args:
        result: List of values from the getter (actual order after sorting)
        expected: Dict with 'top_values' (list of expected top N values in order)
        **options: Additional options (e.g., 'check_count' - number of top values to verify)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    score = 0.0
    check_count = options.get('check_count', 3)
    is_descending = all((result[i] >= result[i + 1] for i in range(len(result) - 1) if result[i] is not None and result[i + 1] is not None))
    if is_descending:
        score += 0.5
    top_values = expected.get('top_values', [])
    if top_values:
        matches = 0
        for i in range(min(check_count, len(top_values), len(result))):
            if result[i] == top_values[i]:
                matches += 1
        if matches > 0:
            score += 0.5 * (matches / min(check_count, len(top_values)))
    return score

