def check_discount_amount_calc__5a9414a5(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Compare discount_amount calculations against expected values.

    Args:
        result: Dict from getter with cell values
        expected: Dict with expected values
        **options: Additional options (tolerance for float comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    checks = 0
    passes = 0
    for (cell, exp_value) in expected.items():
        if cell in result:
            checks += 1
            if result[cell] is not None and exp_value is not None:
                if abs(result[cell] - exp_value) <= tolerance:
                    passes += 1
    if checks > 0:
        score = passes / checks
    return score

def check_xlsx_column_values__0d2468a3fcca7c65f4477d321a5ee11a(result: List[Any], expected: Any, **options) -> float:
    """Check if column values match the expected list of values.

    Args:
        result: Actual column values from getter (list)
        expected: Expected values from rules (dict with 'values' key containing list)
        **options: Additional comparison options

    Returns:
        1.0 if all values match in order, partial credit for partial matches, 0.0 for no match
    """
    expected_values = expected.get('values', [])
    if not expected_values:
        return 0.0
    result_filtered = [v for v in result if v is not None]
    if result_filtered == expected_values:
        return 1.0
    matches = 0
    for i in range(min(len(result_filtered), len(expected_values))):
        if i < len(result_filtered) and i < len(expected_values):
            if result_filtered[i] == expected_values[i]:
                matches += 1
    if len(expected_values) > 0:
        return matches / len(expected_values)
    return 0.0

