        if not os.path.exists(result):
            return 0.0
        wb = openpyxl.load_workbook(result, data_only=False)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_coord]
        is_bold = cell.font and cell.font.bold
