def check_xlsx_data__f77d3051(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    if 'min_rows' in expected:
        total_checks += 1
        if len(result) >= expected['min_rows']:
            score += 1.0
    if 'headers' in expected:
        total_checks += 1
        expected_headers = expected['headers']
        if len(result) > 0 and result[0]:
            if len(result[0]) >= len(expected_headers):
                actual_headers = [str(cell).strip() if cell is not None else '' for cell in result[0][:len(expected_headers)]]
                if actual_headers == expected_headers:
                    score += 1.0
    if 'filenames' in expected:
        total_checks += 1
        expected_filenames = expected['filenames']
        if isinstance(result, list) and len(result) >= len(expected_filenames) + 1:
            all_rows_valid = True
            for i in range(1, len(expected_filenames) + 1):
                if i >= len(result) or not result[i] or len(result[i]) < 2:
                    all_rows_valid = False
                    break
            if all_rows_valid:
                actual_filenames = [str(result[i][0]).strip() if result[i][0] is not None else '' for i in range(1, len(expected_filenames) + 1)]
                actual_uppercase = [str(result[i][1]).strip() if result[i][1] is not None else '' for i in range(1, len(expected_filenames) + 1)]
                actual_filenames_lower = [f.lower() for f in actual_filenames]
                expected_filenames_lower = [f.lower() for f in expected_filenames]
                filenames_match = sorted(actual_filenames_lower) == sorted(expected_filenames_lower)
                uppercase_correct = all((actual_uppercase[i] == actual_filenames[i].upper() for i in range(len(actual_filenames))))
                if filenames_match and uppercase_correct:
                    score += 1.0
    if 'count' in expected:
        total_checks += 1
        if len(result) > 1 and len(result[1]) > 1:
            try:
                count_val = int(result[1][1])
                if count_val == expected['count']:
                    score += 1.0
            except:
                pass
    return score / total_checks if total_checks > 0 else 0.0

