def check_xlsx_text_format__c7d836f9(result_state: Optional[str], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the cell text matches the expected formatted text.

    This validates that a formula in LibreOffice Calc correctly formats a number
    with the proper decimal places within concatenated text.

    Scoring: Binary - 1.0 if exact match, 0.0 otherwise

    Args:
        result_state: The actual cell text from the getter (str)
        expected_state: Dict containing:
            - When type='rule', the 'rules' field is passed directly as expected_state (str)
        **options: Additional options

    Returns:
        float: 1.0 if the text matches exactly, 0.0 otherwise
    """
    if result_state is None:
        logger.warning('Result state is None')
        return 0.0
    if isinstance(expected_state, str):
        expected_text = expected_state
    elif isinstance(expected_state, dict):
        expected_text = expected_state.get('rules') or expected_state.get('expected') or expected_state.get('text')
    else:
        logger.error(f'Unexpected expected_state type: {type(expected_state)}')
        return 0.0
    if expected_text is None:
        logger.error('Could not extract expected text from expected_state')
        return 0.0
    result_normalized = result_state.strip()
    expected_normalized = expected_text.strip()
    logger.info(f"Comparing result: '{result_normalized}' with expected: '{expected_normalized}'")
    if result_normalized == expected_normalized:
        logger.info('Text matches exactly - PASS')
        return 1.0
    else:
        logger.warning(f'Text mismatch - FAIL')
        logger.warning(f"  Expected: '{expected_normalized}'")
        logger.warning(f"  Got:      '{result_normalized}'")
        return 0.0

