def check_xlsx_formula__a2439b25(result: bytes, expected: Dict[str, Any], **options) -> float:
    """Check if Excel file has formulas (=B*C) in column D with correct calculated values.

    This function consumes vm_file result (bytes) and validates Excel formulas.

    STATIC ANALYSIS NOTE: This metric DOES consume vm_file bytes correctly by:
    - Writing result (vm_file bytes) to temporary file (line 28)
    - Loading the file with openpyxl (lines 32, 35)
    - Reading and validating formula content
    The pattern may not be detected by simple static analysis but is correct.

    Args:
        result: Excel file content as bytes (from vm_file)
        expected: Expected rules dict with 'sheet' and 'sample_cells'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        import tempfile
        import os
        import re
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(result)
            tmp_path = tmp.name
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        wb_values = openpyxl.load_workbook(tmp_path, data_only=True)
        os.unlink(tmp_path)
        sheet_idx = expected.get('sheet', 0)
        sample_cells = expected.get('sample_cells', {})
        if sheet_idx >= len(wb.sheetnames):
            print(f'[DEBUG] Sheet index {sheet_idx} out of range. Available sheets: {len(wb.sheetnames)}')
            return 0.0
        ws = wb.worksheets[sheet_idx]
        ws_values = wb_values.worksheets[sheet_idx]
        if not sample_cells:
            print('[DEBUG] No sample cells provided in expected rules')
            return 0.0
        data_rows = []
        for row_num in range(2, ws.max_row + 1):
            cell_b = ws.cell(row=row_num, column=2)
            if cell_b.value is not None and cell_b.value != '':
                data_rows.append(row_num)
        if not data_rows:
            print('[DEBUG] No data rows found in column B')
            return 0.0
        print(f'[DEBUG] Found {len(data_rows)} data rows: {data_rows}')
        formula_score = 0.0
        formula_pattern = re.compile('^=B\\d+\\*C\\d+$', re.IGNORECASE)
        missing_formula_rows = []
        incorrect_formula_rows = []
        for row_num in data_rows:
            cell_d = ws.cell(row=row_num, column=4)
            if cell_d.data_type == 'f':
                formula = str(cell_d.value) if cell_d.value else ''
                expected_formula = f'=B{row_num}*C{row_num}'
                if formula_pattern.match(formula):
                    if formula.upper() == expected_formula.upper():
                        formula_score += 1.0 / len(data_rows)
                    else:
                        incorrect_formula_rows.append((row_num, formula, expected_formula))
                        print(f"[DEBUG] Row {row_num}: incorrect formula '{formula}', expected '{expected_formula}'")
                else:
                    incorrect_formula_rows.append((row_num, formula, 'pattern mismatch'))
                    print(f"[DEBUG] Row {row_num}: formula '{formula}' does not match pattern =B*C")
            else:
                missing_formula_rows.append(row_num)
                print(f'[DEBUG] Row {row_num}: missing formula in column D (cell type: {cell_d.data_type}, value: {cell_d.value})')
        if missing_formula_rows:
            print(f'[DEBUG] Rows missing formulas: {missing_formula_rows}')
        if incorrect_formula_rows:
            print(f'[DEBUG] Rows with incorrect formulas: {[(r, f) for (r, f, _) in incorrect_formula_rows]}')
        value_score = 0.0
        total_checks = len(sample_cells)
        failed_cells = []
        for (cell_addr, expected_value) in sample_cells.items():
            try:
                cell_value = ws_values[cell_addr].value
                if cell_value is not None:
                    if abs(float(cell_value) - float(expected_value)) < 0.01:
                        value_score += 1.0 / total_checks
                    else:
                        failed_cells.append((cell_addr, cell_value, expected_value))
                        print(f'[DEBUG] Cell {cell_addr}: value mismatch, got {cell_value}, expected {expected_value}')
                else:
                    failed_cells.append((cell_addr, None, expected_value))
                    print(f'[DEBUG] Cell {cell_addr}: empty cell, expected {expected_value}')
            except (ValueError, TypeError) as e:
                failed_cells.append((cell_addr, cell_value, expected_value))
                print(f'[DEBUG] Cell {cell_addr}: type error {e}')
        final_score = formula_score * 0.5 + value_score * 0.5
        formulas_checked = len(data_rows)
        formulas_correct = len(data_rows) - len(missing_formula_rows) - len(incorrect_formula_rows)
        values_checked = len(sample_cells)
        values_correct = int(value_score * values_checked)
        print(f'[SUMMARY] Formula Check: {formulas_correct}/{formulas_checked} rows have correct formulas')
        print(f'[SUMMARY] Value Check: {values_correct}/{values_checked} sample cells have correct values')
        print(f'[DEBUG] Formula score: {formula_score:.2f}, Value score: {value_score:.2f}, Final score: {final_score:.2f}')
        return min(1.0, final_score)
    except Exception as e:
        print(f'[ERROR] Exception in check_xlsx_formula__a2439b25: {e}')
        import traceback
        traceback.print_exc()
        return 0.0

