def check_xlsx_quality_summary__2b545177235b3e1989bf6e21bc344c53(result: Dict[str, int], expected: Dict[str, Any], **options) -> float:
    """
    Verify that the summary counts match expected values.

    Args:
        result: Dict of rating levels to counts from result getter
        expected: Expected counts (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_counts = expected.get('expected_counts', {})
    if not expected_counts:
        return 0.0
    total_ratings = len(expected_counts)
    correct_count = 0
    for (rating, expected_value) in expected_counts.items():
        if rating not in result:
            continue
        if result[rating] == expected_value:
            correct_count += 1
    all_present = all((rating in result for rating in expected_counts.keys()))
    if not all_present:
        return 0.0
    return correct_count / total_ratings if total_ratings > 0 else 0.0

