def check_xlsx_sheet_content__7018e3cb(result, expected, **options):
    """Check if Excel sheet contains the expected movies data.

    Args:
        result: Path to result Excel file
        expected: Dict with expected sheet configuration
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        wb_result = openpyxl.load_workbook(result, data_only=True)
        sheet_name = expected.get('sheet_name', 'masterpieces')
        expected_count = expected.get('expected_count', 5)
        year_min = expected.get('year_min', 1920)
        year_max = expected.get('year_max', 2019)
        rating_min = expected.get('rating_min', 9.0)
        if sheet_name not in wb_result.sheetnames:
            return 0.0
        ws = wb_result[sheet_name]
        headers = [cell.value for cell in ws[1]]
        expected_headers = ['title', 'release year', 'ratings', 'description']
        if headers != expected_headers:
            return 0.2
        data_rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0]:
                data_rows.append(row)
        if len(data_rows) != expected_count:
            return 0.4
        score = 0.4
        all_valid = True
        for row in data_rows:
            (title, year, rating, desc) = row
            if not (year_min <= int(year) <= year_max and float(rating) >= rating_min):
                all_valid = False
                break
        if all_valid:
            score = 0.7
        ratings = [float(row[2]) for row in data_rows]
        if ratings == sorted(ratings, reverse=True):
            score = 1.0
        return score
    except Exception as e:
        return 0.0

def check_xlsx_quarterly_totals__9f2b77cf1987fbf5182e711b0cf8716f(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if quarterly totals (Q1 and Q2) are calculated correctly and headers are set.

    Scoring:
    - 0.05: Q1 header is correct
    - 0.05: Q2 header is correct
    - 0.45: Q1 totals are correct
    - 0.45: Q2 totals are correct

    Args:
        result: Dict from getter with 'q1_header', 'q2_header', 'q1_totals' and 'q2_totals'
        expected: Dict with 'q1_header', 'q2_header', 'q1_totals' and 'q2_totals' - expected values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_q1_header = expected.get('q1_header', '')
    expected_q2_header = expected.get('q2_header', '')
    expected_q1 = expected.get('q1_totals', {})
    expected_q2 = expected.get('q2_totals', {})
    result_q1_header = result.get('q1_header', '')
    result_q2_header = result.get('q2_header', '')
    result_q1 = result.get('q1_totals', {})
    result_q2 = result.get('q2_totals', {})
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    if expected_q1_header and result_q1_header == expected_q1_header:
        score += 0.05
    if expected_q2_header and result_q2_header == expected_q2_header:
        score += 0.05
    if expected_q1 and result_q1:
        correct_q1 = 0
        total_q1 = len(expected_q1)
        for (row_idx, expected_val) in expected_q1.items():
            result_val = result_q1.get(row_idx, 0)
            if abs(result_val - expected_val) <= tolerance:
                correct_q1 += 1
        if total_q1 > 0:
            score += 0.45 * (correct_q1 / total_q1)
    if expected_q2 and result_q2:
        correct_q2 = 0
        total_q2 = len(expected_q2)
        for (row_idx, expected_val) in expected_q2.items():
            result_val = result_q2.get(row_idx, 0)
            if abs(result_val - expected_val) <= tolerance:
                correct_q2 += 1
        if total_q2 > 0:
            score += 0.45 * (correct_q2 / total_q2)
    return min(score, 1.0)

