def check_xlsx_table_copy__0f4ec0a9(result, expected, **options):
    """Check if a table has been copied correctly to a new location.

    Args:
        result: List of lists from getter (copied table)
        expected: Expected table data
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 with partial credit
    """
    if result is None or expected is None:
        return 0.0
    if len(result) != len(expected):
        return 0.0
    score = 0.0
    total_cells = sum((len(row) for row in expected))
    for (result_row, expected_row) in zip(result, expected):
        if len(result_row) != len(expected_row):
            return 0.0
        for (r_cell, e_cell) in zip(result_row, expected_row):
            if r_cell == e_cell:
                score += 1.0 / total_cells
    return score

def check_thunderbird_email_xlsx__69cdec6f(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Validate Thunderbird email extraction XLSX file.

    Args:
        result: Path to result XLSX file
        expected: Dict with 'email_data' (list of lists) and 'columns' (list of column names)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.active
        expected_data = expected.get('email_data', [])
        expected_columns = expected.get('columns', [])
        num_emails = len(expected_data)
        num_cols = len(expected_columns)
        if ws.max_row < num_emails + 1:
            return 0.0
        header_row = []
        for col_idx in range(1, ws.max_column + 1):
            cell_value = ws.cell(1, col_idx).value
            if cell_value is not None:
                header_row.append(str(cell_value).strip())
            else:
                header_row.append('')
        if header_row != expected_columns:
            return 0.0
        if ws.max_column != len(expected_columns):
            return 0.0
        score = 0.0
        total_checks = num_emails * num_cols
        correct_checks = 0
        for row_idx in range(num_emails):
            expected_row = expected_data[row_idx]
            actual_row_idx = row_idx + 2
            for col_idx in range(num_cols):
                cell_value = ws.cell(actual_row_idx, col_idx + 1).value
                expected_value = expected_row[col_idx]
                if cell_value is not None:
                    cell_value_str = str(cell_value).strip()
                else:
                    cell_value_str = ''
                expected_value_str = str(expected_value).strip()
                if cell_value_str == expected_value_str:
                    correct_checks += 1
        subject_col_idx = None
        for (idx, col_name) in enumerate(expected_columns):
            if col_name == 'subject':
                subject_col_idx = idx + 1
                break
        if subject_col_idx is not None:
            dates = []
            for row_idx in range(2, 2 + num_emails):
                subject_value = ws.cell(row_idx, subject_col_idx).value
                if subject_value is not None:
                    subject_str = str(subject_value).strip()
                    date_match = re.search('\\((\\d{1,2})\\s+([A-Z]{3})\\s+(\\d{4})\\)', subject_str)
                    if date_match:
                        day = int(date_match.group(1))
                        month_str = date_match.group(2)
                        year = int(date_match.group(3))
                        try:
                            date_obj = datetime.strptime(f'{day} {month_str} {year}', '%d %b %Y')
                            dates.append(date_obj)
                        except:
                            pass
            if len(dates) == num_emails:
                for i in range(len(dates) - 1):
                    if dates[i] > dates[i + 1]:
                        score = correct_checks / total_checks if total_checks > 0 else 0.0
                        return score * 0.5
        score = correct_checks / total_checks if total_checks > 0 else 0.0
        return score
    except Exception as e:
        return 0.0

def check_xlsx_cell_colors__d20188d4(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if specified cells have the expected background color.

    Args:
        result: Dict mapping cell coordinates to their hex color values (from getter)
        expected: Dict with 'cells' (list of cell coords) and 'color' (expected hex color)
        **options: Additional options (tolerance for color matching, etc.)

    Returns:
        float: Score between 0.0 and 1.0 (proportion of cells with correct color)
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', [])
    expected_color = expected.get('color', '').upper()
    if not expected_cells or not expected_color:
        return 0.0
    if not expected_color.startswith('#'):
        expected_color = f'#{expected_color}'
    expected_color = expected_color.upper()
    correct_count = 0
    total_count = len(expected_cells)
    for cell_coord in expected_cells:
        actual_color = result.get(cell_coord, '').upper()
        if actual_color and (not actual_color.startswith('#')):
            actual_color = f'#{actual_color}'
        if actual_color == expected_color:
            correct_count += 1
    if total_count == 0:
        return 0.0
    return correct_count / total_count

def check_xlsx_sorted_ascending__3191e02b(result, expected, **options):
    """Check if values are sorted in ascending order.

    Args:
        result: List of values from getter
        expected: Order type ('ascending' or 'descending')
        **options: unused

    Returns:
        float: 1.0 if sorted correctly, 0.0 otherwise
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    non_null_values = [v for v in result if v is not None]
    if len(non_null_values) == 0:
        return 0.0
    if expected == 'ascending':
        is_sorted = all((non_null_values[i] <= non_null_values[i + 1] for i in range(len(non_null_values) - 1)))
    elif expected == 'descending':
        is_sorted = all((non_null_values[i] >= non_null_values[i + 1] for i in range(len(non_null_values) - 1)))
    else:
        return 0.0
    return 1.0 if is_sorted else 0.0

