def check_xlsx_sorted_desc__2a362783(result, expected, **options):
    """Check if column values are sorted in descending order.

    Args:
        result: List of values from getter
        expected: Dict with 'check_sorted' flag and optional 'top_values' to verify
        **options: Additional options like 'tolerance'

    Returns:
        float: Score based on correct sorting (0.0-1.0)
    """
    if not result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    top_values = expected.get('top_values', None)
    score = 0.0
    is_sorted = True
    for i in range(len(result) - 1):
        if result[i] is None or result[i + 1] is None:
            continue
        if result[i] < result[i + 1]:
            is_sorted = False
            break
    if is_sorted:
        score += 0.5
    if top_values:
        matches = 0
        check_count = min(len(top_values), len(result))
        for i in range(check_count):
            if result[i] is not None and isinstance(result[i], (int, float)):
                if abs(result[i] - top_values[i]) <= tolerance:
                    matches += 1
        if check_count > 0:
            score += 0.5 * (matches / check_count)
    elif is_sorted:
        score = 1.0
    return score

