def check_xlsx_cell_colors__e3a623b2(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if specified cells have the expected background color.

    Args:
        result: Dict mapping cell coordinates to their hex color values (from getter)
        expected: Dict with 'cells' (list of cell coords) and 'color' (expected hex color)
        **options: Additional options (tolerance for color matching, etc.)

    Returns:
        float: Score between 0.0 and 1.0 (proportion of cells with correct color)
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', [])
    expected_color = expected.get('color', '').upper()
    if not expected_cells or not expected_color:
        return 0.0
    if not expected_color.startswith('#'):
        expected_color = f'#{expected_color}'
    expected_color = expected_color.upper()
    correct_count = 0
    total_count = len(expected_cells)
    for cell_coord in expected_cells:
        actual_color = result.get(cell_coord, '').upper()
        if actual_color and (not actual_color.startswith('#')):
            actual_color = f'#{actual_color}'
        if actual_color == expected_color:
            correct_count += 1
    if total_count == 0:
        return 0.0
    return correct_count / total_count

def check_xlsx_net_income_column__592472ed3c184f2afab03dc4dd778347(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Net Income column exists with correct header and calculated values.

    Verifies that:
    1. Column C has the correct header "Net Income" (0.2 pts)
    2. Column C has values (0.1 pts)
    3. Correct number of rows (0.2 pts)
    4. Values are correctly calculated as Revenue - Total Expenses (0.5 pts)

    Args:
        result: Data from getter (dict with columns A, B, C data)
        expected: Expected configuration from rules
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    score = 0.0
    expected_header = expected.get('header', 'Net Income')
    if result.get('header_c') == expected_header:
        score += 0.2
    column_c = result.get('column_c', [])
    if len(column_c) > 0:
        score += 0.1
    expected_count = expected.get('count', 19)
    if result.get('count') == expected_count:
        score += 0.2
    column_a = result.get('column_a', [])
    column_b = result.get('column_b', [])
    if len(column_a) == len(column_b) == len(column_c) and len(column_c) > 0:
        correct_calculations = 0
        total_rows = 0
        for i in range(len(column_c)):
            val_a = column_a[i]
            val_b = column_b[i]
            val_c = column_c[i]
            if val_a is None or val_b is None or val_c is None:
                continue
            total_rows += 1
            try:
                revenue = float(val_a)
                expenses = float(val_b)
                net_income = float(val_c)
                expected_net_income = revenue - expenses
                if abs(net_income - expected_net_income) < 0.01:
                    correct_calculations += 1
            except (TypeError, ValueError):
                pass
        if total_rows > 0:
            calculation_ratio = correct_calculations / total_rows
            score += 0.5 * calculation_ratio
    return min(score, 1.0)

