def check_xlsx_multiple_cells__e8ab11ca(result_state, expected_state, **options):
    """
    Check if multiple cells in an xlsx file contain expected values.

    This function verifies multiple cells at once, supporting both text and numeric
    values with tolerance for numeric comparisons and fuzzy matching for text.

    Args:
        result_state: Path to the result xlsx file (str)
        expected_state: Dict containing:
            - sheet: Sheet index (int) or name (str)
            - cells: List of dicts, each with:
                - cell: Cell coordinate (str, e.g., 'B7')
                - value: Expected value (str, float, or int)
                - type: 'text' or 'numeric' (optional, auto-detected if not provided)
        **options: Additional options:
            - tolerance: Maximum allowed difference for numeric values (float, default 0.0)
            - case_sensitive: Whether text comparison is case-sensitive (bool, default False)

    Returns:
        float: 1.0 if all cells match, 0.0 if any cell doesn't match
    """
    if result_state is None:
        logger.error('Result file path is None')
        return 0.0
    try:
        logger.info(f'Loading result file: {result_state}')
        workbook = openpyxl.load_workbook(filename=result_state)
    except Exception as e:
        logger.error(f'Failed to load result file {result_state}: {e}')
        return 0.0
    sheet_idx = expected_state.get('sheet', 0)
    try:
        if isinstance(sheet_idx, int):
            sheet_names = workbook.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available: {sheet_names}')
                return 0.0
            sheet = workbook[sheet_names[sheet_idx]]
        else:
            sheet = workbook[sheet_idx]
        logger.info(f'Loaded sheet: {sheet.title}')
    except Exception as e:
        logger.error(f'Failed to load sheet {sheet_idx}: {e}')
        return 0.0
    cells = expected_state.get('cells', [])
    if not cells:
        logger.error('No cells specified')
        return 0.0
    tolerance = options.get('tolerance', 0.0)
    case_sensitive = options.get('case_sensitive', False)
    for cell_spec in cells:
        cell_coord = cell_spec.get('cell')
        expected_value = cell_spec.get('value')
        value_type = cell_spec.get('type', 'auto')
        if not cell_coord:
            logger.error('Cell coordinate missing in cell spec')
            return 0.0
        try:
            cell = sheet[cell_coord]
            cell_value = cell.value
            logger.info(f'Cell {cell_coord} value: {cell_value}')
        except Exception as e:
            logger.error(f'Failed to access cell {cell_coord}: {e}')
            return 0.0
        if cell_value is None:
            logger.error(f'Cell {cell_coord} is empty')
            return 0.0
        if value_type == 'auto':
            if isinstance(expected_value, (int, float)):
                value_type = 'numeric'
            else:
                value_type = 'text'
        if value_type == 'numeric':
            try:
                cell_value_float = float(cell_value)
                expected_value_float = float(expected_value)
                difference = abs(cell_value_float - expected_value_float)
                logger.info(f'Comparing numeric values in {cell_coord}: cell={cell_value_float}, expected={expected_value_float}, difference={difference}, tolerance={tolerance}')
                if difference > tolerance:
                    logger.warning(f'Cell {cell_coord} numeric value does not match: {difference} > {tolerance}')
                    return 0.0
            except (ValueError, TypeError) as e:
                logger.error(f'Failed to convert values to float for {cell_coord}: cell={cell_value}, expected={expected_value}, error={e}')
                return 0.0
        else:
            cell_value_str = str(cell_value).strip()
            expected_value_str = str(expected_value).strip()
            if not case_sensitive:
                cell_value_str = cell_value_str.lower()
                expected_value_str = expected_value_str.lower()
            logger.info(f"Comparing text values in {cell_coord}: cell='{cell_value_str}', expected='{expected_value_str}'")
            if cell_value_str != expected_value_str:
                logger.warning(f"Cell {cell_coord} text value does not match: '{cell_value_str}' != '{expected_value_str}'")
                return 0.0
    logger.info('All cells match their expected values')
    return 1.0

