def check_xlsx_multiplied_values__bc7b9125c363c28f5972c9a1e257f5d6(result, expected, **options):
    """Check if values match expected list (with tolerance for floats).

    Args:
        result: List of values from getter
        expected: Expected list of values (from rules dict)
        **options: Additional options (tolerance for numeric comparison)

    Returns:
        float: Proportion of values that match (0.0 to 1.0)
    """
    tolerance = options.get('tolerance', 0.01)
    if not result or not expected:
        return 0.0
    if len(result) != len(expected):
        return 0.0
    matches = 0
    for (r, e) in zip(result, expected):
        if r is None and e is None:
            matches += 1
        elif r is None or e is None:
            continue
        elif isinstance(r, (int, float)) and isinstance(e, (int, float)):
            if abs(r - e) <= tolerance:
                matches += 1
        elif str(r) == str(e):
            matches += 1
    return matches / len(expected) if len(expected) > 0 else 0.0

