def check_cell_has_sum_formula__b7373d5a(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if cell contains a SUM formula with the correct range.

    Args:
        result: Formula string from the cell
        expected: Dict with validation criteria (not used, just checks for SUM)
        **options: Additional options

    Returns:
        float: 1.0 if cell has SUM formula with correct range (rows 12-23), 0.0 otherwise
    """
    if not result:
        return 0.0
    formula_upper = result.upper()
    if 'SUM(' not in formula_upper and 'SUM (' not in formula_upper:
        return 0.0
    pattern = 'SUM\\s*\\(\\s*([A-Z]+)(\\d+)\\s*:\\s*([A-Z]+)(\\d+)\\s*\\)'
    match = re.search(pattern, formula_upper)
    if not match:
        return 0.0
    start_col = match.group(1)
    start_row = int(match.group(2))
    end_col = match.group(3)
    end_row = int(match.group(4))
    if start_row == 12 and end_row == 23 and (start_col == end_col):
        return 1.0
    return 0.0

