def check_xlsx_content__462df971(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Excel table content matches expected values.

    Args:
        result: Table data from getter (list of lists)
        expected: Expected configuration with validation rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not result:
        return 0.0
    expected_rows = expected.get('rows', [])
    if not expected_rows:
        return 0.0
    if len(result) < len(expected_rows) + 1:
        return 0.0
    score = 0.0
    header_score = 0.25
    data_score = 0.75
    header_row = result[0] if result else []
    expected_headers = ['Metric', '2019', '2023', 'Change']
    header_matches = True
    if len(header_row) >= len(expected_headers):
        for (idx, expected_header) in enumerate(expected_headers):
            actual_header = str(header_row[idx]).strip() if idx < len(header_row) and header_row[idx] is not None else ''
            if actual_header.lower() != expected_header.lower():
                header_matches = False
                break
    else:
        header_matches = False
    if header_matches:
        score += header_score
    data_rows = result[1:]
    if len(data_rows) != len(expected_rows):
        return score
    points_per_row = data_score / len(expected_rows) if expected_rows else 0.0
    for (idx, actual_row) in enumerate(data_rows):
        if idx >= len(expected_rows):
            break
        expected_row = expected_rows[idx]
        row_matches = True
        for (col_idx, expected_val) in enumerate(expected_row):
            if col_idx >= len(actual_row):
                row_matches = False
                break
            actual_val = actual_row[col_idx]
            if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                if abs(float(actual_val) - float(expected_val)) > 0.01:
                    row_matches = False
                    break
            elif actual_val != expected_val:
                row_matches = False
                break
        if row_matches:
            score += points_per_row
    return round(score, 2)

def check_xlsx_text_format__04e43e01(result_state, expected_state, **options):
    """
    Check if the cell text matches the expected formatted text pattern and has a valid formula
    that references and formats cell C1.
    The result_state is a dict with 'text' (displayed value) and 'formula' (formula string).
    When expected.type='rule', expected_state is the rules value directly (string), not a dict.

    Args:
        result_state: Dict with 'text' (displayed text) and 'formula' (formula string)
        expected_state: Expected text value (str) when type='rule'
        **options: Additional options

    Returns:
        float: 1.0 if (1) text matches expected, (2) formula contains formatting functions,
               (3) formula references C1, and (4) C1 is used within the formatting function.
               0.0 otherwise.
    """
    expected_text = str(expected_state).strip()
    actual_text = str(result_state.get('text', '')).strip()
    actual_formula = str(result_state.get('formula', '')).strip()
    if actual_text != expected_text:
        return 0.0
    if not actual_formula or not actual_formula.startswith('='):
        return 0.0
    formula_upper = actual_formula.upper()
    has_formatting = any(['TEXT(' in formula_upper, 'ROUND(' in formula_upper, 'INT(' in formula_upper, 'TRUNC(' in formula_upper])
    if not has_formatting:
        return 0.0
    if 'C1' not in formula_upper:
        return 0.0
    has_c1_in_formatting = any(['TEXT(C1' in formula_upper or 'TEXT( C1' in formula_upper, 'ROUND(C1' in formula_upper or 'ROUND( C1' in formula_upper, 'INT(C1' in formula_upper or 'INT( C1' in formula_upper, 'TRUNC(C1' in formula_upper or 'TRUNC( C1' in formula_upper])
    if has_c1_in_formatting:
        return 1.0
    return 0.0

def check_xlsx_sorted_by_column__447f5fcf01e57a045588cce9783df3a1(result, expected, **options):
    """Check if table data is sorted correctly by a specific row.

    Args:
        result: The actual table data (list of lists) from the getter
        expected: Dict with 'row_idx' (which row contains sort values) and 'descending' (bool)
        **options: Additional options

    Returns:
        float: 1.0 if correctly sorted, partial credit otherwise
    """
    if not result or not expected:
        return 0.0
    row_idx = expected.get('row_idx', 0)
    descending = expected.get('descending', False)
    if row_idx >= len(result):
        return 0.0
    sort_row = result[row_idx]
    if descending:
        is_sorted = all((sort_row[i] >= sort_row[i + 1] for i in range(len(sort_row) - 1) if sort_row[i] is not None and sort_row[i + 1] is not None))
    else:
        is_sorted = all((sort_row[i] <= sort_row[i + 1] for i in range(len(sort_row) - 1) if sort_row[i] is not None and sort_row[i + 1] is not None))
    if is_sorted:
        return 1.0
    else:
        return 0.0

