def check_calc_cell_format__a3c8817989e00a27454e516ffd39d47e(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the correct month with lowest 2020 cost has expected formatting.

    This metric verifies two things:
    1. The month with the lowest total cost in 2020 is correctly identified (50% score)
    2. That month's name cell in column A has the expected bold formatting (50% score)

    Args:
        result: Dict with 'formatting', 'data', 'month_column', 'cost_2020_column'
        expected: Expected configuration with 'cell' and formatting properties
        **options: Additional options

    Returns:
        Float score between 0.0 and 1.0
    """
    if not result or not isinstance(result, dict):
        return 0.0
    formatting = result.get('formatting', {})
    data = result.get('data', {})
    month_column = result.get('month_column', [])
    cost_2020_column = result.get('cost_2020_column', [])
    if not cost_2020_column:
        return 0.0
    min_cost = float('inf')
    min_row = None
    for (row_idx, cell_address, cost_value) in cost_2020_column:
        if cost_value < min_cost:
            min_cost = cost_value
            min_row = row_idx
    if min_row is None:
        return 0.0
    expected_cell = expected.get('cell', '')
    if not expected_cell:
        return 0.0
    try:
        expected_row = int(expected_cell[1:])
    except (ValueError, IndexError):
        return 0.0
    correct_identification = min_row == expected_row
    identification_score = 0.5 if correct_identification else 0.0
    formatting_score = 0.0
    if expected_cell in formatting:
        actual_format = formatting[expected_cell]
        property_score = 0.0
        checks = 0
        if 'bold' in expected:
            checks += 1
            if actual_format.get('bold') == expected['bold']:
                property_score += 1.0
        if 'italic' in expected:
            checks += 1
            if actual_format.get('italic') == expected['italic']:
                property_score += 1.0
        if 'underline' in expected:
            checks += 1
            if actual_format.get('underline') == expected['underline']:
                property_score += 1.0
        if checks > 0:
            formatting_score = 0.5 * (property_score / checks)
    total_score = identification_score + formatting_score
    return total_score

def check_xlsx_filtered_names__c1ce1471(result, expected, **options):
    """Check if column contains exactly the expected filtered names (no more, no less).

    Args:
        result: List of values from getter
        expected: Expected list of names
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    expected_names = expected.get('names', [])
    if not expected_names:
        return 0.0
    result_set = set(result) if result else set()
    expected_set = set(expected_names)
    if result_set == expected_set:
        return 1.0
    correct_names = result_set & expected_set
    missing_names = expected_set - result_set
    extra_names = result_set - expected_set
    total_expected = len(expected_set)
    correct_count = len(correct_names)
    if correct_count == 0:
        return 0.0
    missing_penalty = len(missing_names) / total_expected
    extra_penalty = len(extra_names) / total_expected
    score = correct_count / total_expected - extra_penalty
    return max(0.0, min(score, 1.0))

