def check_xlsx_highlighting__8a224e68(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if correct cells are highlighted with correct color AND no other cells are modified.

    Args:
        result: Result from getter (dict with 'expected_cells_highlighted' and 'other_cells_highlighted')
        expected: Expected cells and color from rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = set(expected.get('cells', []))
    expected_color = expected.get('color', '').lower().replace('#', '')
    expected_cells_highlighted = result.get('expected_cells_highlighted', [])
    other_cells_highlighted = result.get('other_cells_highlighted', [])
    if len(other_cells_highlighted) > 0:
        return 0.0
    correct_count = 0
    for item in expected_cells_highlighted:
        cell_addr = item['cell']
        cell_color = item.get('color', '').lower()
        if cell_addr in expected_cells:
            if cell_color == expected_color:
                correct_count += 1
    total_expected = len(expected_cells)
    if total_expected == 0:
        return 1.0
    score = correct_count / total_expected
    return min(1.0, max(0.0, score))

