def check_xlsx_sorted_desc__f7g3h4i5(result, expected, **options):
    """Check if ages are sorted in descending order.

    Args:
        result: List of ages in order
        expected: Expected sort configuration
        **options: Additional options

    Returns:
        float: Score based on how well sorted
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    is_sorted = all((result[i] >= result[i + 1] for i in range(len(result) - 1)))
    if is_sorted:
        return 1.0
    correct_pairs = sum((1 for i in range(len(result) - 1) if result[i] >= result[i + 1]))
    total_pairs = len(result) - 1
    return correct_pairs / total_pairs if total_pairs > 0 else 0.0

def check_xlsx_column_e_lengths__5a831fd058f448d1c7a430eaa6ea31d4(result, expected, **options):
    """Check if the task is completed correctly with multi-step verification.

    Verifies:
    1. Data was split into columns B, C, D (30% weight)
    2. Column E header is 'Name Length' (20% weight)
    3. Column E values contain correct name length calculations (50% weight)

    Args:
        result: Dict with:
            - 'column_e_header': Header value from E1
            - 'column_e_values': Dict with row numbers as keys and name lengths as values
            - 'data_split': Boolean indicating if data was split
            - 'sample_split_data': Sample data from columns B, C, D
        expected: Dict with:
            - 'name_lengths': Dict with row numbers as keys and expected name lengths
            - 'header': Expected header text for column E
            - 'require_split': Boolean indicating if data splitting is required

    Returns:
        float: Score between 0.0 and 1.0 based on weighted verification
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    require_split = expected.get('require_split', True)
    if require_split:
        if result.get('data_split', False):
            score += 0.3
    else:
        score += 0.3
    expected_header = expected.get('header', 'Name Length')
    actual_header = result.get('column_e_header', '')
    if actual_header and expected_header:
        if str(actual_header).strip().lower() == str(expected_header).strip().lower():
            score += 0.2
    expected_rows = expected.get('name_lengths', {})
    actual_values = result.get('column_e_values', {})
    if expected_rows:
        total = len(expected_rows)
        matches = 0
        for (row_num, expected_length) in expected_rows.items():
            row_key = int(row_num)
            if row_key in actual_values:
                actual_value = actual_values[row_key]
                if actual_value == expected_length or (isinstance(actual_value, (int, float)) and int(actual_value) == expected_length):
                    matches += 1
        if total > 0:
            score += 0.5 * (matches / total)
    return score

def check_calc_chart__d89ae1ac878087c6053fc4182b0f11d8(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the chart matches expected properties including data source.

    Args:
        result: Dict from getter with 'charts' list
        expected: Expected chart properties (from rules)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'charts' not in result:
        return 0.0
    charts = result.get('charts', [])
    if not charts:
        return 0.0
    expected_sheet_name = expected.get('sheet_name', '')
    expected_chart_type = expected.get('chart_type', '')
    expected_title = expected.get('chart_title', '')
    expected_data_column = expected.get('data_column', '')
    expected_min_rows = expected.get('min_data_rows', 0)
    score = 0.0
    for chart in charts:
        chart_score = 0.0
        if expected_sheet_name and chart.get('sheet_name', '') == expected_sheet_name:
            chart_score += 0.25
        elif not expected_sheet_name:
            chart_score += 0.25
        if expected_chart_type and chart.get('chart_type', '') == expected_chart_type:
            chart_score += 0.25
        elif not expected_chart_type:
            chart_score += 0.25
        if expected_title and chart.get('chart_title', '') == expected_title:
            chart_score += 0.25
        elif not expected_title:
            chart_score += 0.25
        data_source_valid = False
        if expected_data_column or expected_min_rows > 0:
            data_series = chart.get('data_series', [])
            if data_series:
                for series in data_series:
                    values_ref = series.get('values_ref', '')
                    data_range = series.get('data_range', '')
                    column_match = True
                    if expected_data_column:
                        series_title = series.get('title', '')
                        if expected_data_column.upper() not in values_ref.upper() and expected_data_column.upper() not in series_title.upper():
                            column_match = False
                    row_count_match = True
                    if expected_min_rows > 0 and data_range:
                        try:
                            if ':' in data_range:
                                (start, end) = data_range.split(':')
                                start_row = int(''.join(filter(str.isdigit, start)))
                                end_row = int(''.join(filter(str.isdigit, end)))
                                row_count = end_row - start_row + 1
                                if row_count < expected_min_rows:
                                    row_count_match = False
                        except (ValueError, IndexError):
                            row_count_match = False
                    if column_match and row_count_match:
                        data_source_valid = True
                        break
            if data_source_valid:
                chart_score += 0.25
        else:
            chart_score += 0.25
        score = max(score, chart_score)
    return score

