def check_xlsx_currency_format__2fddd674dc6f7b23072bc78c9305ad0e(result, expected, **options):
    """Check if column B cells have currency number formatting applied.

    Args:
        result: Dictionary mapping cell addresses to their number format strings
        expected: Dictionary with 'expected_values' key (used to know which cells to check)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('expected_values', {})
    if not expected_values:
        return 0.0
    total_cells = len(expected_values)
    correct_cells = 0
    for cell_addr in expected_values.keys():
        format_str = result.get(cell_addr)
        if format_str is None:
            continue
        format_lower = format_str.lower()
        has_dollar = '$' in format_str or '"$"' in format_str
        has_comma = '#,##0' in format_str or ',##0' in format_str
        has_decimals = '.00' in format_str
        is_not_general = format_str.strip().lower() != 'general'
        if has_dollar and has_comma and has_decimals and is_not_general:
            correct_cells += 1
    return correct_cells / total_cells if total_cells > 0 else 0.0

