def check_calc_max_formula_and_value__f39986703a8e9c70422f5ef8579fdbfe(result, expected, **options):
    """Check if cell contains both a valid MAX formula and correct result value.

    This metric validates that:
    1. Cell contains a formula starting with '='
    2. Formula uses the MAX function
    3. Formula references the expected range
    4. Cell value equals the expected numeric value (within tolerance)

    Args:
        result: Dict with 'formula' and 'value' from getter
        expected: Expected properties dict with 'range' and 'value'
        **options: Additional options including 'tolerance'

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    value = result.get('value')
    expected_range = expected.get('range', '').upper()
    expected_value = expected.get('value')
    if formula is None:
        return 0.0
    formula_str = str(formula).strip().upper()
    if not formula_str.startswith('='):
        return 0.0
    if 'MAX' not in formula_str:
        return 0.0
    if expected_range:
        formula_normalized = formula_str.replace('$', '')
        if expected_range not in formula_normalized:
            return 0.0
    if value is None:
        return 0.0
    try:
        result_value = float(value)
    except (ValueError, TypeError):
        return 0.0
    if expected_value is None:
        return 0.0
    try:
        expected_value = float(expected_value)
    except (ValueError, TypeError):
        return 0.0
    tolerance = options.get('tolerance', 0.0001)
    abs_tolerance = abs(expected_value * tolerance) if expected_value != 0 else 1e-05
    if abs(result_value - expected_value) > abs_tolerance:
        return 0.0
    return 1.0

