def check_xlsx_friday_highlights__06e470319b53c63588f6a30553809c36(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all Friday cells are highlighted with the expected color.

    Args:
        result: Dict mapping cell coordinates to their actual background colors
        expected: Dict with 'expected_color' (hex RGB string) and 'friday_cells' (list of cell coordinates)
        **options: Additional options including 'color_tolerance' for fuzzy matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_color = expected.get('expected_color', 'FFFFFF00')
    friday_cells = expected.get('friday_cells', [])
    color_tolerance = options.get('color_tolerance', 20)
    strict_color_match = options.get('strict_color_match', False)
    if not friday_cells:
        return 0.0

    def colors_match(color1: str, color2: str) -> bool:
        """Check if two RGB hex colors match (with optional tolerance)."""
        if not color1 or not color2:
            return False
        if len(color1) == 8:
            color1 = color1[2:]
        if len(color2) == 8:
            color2 = color2[2:]
        if strict_color_match:
            return color1.upper() == color2.upper()
        try:
            (r1, g1, b1) = (int(color1[0:2], 16), int(color1[2:4], 16), int(color1[4:6], 16))
            (r2, g2, b2) = (int(color2[0:2], 16), int(color2[2:4], 16), int(color2[4:6], 16))
            distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
            return distance <= color_tolerance
        except (ValueError, IndexError):
            return False
    correct_count = 0
    for cell_coord in friday_cells:
        actual_color = result.get(cell_coord)
        if actual_color and colors_match(actual_color, expected_color):
            correct_count += 1
    score = correct_count / len(friday_cells)
    return score

def check_xlsx_cell_contains__7bf98201(result_state: str, expected_state: dict, **options) -> float:
    """
    Check if a cell value contains a specific keyword.

    This function checks if the cell value contains the expected keyword,
    with optional case-insensitive comparison.

    Args:
        result_state: The cell value as a string from the getter
        expected_state: Dictionary containing rule parameters directly:
            - 'contains': The keyword to search for
            - 'case_sensitive': Boolean for case-sensitive matching (default: True)
        **options: Additional options

    Returns:
        float: 1.0 if the cell contains the keyword, 0.0 otherwise
    """
    if result_state is None:
        logger.error('Result state is None')
        return 0.0
    keyword = expected_state.get('contains', '')
    case_sensitive = expected_state.get('case_sensitive', True)
    if not keyword:
        logger.error('No keyword provided in expected_state')
        return 0.0
    result_str = str(result_state).strip()
    if not result_str:
        logger.info(f"Cell is empty, expected to contain '{keyword}'")
        return 0.0
    if case_sensitive:
        contains = keyword in result_str
    else:
        contains = keyword.lower() in result_str.lower()
    if contains:
        logger.info(f"Cell contains keyword '{keyword}': '{result_str}'")
        return 1.0
    else:
        logger.info(f"Cell does not contain keyword '{keyword}': '{result_str}'")
        return 0.0

