def check_xlsx_dept_employees__343b0a84fd44790d4ed7b7f9379c462a(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Verify that the result file contains only employees from the target department
    with complete evaluation information.

    Args:
        result: Dict from result getter containing employees, column info, and verification flags
        expected: Expected employee names (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_employees = expected.get('expected_employees', [])
    if not expected_employees:
        return 0.0
    result_employees = result.get('employees', [])
    result_set = set(result_employees)
    expected_set = set(expected_employees)
    if result_set == expected_set:
        employee_match_score = 0.5
    elif result_set & expected_set:
        employee_match_score = 0.5 * (len(result_set & expected_set) / len(expected_set))
    else:
        employee_match_score = 0.0
    has_eval_columns = result.get('has_evaluation_columns', False)
    eval_columns_score = 0.25 if has_eval_columns else 0.0
    dept_verified = result.get('department_verified', False)
    dept_score = 0.25 if dept_verified else 0.0
    total_score = employee_match_score + eval_columns_score + dept_score
    return total_score

def check_xlsx_sequential_nums__01c0333b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if column A has sequential numbers and last row has correct data.

    Args:
        result: Dict with 'sequence' (list of numbers) and 'last_row_data' (dict with name, university, department)
        expected: Dict with 'sequence' and 'last_row_data' keys
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_sequence = expected.get('sequence', [])
    expected_row_data = expected.get('last_row_data', {})
    result_sequence = result.get('sequence', [])
    result_row_data = result.get('last_row_data', {})
    if not expected_sequence:
        return 0.0
    sequence_score = 0.0
    if result_sequence == expected_sequence:
        sequence_score = 0.5
    else:
        matches = sum((1 for (r, e) in zip(result_sequence, expected_sequence) if r == e))
        sequence_score = 0.5 * (matches / len(expected_sequence)) if expected_sequence else 0.0
    row_data_score = 0.0
    if expected_row_data:
        fields_to_check = ['name', 'university', 'department']
        field_matches = 0
        for field in fields_to_check:
            expected_val = expected_row_data.get(field, '').strip() if expected_row_data.get(field) else ''
            result_val = result_row_data.get(field, '').strip() if result_row_data.get(field) else ''
            if expected_val.lower() == result_val.lower():
                field_matches += 1
        row_data_score = 0.5 * (field_matches / len(fields_to_check))
    return sequence_score + row_data_score

def check_cell_has_formula__e700b4a8(result: Optional[str], expected: dict, **options) -> float:
    """
    Check if a cell contains the correct formula for calculating Council Tax total.

    Args:
        result: The formula string from the getter (e.g., '=SUM(E20:E31)')
        expected: Expected configuration with:
            - has_formula (bool): Whether a formula should exist
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 1.0 if the cell contains a correct SUM formula with range E20:E31
            - 0.0 otherwise
    """
    try:
        if not result or not isinstance(result, str):
            return 0.0
        if not result.startswith('='):
            return 0.0
        formula_normalized = result.upper().replace(' ', '')
        if 'SUM' not in formula_normalized:
            return 0.0
        range_pattern = 'E\\$?20:\\$?E\\$?31|E\\$?20\\.\\.\\$?E\\$?31'
        if re.search(range_pattern, formula_normalized):
            return 1.0
        reverse_range_pattern = 'E\\$?31:\\$?E\\$?20|E\\$?31\\.\\.\\$?E\\$?20'
        if re.search(reverse_range_pattern, formula_normalized):
            return 1.0
        return 0.0
    except Exception as e:
        print(f'Error in check_cell_has_formula__e700b4a8: {e}')
        return 0.0

