def check_xlsx_invoice_data__39d2d2b1(result, expected, **options):
    """Verify invoice data was properly extracted from PDF.

    Args:
        result: Dictionary from getter with:
            - headers: List of column headers
            - services: List of service names found
            - domain_registration_row: Row number where Domain Registration was found (if any)
            - domain_registration_found: Boolean indicating if Domain Registration service exists
            - f6_value: Value from cell F6 (unit price location per instruction)
            - total_service_rows: Total number of service rows
            - all_row_data: All row data for detailed checks
        expected: Expected values dict with:
            - service_name: Expected service name (e.g., 'Domain Registration')
            - unit_price: Expected unit price value
        **options: Additional comparison options
            - tolerance: Allowed difference for numeric values (default: 0.01)

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass)
    """
    tolerance = options.get('tolerance', 0.01)
    if not isinstance(result, dict):
        return 0.0
    checks_passed = 0
    total_checks = 6
    headers = result.get('headers', [])
    has_valid_headers = False
    if headers:
        header_str = ' '.join([str(h).lower() for h in headers if h])
        if any((keyword in header_str for keyword in ['service', 'description', 'item', 'product'])):
            has_valid_headers = True
    if has_valid_headers:
        checks_passed += 1
    services = result.get('services', [])
    total_service_rows = result.get('total_service_rows', 0)
    if total_service_rows >= 8:
        checks_passed += 1
    domain_registration_found = result.get('domain_registration_found', False)
    expected_service = expected.get('service_name', 'Domain Registration')
    if domain_registration_found:
        checks_passed += 1
    f6_value = result.get('f6_value')
    expected_price = expected.get('unit_price')
    if f6_value is not None and expected_price is not None:
        try:
            result_val = float(f6_value)
            expected_val = float(expected_price)
            if abs(result_val - expected_val) <= tolerance:
                checks_passed += 1
        except (ValueError, TypeError):
            pass
    if len(services) >= 3:
        unique_services = set([s.lower().strip() for s in services if s])
        if len(unique_services) >= 3:
            checks_passed += 1
    all_row_data = result.get('all_row_data', [])
    expected_services_keywords = ['hosting', 'domain', 'email', 'ssl', 'certificate', 'support', 'maintenance', 'backup', 'storage', 'bandwidth']
    services_found_count = 0
    for service in services:
        service_lower = service.lower() if service else ''
        for keyword in expected_services_keywords:
            if keyword in service_lower:
                services_found_count += 1
                break
    if services_found_count >= 3:
        checks_passed += 1
    return 1.0 if checks_passed == total_checks else 0.0

