def check_xlsx_website_qty__57e581555e19ceb3db2669015c9e00b9(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Verify Excel file has summary sheet with correct totals and Total Quantity column.

    Args:
        result: Dictionary from getter containing:
                - has_summary_sheet: bool
                - summary_data: dict mapping website to quantity
                - has_total_column: bool
                - original_totals: dict mapping website to quantity
        expected: Expected rules containing target website quantities
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 and 1.0 with partial credit for:
               - 0.4: Summary sheet exists with correct data
               - 0.4: All website totals are correct
               - 0.2: Total Quantity column exists in original sheet
    """
    if not isinstance(result, dict):
        return 0.0
    expected_values = expected.get('website_quantities', {})
    if not expected_values:
        return 0.0
    total_score = 0.0
    if result.get('has_summary_sheet', False):
        summary_data = result.get('summary_data', {})
        if summary_data:
            correct_websites = 0
            for (website, expected_qty) in expected_values.items():
                if summary_data.get(website) == expected_qty:
                    correct_websites += 1
            if correct_websites == len(expected_values):
                total_score += 0.4
    totals_to_check = result.get('summary_data', {}) or result.get('original_totals', {})
    if totals_to_check:
        correct_totals = 0
        for (website, expected_qty) in expected_values.items():
            if totals_to_check.get(website) == expected_qty:
                correct_totals += 1
        total_score += correct_totals / len(expected_values) * 0.4
    if result.get('has_total_column', False):
        total_score += 0.2
    return total_score

def check_xlsx_billions_3decimal__f20dac8a(result, expected, **options):
    """Check if cells in column B contain Billions (B) format with 3 decimals.

    Args:
        result: File bytes from VM
        expected: Dict with 'rules' containing 'sheet' and 'values' dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        expected_values = expected.get('values', {})
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(result)
            tmp_path = tmp.name
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        correct = 0
        total = len(expected_values)
        for (cell_addr, expected_val) in expected_values.items():
            actual_val = ws[cell_addr].value
            actual_str = str(actual_val).strip() if actual_val is not None else ''
            expected_str = str(expected_val).strip()
            if actual_str == expected_str:
                correct += 1
        wb.close()
        import os
        os.unlink(tmp_path)
        return correct / total if total > 0 else 0.0
    except Exception as e:
        print(f'Error in check_xlsx_billions_3decimal__f20dac8a: {e}')
        return 0.0

