def check_xlsx_total_column__acf65d93239c96b69db0baa269f4ce8b(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if total column is correctly calculated in Excel file.

    Args:
        result: Dict from getter with header and totals
        expected: Expected values (from rules)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        logger.warning('Empty result from getter')
        return 0.0
    tolerance = options.get('tolerance', 1)
    score = 0.0
    header = result.get('header', '')
    expected_header = expected.get('header', 'Total')
    if header and str(header).strip().lower() == expected_header.lower():
        score += 0.2
    totals = result.get('totals', [])
    expected_totals = expected.get('totals', [])
    if len(totals) == len(expected_totals) and len(totals) > 0:
        points_per_value = 0.8 / len(totals)
        for (actual, expect) in zip(totals, expected_totals):
            if actual is not None and expect is not None:
                try:
                    if abs(float(actual) - float(expect)) <= tolerance:
                        score += points_per_value
                except (TypeError, ValueError):
                    pass
    return min(score, 1.0)

