def check_xlsx_employee_sorted__cebd11d3232d8a7deccc4d5c8ddffe07(result: List[Dict[str, Any]], expected: Dict, **options) -> float:
    """
    Check if employees are sorted by clock-in time in ascending order.
    Employees with missing/invalid clock-in times should appear at the end.

    Args:
        result: List of dicts with 'name' and 'clock_in_time' keys from the result file
        expected: Expected configuration with 'sorted_order' key
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    expected_order = expected.get('sorted_order', [])
    if not result or not expected_order:
        return 0.0
    result_names = [emp['name'] for emp in result]
    if result_names != expected_order:
        correct_positions = sum((1 for (i, name) in enumerate(result_names) if i < len(expected_order) and name == expected_order[i]))
        name_match_score = correct_positions / len(expected_order) if expected_order else 0.0
    else:
        name_match_score = 1.0
    with_time = [emp for emp in result if emp['clock_in_time'] is not None]
    without_time = [emp for emp in result if emp['clock_in_time'] is None]
    time_sorted_correctly = True
    for i in range(len(with_time) - 1):
        if with_time[i]['clock_in_time'] > with_time[i + 1]['clock_in_time']:
            time_sorted_correctly = False
            break
    if with_time and without_time:
        last_with_time_idx = len(result) - 1
        first_without_time_idx = 0
        for (i, emp) in enumerate(result):
            if emp['clock_in_time'] is not None:
                last_with_time_idx = i
        for (i, emp) in enumerate(result):
            if emp['clock_in_time'] is None:
                first_without_time_idx = i
                break
        if first_without_time_idx <= last_with_time_idx:
            time_sorted_correctly = False
    if name_match_score == 1.0 and time_sorted_correctly:
        return 1.0
    elif time_sorted_correctly:
        return max(0.5, name_match_score)
    else:
        return name_match_score * 0.5

