def check_xlsx_total_expenses__263f8630e4021954c5f4487c5b68019a(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Total Cost of Goods Sold values are correctly calculated.

    Verifies:
    1. Total values match expected values
    2. Total is correctly calculated as Materials + Labor + Overhead

    Args:
        result: Dict mapping string row indices to dicts with 'total', 'materials', 'labor', 'overhead'
        expected: Dict with 'values' key containing expected total values per row

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_values = expected.get('values', {})
    if not expected_values:
        return 0.0
    total_rows = len(expected_values)
    if total_rows == 0:
        return 0.0
    correct_count = 0
    for (row_idx, expected_value) in expected_values.items():
        row_data = result.get(row_idx)
        if row_data is None or not isinstance(row_data, dict):
            continue
        actual_total = row_data.get('total')
        materials = row_data.get('materials')
        labor = row_data.get('labor')
        overhead = row_data.get('overhead')
        if actual_total is None:
            continue
        if abs(actual_total - expected_value) >= 0.01:
            continue
        if materials is not None and labor is not None and (overhead is not None):
            calculated_total = materials + labor + overhead
            if abs(actual_total - calculated_total) >= 0.01:
                continue
        correct_count += 1
    return correct_count / total_rows

