def check_xlsx_sorted_desc__34d8bfad(result, expected, **options):
    """Check if column values are sorted in descending order.

    Args:
        result: List of values from getter
        expected: Expected configuration with sorting rules:
            - order: 'descending' or 'ascending'
            - sheet: Sheet index (optional, for reference)
            - column: Column index (optional, for reference)
            - start_row: Start row (optional, for reference)
            - end_row: End row (optional, for reference)
        **options: Additional options

    Returns:
        float: Score 1.0 if sorted correctly, 0.0 otherwise
    """
    if result is None or not isinstance(result, list):
        return 0.0
    order = expected.get('order', 'descending')
    result_values = [v for v in result if v is not None]
    if not result_values:
        return 0.0
    try:
        numeric_values = [float(v) for v in result_values]
        if order == 'descending':
            is_sorted = all((numeric_values[i] >= numeric_values[i + 1] for i in range(len(numeric_values) - 1)))
        else:
            is_sorted = all((numeric_values[i] <= numeric_values[i + 1] for i in range(len(numeric_values) - 1)))
        return 1.0 if is_sorted else 0.0
    except (TypeError, ValueError):
        if order == 'descending':
            is_sorted = all((result_values[i] >= result_values[i + 1] for i in range(len(result_values) - 1)))
        else:
            is_sorted = all((result_values[i] <= result_values[i + 1] for i in range(len(result_values) - 1)))
        return 1.0 if is_sorted else 0.0

