def check_xlsx_row_totals__369b58ec3a2f3e6fd7228fab6efb54d7(result, expected, **options):
    """Check if row totals match expected values and label is correct.

    Args:
        result: Dict mapping column letters to actual values (including 'A' for label)
        expected: Dict with 'expected_values' (dict mapping columns to expected values)
                  and optionally 'label' (expected label text)
        **options: Additional options (tolerance for numeric comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    expected_values = expected.get('expected_values', {})
    expected_label = expected.get('label', 'Total')
    if not expected_values:
        return 0.0
    tolerance = options.get('tolerance', 0.1)
    label_score = 0.0
    actual_label = result.get('A')
    if actual_label is not None:
        if isinstance(actual_label, str) and actual_label.strip().lower() == expected_label.lower():
            label_score = 0.15
    matches = 0
    total = len(expected_values)
    for (col, expected_val) in expected_values.items():
        actual_val = result.get(col)
        if actual_val is not None:
            if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                if abs(actual_val - expected_val) <= tolerance:
                    matches += 1
            elif actual_val == expected_val:
                matches += 1
    numeric_score = matches / total * 0.85 if total > 0 else 0.0
    return label_score + numeric_score

