def check_xlsx_sheet_sorted__7018e3cb(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if sheet data matches expected rules including headers, row count, and sorting.

    This function validates:
    1. Headers match expected headers (case-insensitive)
    2. Minimum row count is met
    3. Exact row count matches expected (if specified)
    4. Data is sorted by specified column in specified order

    Args:
        result: Dict from getter with 'headers', 'rows', 'row_count'
        expected: Dict containing rules directly (when type='rule', framework passes rules dict):
            - headers: List of expected header names
            - min_rows: Minimum number of rows required
            - exact_rows: Exact number of rows required (optional)
            - sort_column_idx: Column index to check for sorting
            - descending: True for descending order, False for ascending
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on partial credit
    """
    if not result:
        return 0.0
    actual_headers = result.get('headers', [])
    actual_rows = result.get('rows', [])
    actual_row_count = result.get('row_count', 0)
    expected_headers = [h.lower().strip() for h in expected.get('headers', [])]
    min_rows = expected.get('min_rows', 0)
    exact_rows = expected.get('exact_rows', None)
    sort_column_idx = expected.get('sort_column_idx')
    descending = expected.get('descending', False)
    score = 0.0
    max_score = 4
    headers_match = False
    if len(actual_headers) == len(expected_headers):
        if all((ah == eh for (ah, eh) in zip(actual_headers, expected_headers))):
            headers_match = True
            score += 1
    min_rows_ok = actual_row_count >= min_rows
    if min_rows_ok:
        score += 1
    exact_rows_ok = False
    if exact_rows is not None:
        if actual_row_count == exact_rows:
            exact_rows_ok = True
            score += 1
    else:
        score += 1
    sorted_correctly = False
    if sort_column_idx is not None and actual_rows:
        sorted_correctly = True
        for i in range(len(actual_rows) - 1):
            if len(actual_rows[i]) <= sort_column_idx or len(actual_rows[i + 1]) <= sort_column_idx:
                sorted_correctly = False
                break
            val1 = actual_rows[i][sort_column_idx]
            val2 = actual_rows[i + 1][sort_column_idx]
            try:
                val1 = float(val1) if val1 != '' else float('-inf')
                val2 = float(val2) if val2 != '' else float('-inf')
            except (ValueError, TypeError):
                val1 = str(val1)
                val2 = str(val2)
            if descending:
                if val1 < val2:
                    sorted_correctly = False
                    break
            elif val1 > val2:
                sorted_correctly = False
                break
        if sorted_correctly:
            score += 2
    return score / max_score

