def check_xlsx_split_sorted__15b128d4aa4fcee2f6589bb311116677(result, expected, **options):
    """Check if employee data is correctly split and sorted by last name, and column A is unchanged.

    Args:
        result: Dict with 'sorted_data' (list of tuples) and 'original_column_a' (list of strings)
        expected: Dict with 'sorted_data' (expected sorted list) and 'original_column_a' (expected original data)

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    result_sorted = result.get('sorted_data', [])
    expected_sorted = expected.get('sorted_data', [])
    result_column_a = result.get('original_column_a', [])
    expected_column_a = expected.get('original_column_a', [])
    if not isinstance(result_sorted, list) or not isinstance(expected_sorted, list):
        return 0.0
    if not isinstance(result_column_a, list) or not isinstance(expected_column_a, list):
        return 0.0
    sorted_score = 0.0
    if len(result_sorted) == len(expected_sorted) and len(expected_sorted) > 0:
        correct_count = 0
        for i in range(len(expected_sorted)):
            if i < len(result_sorted):
                result_entry = result_sorted[i]
                expected_entry = expected_sorted[i]
                if result_entry[0] == expected_entry[0] and result_entry[1] == expected_entry[1] and (result_entry[2] == expected_entry[2]):
                    correct_count += 1
        sorted_score = correct_count / len(expected_sorted)
    column_a_score = 0.0
    if len(result_column_a) == len(expected_column_a) and len(expected_column_a) > 0:
        correct_count = 0
        for i in range(len(expected_column_a)):
            if i < len(result_column_a):
                if result_column_a[i] == expected_column_a[i]:
                    correct_count += 1
        column_a_score = correct_count / len(expected_column_a)
    final_score = sorted_score * 0.5 + column_a_score * 0.5
    return final_score

