def check_xlsx_multi_highlights__3ca6b03a(result, expected, **options):
    """Check if multiple cells have expected background colors.

    Args:
        result: Dict mapping cell addresses to fill colors from getter
        expected: Dict with 'cells' list and 'color' expected
        **options: Options like 'color_tolerance' and 'strict_color_match'

    Returns:
        float: Score based on how many cells have correct highlighting (0.0-1.0)
    """
    if not result:
        return 0.0
    expected_cells = expected.get('cells', [])
    expected_color = expected.get('color', 'FFFF00')
    strict_match = options.get('strict_color_match', False)
    tolerance = options.get('color_tolerance', 20)
    if not expected_cells:
        return 0.0
    correct_count = 0
    for cell_addr in expected_cells:
        cell_color = result.get(cell_addr)
        if cell_color is None:
            continue
        cell_color_str = str(cell_color).upper().replace('#', '')
        expected_color_str = str(expected_color).upper().replace('#', '')
        if len(cell_color_str) == 8:
            cell_color_str = cell_color_str[2:]
        if len(expected_color_str) == 8:
            expected_color_str = expected_color_str[2:]
        if strict_match:
            if cell_color_str == expected_color_str:
                correct_count += 1
        else:
            try:
                (r1, g1, b1) = (int(cell_color_str[0:2], 16), int(cell_color_str[2:4], 16), int(cell_color_str[4:6], 16))
                (r2, g2, b2) = (int(expected_color_str[0:2], 16), int(expected_color_str[2:4], 16), int(expected_color_str[4:6], 16))
                distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
                if distance <= tolerance:
                    correct_count += 1
            except:
                pass
    return correct_count / len(expected_cells) if expected_cells else 0.0

def check_xlsx_marker_column__91de89e2(result, expected, **options):
    """Check if marker column correctly identifies target rows.

    Args:
        result: List of marker values from getter (should contain 'Yes', 'No', or similar)
        expected: Dict with 'target_rows' (list of row indices to be marked) and 'marker_value' (expected marker)
        **options: Additional options

    Returns:
        float: Proportion of correct markers (0.0 to 1.0)
    """
    if not isinstance(result, list):
        return 0.0
    target_rows = expected.get('target_rows', [])
    marker_value = expected.get('marker_value', 'Yes')
    correct = 0
    total = len(result)
    for (i, value) in enumerate(result):
        actual_row = i + 2
        should_be_marked = actual_row in target_rows
        value_str = str(value).strip().lower() if value else ''
        marker_str = str(marker_value).strip().lower()
        if should_be_marked:
            if value_str == marker_str:
                correct += 1
        elif value_str != marker_str:
            correct += 1
    return correct / total if total > 0 else 0.0

def check_xlsx_filtered__c794755b(result_state: Dict[str, Any], expected_state: Dict[str, Any], **options) -> float:
    """
    Check if the xlsx file has the correct AutoFilter applied.

    This metric verifies:
    - AutoFilter is applied
    - Filter is on the correct column
    - Filter condition is correct (greater than average)
    - Only rows matching the filter are visible

    Args:
        result_state: Result from getter containing filter information
        expected_state: Expected filter configuration with keys:
            - sheet (int): sheet index
            - filter_applied (bool): whether filter should be applied
            - filter_column (int): column index (0-based) to filter
            - filter_condition (str): filter type (e.g., 'greater_than')
            - filter_value (float): value to compare against
        **options: Additional options

    Returns:
        float: Score (1.0 if correct, 0.0 otherwise)
    """
    expected = expected_state
    expected_filter_applied = expected.get('filter_applied', True)
    actual_filter_applied = result_state.get('filter_applied', False)
    if expected_filter_applied != actual_filter_applied:
        print(f'Filter applied mismatch: expected={expected_filter_applied}, actual={actual_filter_applied}')
        return 0.0
    if not expected_filter_applied:
        return 1.0
    filter_info = result_state.get('filter_info', {})
    filter_columns = filter_info.get('filter_columns', [])
    if not filter_columns:
        print('No filter columns found')
        return 0.0
    expected_column = expected.get('filter_column')
    filter_condition = expected.get('filter_condition')
    filter_value = expected.get('filter_value')
    column_found = False
    condition_correct = False
    for flt_col in filter_columns:
        if flt_col['col_id'] == expected_column:
            column_found = True
            if 'custom_filters' in flt_col:
                for custom_filter in flt_col['custom_filters']:
                    operator = custom_filter['operator']
                    value = custom_filter['value']
                    if filter_condition == 'greater_than' and operator == 'greaterThan':
                        try:
                            if abs(float(value) - float(filter_value)) < 0.01:
                                condition_correct = True
                                break
                        except (ValueError, TypeError):
                            pass
                    elif filter_condition == 'less_than' and operator == 'lessThan':
                        try:
                            if abs(float(value) - float(filter_value)) < 0.01:
                                condition_correct = True
                                break
                        except (ValueError, TypeError):
                            pass
                    elif filter_condition == 'equals' and operator == 'equal':
                        try:
                            if abs(float(value) - float(filter_value)) < 0.01:
                                condition_correct = True
                                break
                        except (ValueError, TypeError):
                            pass
            if not condition_correct and 'filters' in flt_col:
                pass
            break
    if not column_found:
        print(f'Filter not found on expected column {expected_column}')
        return 0.0
    if not condition_correct:
        print(f'Filter condition not correct. Expected: {filter_condition} {filter_value}')
        return 0.0
    visible_rows = result_state.get('visible_rows', [])
    if not visible_rows:
        print('No visible rows found')
        return 0.0
    data_rows = [row for row in visible_rows if isinstance(row, dict) and row.get('row_num', 0) > 1]
    if not data_rows:
        print('No data rows found in visible rows')
        return 0.0
    for row in data_rows:
        revenue = row.get('revenue')
        if revenue is None:
            continue
        if filter_condition == 'greater_than':
            if revenue <= filter_value:
                print(f"Row {row['row_num']} has revenue {revenue} which is not > {filter_value}")
                return 0.0
        elif filter_condition == 'less_than':
            if revenue >= filter_value:
                print(f"Row {row['row_num']} has revenue {revenue} which is not < {filter_value}")
                return 0.0
        elif filter_condition == 'equals':
            if abs(revenue - filter_value) > 0.01:
                print(f"Row {row['row_num']} has revenue {revenue} which is not equal to {filter_value}")
                return 0.0
    return 1.0

def check_xlsx_cell_value__e36db52f(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if a cell in Excel file contains the expected value.
    
    Args:
        result: Path to Excel file (from getter)
        expected: Rules dict with 'sheet', 'cell', and 'value' keys
        **options: Additional options
        
    Returns:
        1.0 if cell value matches expected, 0.0 otherwise
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        cell_address = expected.get('cell', 'A1')
        expected_value = expected.get('value')
        tolerance = expected.get('tolerance', 0.0)
        wb = openpyxl.load_workbook(result, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_value = ws[cell_address].value
        if expected_value is None:
            return 1.0 if cell_value is None else 0.0
        if isinstance(expected_value, (int, float)) and isinstance(cell_value, (int, float)):
            if abs(cell_value - expected_value) <= tolerance:
                return 1.0
            return 0.0
        if isinstance(expected_value, str) and isinstance(cell_value, str):
            if expected_value.lower() == cell_value.lower():
                return 1.0
            return 0.0
        if cell_value == expected_value:
            return 1.0
        return 0.0
    except Exception as e:
        print(f'Error in check_xlsx_cell_value__e36db52f: {e}')
        return 0.0
    finally:
        import os
        if os.path.exists(result):
            try:
                os.unlink(result)
            except:
                pass

