def check_xlsx_column_sequence__208e870a(result, expected, **options):
    """Check if column contains expected sequential values.

    Args:
        result: List of actual cell values from getter
        expected: Dict with 'pattern' and 'count'
        **options: Additional options

    Returns:
        float: Score based on how many values match the expected pattern
    """
    if not result or not isinstance(result, list):
        return 0.0
    pattern = expected.get('pattern', 'number')
    count = expected.get('count', len(result))
    start = expected.get('start', 1)
    correct = 0
    total = min(count, len(result))
    if pattern == 'number':
        for i in range(total):
            expected_value = start + i
            actual = result[i]
            if actual == expected_value or (isinstance(actual, (int, float)) and int(actual) == expected_value):
                correct += 1
    elif pattern == 'custom':
        expected_values = expected.get('values', [])
        for i in range(min(total, len(expected_values))):
            if result[i] == expected_values[i] or str(result[i]) == str(expected_values[i]):
                correct += 1
    return correct / total if total > 0 else 0.0

