def check_xlsx_sorted_bold_top3__8ad95d8f699bceacb56d23803960d9c1(result, expected, **options):
    """Check if data is sorted by period rate descending and top 3 are bold.

    Args:
        result: dict from getter with sorting and bold info
        expected: dict with expected top 3 values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    column_exists = result.get('column_exists', False)
    if not column_exists:
        return 0.0
    period_rates = result.get('period_rates', [])
    if not period_rates:
        return 0.0
    score += 0.1
    calculation_verified = result.get('calculation_verified', False)
    if calculation_verified:
        score += 0.1
    is_sorted_desc = result.get('is_sorted_desc', False)
    if is_sorted_desc:
        score += 0.4
    top3_values = result.get('top3_values', [])
    expected_top3 = expected.get('top3_values', [])
    if len(top3_values) >= 3 and len(expected_top3) >= 3:
        tolerance = options.get('tolerance', 0.01)
        matches = 0
        for i in range(3):
            if abs(top3_values[i] - expected_top3[i]) <= tolerance:
                matches += 1
        if matches == 3:
            score += 0.2
    bold_rows = set(result.get('bold_rows', []))
    expected_bold = {2, 3, 4}
    if bold_rows == expected_bold:
        score += 0.2
    elif bold_rows & expected_bold:
        score += 0.1 * len(bold_rows & expected_bold) / 3
    return score

