def check_xlsx_row_highlighting__ec6099e4393d3df1a03fe5d9019f1dca(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the row with maximum sales value has fill/highlighting applied.

    This verifies TWO conditions:
    1. The target row has the maximum sales value among all rows
    2. The target row has fill applied

    This prevents false positives where an incorrect row is highlighted.

    Args:
        result: Dict from getter with:
            - has_fill: bool - whether target row has fill
            - fill_colors: list - fill colors of target row cells
            - all_rows_data: list[dict] - all rows with sales values and fill status
            - target_row_sales: float/None - sales value of target row
            - max_sales_value: float/None - maximum sales value in all rows
            - max_sales_row: int/None - row number with maximum sales
        expected: Expected rules dict with keys:
            - has_fill: Expected boolean for whether fill should be present

    Returns:
        1.0 if the highlighted row is the one with maximum sales, 0.0 otherwise
    """
    if not isinstance(result, dict):
        return 0.0
    expected_has_fill = expected.get('has_fill', True)
    actual_has_fill = result.get('has_fill', False)
    if actual_has_fill != expected_has_fill:
        return 0.0
    target_row_sales = result.get('target_row_sales')
    max_sales_value = result.get('max_sales_value')
    if target_row_sales is None or max_sales_value is None:
        return 1.0 if actual_has_fill == expected_has_fill else 0.0
    epsilon = 1e-06
    if abs(target_row_sales - max_sales_value) > epsilon:
        return 0.0
    all_rows_data = result.get('all_rows_data', [])
    max_sales_row = result.get('max_sales_row')
    if all_rows_data and max_sales_row is not None:
        for row_data in all_rows_data:
            row_num = row_data.get('row_num')
            row_has_fill = row_data.get('has_fill', False)
            if row_num != max_sales_row and row_has_fill:
                return 0.0
    return 1.0

