def check_xlsx_scientific_notation__709d09b3(result, expected, **options):
    """Check if cells in column B contain values in scientific notation format.

    Args:
        result: File bytes from VM
        expected: Dict with 'rules' containing 'sheet' and 'values' dict
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        expected_values = expected.get('values', {})
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(result)
            tmp_path = tmp.name
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        correct = 0
        total = len(expected_values)
        for (cell_addr, expected_val) in expected_values.items():
            actual_val = ws[cell_addr].value
            actual_str = str(actual_val).strip().upper() if actual_val is not None else ''
            expected_str = str(expected_val).strip().upper()
            if actual_str == expected_str:
                correct += 1
        wb.close()
        import os
        os.unlink(tmp_path)
        return correct / total if total > 0 else 0.0
    except Exception as e:
        print(f'Error in check_xlsx_scientific_notation__709d09b3: {e}')
        return 0.0

