def check_xlsx_average_period_rate__17a345572fdc0c283d28b83f4ab7ec06(result, expected, **options):
    """Check if period rate column, calculations, and average were added correctly.

    Args:
        result: dict from getter with 'column_header', 'sample_calculations', 'average_row', 'average_value'
        expected: dict with expected 'average_value'
        **options: Additional options (e.g., 'tolerance')

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    tolerance = options.get('tolerance', 0.01)
    column_header = result.get('column_header')
    if column_header and isinstance(column_header, str):
        if 'period' in column_header.lower() and 'rate' in column_header.lower():
            score += 0.2
    sample_calculations = result.get('sample_calculations', [])
    if sample_calculations:
        correct_samples = 0
        total_samples = len(sample_calculations)
        for calc in sample_calculations:
            annual_rate = calc.get('annual_rate')
            period_per_year = calc.get('period_per_year')
            actual_period_rate = calc.get('actual_period_rate')
            if annual_rate is not None and period_per_year is not None and (actual_period_rate is not None) and (period_per_year != 0):
                expected_period_rate = annual_rate / period_per_year
                difference = abs(actual_period_rate - expected_period_rate)
                if difference <= tolerance:
                    correct_samples += 1
        if total_samples > 0:
            sample_score = correct_samples / total_samples * 0.3
            score += sample_score
    result_row = result.get('average_row')
    if result_row is not None:
        score += 0.1
    result_value = result.get('average_value')
    expected_value = expected.get('average_value')
    if result_value is not None and expected_value is not None:
        difference = abs(result_value - expected_value)
        if difference <= tolerance:
            score += 0.4
        elif difference <= tolerance * 10:
            score += 0.2
    return score

