def check_calc_pivot_table__890caeb409c8e3865dd3686b03596d01(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if both Net Price column and Pivot Table were created correctly.

    Args:
        result: Data from getter containing both net_price_column and pivot_table info
        expected: Expected validation rules
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass) with partial credit
        - 0.5 for Net Price column (0.2 exists, 0.3 correct calculation)
        - 0.5 for Pivot Table (0.2 Sheet2 exists, 0.15 has data, 0.15 correct quantities)
    """
    score = 0.0
    net_price_info = result.get('net_price_column', {})
    if net_price_info.get('has_net_price'):
        score += 0.2
        net_values = net_price_info.get('net_price_values', [])
        retail_values = net_price_info.get('retail_values', [])
        discount_values = net_price_info.get('discount_values', [])
        if net_values and retail_values and discount_values:
            correct_count = 0
            total_count = 0
            for i in range(min(len(net_values), len(retail_values), len(discount_values))):
                net_price = net_values[i]
                retail_price = retail_values[i]
                discount = discount_values[i]
                if net_price is not None and retail_price is not None and (discount is not None):
                    try:
                        expected_net = retail_price * (1 - discount)
                        if abs(net_price - expected_net) < 0.01:
                            correct_count += 1
                        total_count += 1
                    except (TypeError, ValueError):
                        total_count += 1
            if total_count > 0:
                calculation_score = correct_count / total_count
                score += 0.3 * calculation_score
    pivot_info = result.get('pivot_table', {})
    if result.get('has_sheet2'):
        score += 0.2
        pivot_data = pivot_info.get('data', [])
        if pivot_data and len(pivot_data) > 1:
            score += 0.15
            product_quantities = pivot_info.get('product_quantities', {})
            expected_products = expected.get('expected_products', [])
            expected_quantities = {'Quad': 160, 'Aspen': 142, 'Fun Fly': 118, 'Fire Aspen': 96, 'Sunset': 68}
            if expected_products and product_quantities:
                correct_count = 0
                total_count = len(expected_products)
                for product in expected_products:
                    if product in product_quantities:
                        actual_qty = product_quantities[product]
                        expected_qty = expected_quantities.get(product)
                        if expected_qty:
                            if abs(actual_qty - expected_qty) <= 1:
                                correct_count += 1
                        else:
                            correct_count += 0.5
                if total_count > 0:
                    quantity_score = correct_count / total_count
                    score += 0.15 * quantity_score
    return score

