def check_xlsx_papers_complete__4da6f9d04fdaf419bddbc69359d26021(result: List[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if papers list contains complete entries with titles, URLs, and dates.

    Args:
        result: List of dictionaries containing paper data (title, url, date)
        expected: Expected rules dict with 'domain', 'min_count', and optional 'date_pattern' keys
        **options: Additional options

    Returns:
        float: Score based on number of complete valid entries vs minimum required
    """
    domain = expected.get('domain', 'arxiv.org')
    min_count = expected.get('min_count', 3)
    valid_count = 0
    for row in result:
        title = row.get('title')
        url = row.get('url')
        date = row.get('date')
        if not (title and url and date):
            continue
        title_str = str(title).strip()
        url_str = str(url).strip()
        date_str = str(date).strip()
        if not (title_str and url_str and date_str):
            continue
        if domain.lower() not in url_str.lower():
            continue
        valid_count += 1
    if valid_count >= min_count:
        return 1.0
    else:
        return valid_count / max(1, min_count)

