def check_xlsx_passing_count__b0f00f1e2c558a1b1f25c3a0de335edc(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if the total grades match expected values, passing count is correct,
    and individual question scores were filled in and sum to totals.
    This verifies that actual grading was performed correctly.

    Args:
        result: Dict with 'total_grades' (list), 'passing_count' (int),
                and 'individual_scores' (list of lists) from getter
        expected: Expected rules dict with 'passing_count' and 'total_grades' keys
        **options: Additional options

    Returns:
        1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_count = expected.get('passing_count')
    expected_grades = expected.get('total_grades')
    if expected_count is None:
        return 0.0
    actual_count = result.get('passing_count')
    if actual_count != expected_count:
        return 0.0
    if expected_grades is not None:
        actual_grades = result.get('total_grades', [])
        if sorted(actual_grades) != sorted(expected_grades):
            return 0.0
    individual_scores = result.get('individual_scores', [])
    if not individual_scores:
        return 0.0
    actual_grades = result.get('total_grades', [])
    for (i, (student_scores, total_grade)) in enumerate(zip(individual_scores, actual_grades)):
        if all((score is None for score in student_scores)):
            if total_grade is not None:
                return 0.0
            continue
        valid_scores = [s for s in student_scores if s is not None]
        if valid_scores:
            sum_of_individual = sum(valid_scores)
            if total_grade is not None:
                if abs(sum_of_individual - total_grade) > 0.01:
                    return 0.0
    return 1.0

def check_xlsx_bold_rows__7b6f14b7(result, expected, **options):
    """Check if specific rows are bolded correctly.

    Args:
        result: Dict of row numbers and bold status from getter
        expected: Expected bold rows (from rules)
        **options: Additional options

    Returns:
        float: Partial score based on correct bold formatting
    """
    if result is None:
        return 0.0
    expected_bold = expected.get('bold_rows', [])
    expected_not_bold = expected.get('not_bold_rows', [])
    score = 0.0
    total_checks = len(expected_bold) + len(expected_not_bold)
    if total_checks == 0:
        return 0.0
    for row in expected_bold:
        if result.get(row, False):
            score += 1.0 / total_checks
    for row in expected_not_bold:
        if not result.get(row, False):
            score += 1.0 / total_checks
    return score

