def check_xlsx_percentage_format__71d7a7e674f4d2619d09b1f1e82d6b2b(result, expected, **options):
    """Check if period rate column has percentage format with 2 decimal places.

    Args:
        result: dict from getter with formatting info
        expected: dict with expected format requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    has_column_header = result.get('has_column_header', False)
    if not has_column_header:
        return 0.0
    period_rate_data = result.get('period_rate_data', [])
    if not period_rate_data:
        return 0.0
    expected_format_type = expected.get('format_type', 'percentage')
    expected_decimal_places = expected.get('decimal_places', 2)
    score = 0.0
    total_checked = result.get('total_checked', 0)
    if total_checked == 0:
        return 0.0
    calculation_correct_count = result.get('calculation_correct_count', 0)
    calculation_ratio = calculation_correct_count / total_checked
    if calculation_ratio >= 0.9:
        score += 0.3
    elif calculation_ratio >= 0.5:
        score += 0.3 * calculation_ratio
    percentage_count = result.get('percentage_format_count', 0)
    if expected_format_type == 'percentage' and percentage_count > 0:
        percentage_ratio = percentage_count / total_checked
        if percentage_ratio >= 0.9:
            score += 0.4
        elif percentage_ratio >= 0.5:
            score += 0.4 * percentage_ratio
    decimal_2_count = result.get('decimal_2_count', 0)
    if decimal_2_count > 0:
        decimal_ratio = decimal_2_count / total_checked
        if expected_decimal_places == 2:
            if decimal_ratio >= 0.9:
                score += 0.3
            elif decimal_ratio >= 0.5:
                score += 0.3 * decimal_ratio
    return score

def check_xlsx_chart_sheet__79d88bef(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if the Totals sheet exists with correct revenue and expenses.

    Args:
        result: Data from getter with keys:
            - sheet_exists: bool
            - sheet_name: str or None
            - revenue_total: float or None
            - expenses_total: float or None
            - has_revenue_total: bool
            - has_expenses_total: bool
            - has_headers: bool
            - header_a1: str or None
            - header_b1: str or None
        expected: Expected values with keys from config["rules"]:
            - sheet_name: str (expected sheet name)
            - has_revenue_total: bool
            - has_expenses_total: bool
            - revenue_total: float (expected revenue sum)
            - expenses_total: float (expected expenses sum)
            - has_headers: bool
            - header_a1: str (expected header text in A1)
            - header_b1: str (expected header text in B1)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if not isinstance(result, dict):
        logger.error('Result is not a dict')
        return 0.0
    if not result.get('sheet_exists', False):
        logger.error('Totals sheet does not exist')
        return 0.0
    expected_sheet_name = expected.get('sheet_name')
    if expected_sheet_name and result.get('sheet_name') != expected_sheet_name:
        logger.error(f"Sheet name mismatch: expected {expected_sheet_name}, got {result.get('sheet_name')}")
        return 0.0
    if expected.get('has_revenue_total', False):
        if not result.get('has_revenue_total', False):
            logger.error('Revenue total not found in expected location')
            return 0.0
    if expected.get('has_expenses_total', False):
        if not result.get('has_expenses_total', False):
            logger.error('Expenses total not found in expected location')
            return 0.0
    expected_revenue = expected.get('revenue_total')
    if expected_revenue is not None:
        result_revenue = result.get('revenue_total')
        if result_revenue is None:
            logger.error('Revenue total value is None')
            return 0.0
        tolerance = 0.01
        if abs(result_revenue - expected_revenue) > tolerance:
            logger.error(f'Revenue total mismatch: expected {expected_revenue}, got {result_revenue}')
            return 0.0
    expected_expenses = expected.get('expenses_total')
    if expected_expenses is not None:
        result_expenses = result.get('expenses_total')
        if result_expenses is None:
            logger.error('Expenses total value is None')
            return 0.0
        tolerance = 0.01
        if abs(result_expenses - expected_expenses) > tolerance:
            logger.error(f'Expenses total mismatch: expected {expected_expenses}, got {result_expenses}')
            return 0.0
    if expected.get('has_headers', False):
        if not result.get('has_headers', False):
            logger.error('Headers not found in row 1')
            return 0.0
    expected_header_a1 = expected.get('header_a1')
    if expected_header_a1 is not None:
        result_header_a1 = result.get('header_a1')
        if result_header_a1 is None:
            logger.error('Header A1 is None')
            return 0.0
        if result_header_a1 != expected_header_a1:
            logger.error(f"Header A1 mismatch: expected '{expected_header_a1}', got '{result_header_a1}'")
            return 0.0
    expected_header_b1 = expected.get('header_b1')
    if expected_header_b1 is not None:
        result_header_b1 = result.get('header_b1')
        if result_header_b1 is None:
            logger.error('Header B1 is None')
            return 0.0
        if result_header_b1 != expected_header_b1:
            logger.error(f"Header B1 mismatch: expected '{expected_header_b1}', got '{result_header_b1}'")
            return 0.0
    logger.info('All checks passed for Totals sheet')
    return 1.0

def check_xlsx_bookkeeping_data__fa635253(result, expected, **options):
    """Check if bookkeeping data meets quality requirements.

    Validates:
    1. Correct number of rows were added (11 total rows expected)
    2. Each row has a non-empty description in column B
    3. Each row has a valid numeric amount in column C
    4. Each row meets quality standards (not low-effort placeholder entries)

    This validator uses heuristic quality checks to ensure entries are reasonable
    and represent genuine effort to extract receipt data. Since exact semantic
    matching against receipt content is not feasible (receipt images/PDFs cannot
    be reliably parsed in test environment), quality checks ensure:
    - Descriptions have reasonable length (2+ chars) and contain letters
    - Descriptions are not repetitive placeholders (e.g., "aaa", "111")
    - Amounts are positive and in reasonable range (0.1 to 1,000,000)

    Args:
        result: Dict with 'row_count' and 'rows' from getter
        expected: Dict with 'row_count' and 'min_valid_rows'
        **options: Additional options (e.g., 'min_quality_score')

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    actual_count = result.get('row_count', 0)
    expected_count = expected.get('row_count', 0)
    min_valid_rows = expected.get('min_valid_rows', expected_count)
    min_quality_score = options.get('min_quality_score', 0.6)
    rows = result.get('rows', [])
    if actual_count != expected_count:
        return 0.0
    valid_rows = sum((1 for row in rows if row.get('is_valid', False)))
    if valid_rows < min_valid_rows:
        return valid_rows / min_valid_rows * 0.5
    high_quality_rows = sum((1 for row in rows if row.get('is_valid', False) and row.get('quality_score', 0) >= min_quality_score))
    if high_quality_rows < min_valid_rows:
        quality_ratio = high_quality_rows / min_valid_rows
        return 0.5 + quality_ratio * 0.5
    return 1.0

