def check_xlsx_arxiv_content__a8c92c109f6527d3fddb6472a1422a04(result: Dict[str, Any], expected: Dict, **options) -> float:
    """Check if Excel contains valid arXiv papers from Oct 11, 2023 with structural validation.

    Args:
        result: Dict with row_count, arxiv_count, dates_oct_11_count, valid_arxiv_url_count, valid_title_count, rows
        expected: Expected rules dict with 'min_rows', 'min_arxiv', 'min_dates' keys
        **options: Additional options

    Returns:
        float: Score from 0.0 to 1.0 based on validation
    """
    min_rows = expected.get('min_rows', 3)
    min_arxiv = expected.get('min_arxiv', 3)
    min_dates = expected.get('min_dates', 3)
    row_count = result.get('row_count', 0)
    arxiv_count = result.get('arxiv_count', 0)
    dates_count = result.get('dates_oct_11_count', 0)
    valid_arxiv_url_count = result.get('valid_arxiv_url_count', 0)
    valid_title_count = result.get('valid_title_count', 0)
    has_enough_rows = row_count >= min_rows
    has_enough_arxiv = arxiv_count >= min_arxiv
    has_enough_dates = dates_count >= min_dates
    has_valid_structure = valid_arxiv_url_count >= min_arxiv
    if has_enough_rows and has_enough_arxiv and has_enough_dates:
        if has_valid_structure:
            return 1.0
        else:
            return 0.95
    score = 0.0
    if has_enough_rows:
        score += 0.25
    else:
        score += 0.25 * (row_count / min_rows) if row_count > 0 else 0.0
    if has_valid_structure:
        score += 0.35
    elif has_enough_arxiv:
        score += 0.3
    else:
        score += 0.3 * (arxiv_count / min_arxiv) if arxiv_count > 0 else 0.0
    if has_enough_dates:
        score += 0.35
    else:
        score += 0.35 * (dates_count / min_dates) if dates_count > 0 else 0.0
    if row_count > 0 and valid_title_count >= row_count:
        score += 0.05
    return min(score, 1.0)

