    sheet_name = expected.get('sheet_name')
    column_index = expected.get('column_index')
    header_value = expected.get('header_value')
    data_value = expected.get('data_value')
    expected_count = expected.get('expected_count')
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        if sheet_name not in wb.sheetnames:
            return 0.0
        ws = wb[sheet_name]
        score = 0.0
        header_cell = ws.cell(row=1, column=column_index + 1)
        if header_cell.value == header_value:
            score += 0.25
        matching_count = 0
        for row_idx in range(2, 2 + expected_count):
            cell = ws.cell(row=row_idx, column=column_index + 1)
            if cell.value == data_value:
                matching_count += 1
        if matching_count == expected_count:
            score += 0.75
        return min(score, 1.0)
    except Exception as e:
        return 0.0

