def check_cell_value_match__299c599d(result, expected, **options):
    """Compare a cell value against an expected value.

    Args:
        result: The actual cell value from the getter
        expected: The expected cell value (can be a dict with 'value' key when type='rule')
        **options: Additional comparison options (e.g., 'tolerance' for numeric values)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    tolerance = options.get('tolerance', 0.01)
    if isinstance(expected, dict) and 'value' in expected:
        expected_value = expected['value']
    else:
        expected_value = expected
    if result is None and expected_value is None:
        return 1.0
    if result is None or expected_value is None:
        return 0.0
    if isinstance(result, (int, float)) and isinstance(expected_value, (int, float)):
        if abs(result - expected_value) <= tolerance:
            return 1.0
        else:
            return 0.0
    if isinstance(result, str) and isinstance(expected_value, str):
        if result.strip() == expected_value.strip():
            return 1.0
        else:
            return 0.0
    if result == expected_value:
        return 1.0
    else:
        return 0.0

def check_xlsx_cell_formula_and_value__40d813738ceb6076ea6bc5f1682bc5fb(result, expected, **options):
    """Verify that a cell contains both the correct formula and calculated value.

    This metric ensures that:
    1. The cell contains a formula (not just a hardcoded value)
    2. The formula is of the expected type (e.g., AVERAGE)
    3. The formula references the correct range
    4. The calculated value matches the expected result

    Args:
        result: Dict with 'formula' and 'value' keys from getter function
        expected: Dict with 'formula_pattern' (regex), 'expected_value', and optional 'formula_type'
        **options: Additional comparison options (tolerance for numeric comparison)

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None or not isinstance(result, dict):
        return 0.0
    formula = result.get('formula')
    value = result.get('value')
    if formula is None or not isinstance(formula, str) or (not formula.startswith('=')):
        return 0.0
    formula_upper = formula.upper()
    expected_type = expected.get('formula_type')
    if expected_type:
        expected_type_upper = expected_type.upper()
        if not formula_upper.startswith(f'={expected_type_upper}'):
            return 0.0
    formula_pattern = expected.get('formula_pattern')
    if formula_pattern:
        if not re.search(formula_pattern, formula_upper, re.IGNORECASE):
            return 0.0
    expected_value = expected.get('expected_value')
    if expected_value is not None:
        tolerance = options.get('tolerance', 0.01)
        if value is None:
            return 0.0
        if isinstance(value, (int, float)) and isinstance(expected_value, (int, float)):
            if abs(value - expected_value) > tolerance:
                return 0.0
        elif value != expected_value:
            return 0.0
    return 1.0

def check_xlsx_quarterly_totals__d05ab48ac420c4cb506bbc5272ef2448(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if quarterly total values match expected values for all sales reps.

    Args:
        result: Dict from getter containing:
            - 'headers': dict with 'q1_header' and 'q2_header'
            - 'reps': list of dicts with 'row', 'q1', and 'q2' for each rep
        expected: Dict (rules) containing:
            - 'expected_q1_per_rep': expected Q1 value for first rep (row 2)
            - 'expected_q2_per_rep': expected Q2 value for first rep (row 2)
        **options: Additional options

    Returns:
        Score from 0.0 to 1.0 based on:
        - 0.1 for correct Q1 header
        - 0.1 for correct Q2 header
        - 0.8 for all reps having correct Q1 and Q2 totals (proportional partial credit)
    """
    score = 0.0
    headers = result.get('headers', {})
    q1_header = headers.get('q1_header')
    q2_header = headers.get('q2_header')
    if q1_header and str(q1_header).strip() == 'Q1 Total':
        score += 0.1
    if q2_header and str(q2_header).strip() == 'Q2 Total':
        score += 0.1
    reps = result.get('reps', [])
    if not reps:
        return score
    expected_q1 = expected.get('expected_q1_per_rep')
    expected_q2 = expected.get('expected_q2_per_rep')
    if expected_q1 is None or expected_q2 is None:
        return score
    correct_reps = 0
    total_reps = len(reps)
    for rep in reps:
        rep_row = rep.get('row')
        q1_value = rep.get('q1')
        q2_value = rep.get('q2')
        if rep_row == 2:
            try:
                q1_match = q1_value is not None and int(q1_value) == int(expected_q1)
                q2_match = q2_value is not None and int(q2_value) == int(expected_q2)
                if q1_match and q2_match:
                    correct_reps += 1
            except (ValueError, TypeError):
                pass
        elif q1_value is not None and q2_value is not None:
            try:
                float(q1_value)
                float(q2_value)
                correct_reps += 1
            except (ValueError, TypeError):
                pass
    if total_reps > 0:
        score += 0.8 * (correct_reps / total_reps)
    return score

def check_commission_calc__c40b75e9(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Compare commission calculations against expected values.

    Args:
        result: Dict from getter with cell values
        expected: Dict with expected values
        **options: Additional options (tolerance for float comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    checks = 0
    passes = 0
    for (cell, exp_value) in expected.items():
        if cell in result:
            checks += 1
            if result[cell] is not None and exp_value is not None:
                if abs(result[cell] - exp_value) <= tolerance:
                    passes += 1
    if checks > 0:
        score = passes / checks
    return score

def check_calc_filtered_rows__74db1b1a9a1ea9ac0aabaabe6de0e702(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if rows are filtered/hidden as expected.

    Args:
        result: Dict with 'visible_rows', 'hidden_rows', 'rows_with_ellipsis' from getter
        expected: Dict with validation rules (verify_ellipsis_hidden, min_hidden, etc.)
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or 'hidden_rows' not in result:
        return 0.0
    hidden_rows = set(result.get('hidden_rows', []))
    rows_with_ellipsis = set(result.get('rows_with_ellipsis', []))
    hidden_count = len(hidden_rows)
    if expected.get('verify_ellipsis_hidden', False):
        if not rows_with_ellipsis:
            return 0.0
        ellipsis_not_hidden = rows_with_ellipsis - hidden_rows
        if ellipsis_not_hidden:
            return 0.0
        return 1.0
    if 'hidden_count' in expected:
        return 1.0 if hidden_count == expected['hidden_count'] else 0.0
    if 'min_hidden' in expected:
        return 1.0 if hidden_count >= expected['min_hidden'] else 0.0
    if 'max_hidden' in expected:
        return 1.0 if hidden_count <= expected['max_hidden'] else 0.0
    return 1.0 if hidden_count > 0 else 0.0

def check_xlsx_cell_value__afa197c0(result, expected, **options):
    """Check if a cell contains a formula and the value matches expected.

    Args:
        result: Dict with 'value' and 'formula' from getter
        expected: Dict with 'value' and optionally 'formula_pattern'
                  or just a value for backward compatibility
        **options: Additional options (e.g., tolerance for float comparison)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    tolerance = options.get('tolerance', 1e-09)
    if not isinstance(expected, dict):
        expected = {'value': expected}
    if isinstance(result, dict):
        result_value = result.get('value')
        result_formula = result.get('formula')
    else:
        result_value = result
        result_formula = None
    expected_value = expected.get('value')
    expected_formula_pattern = expected.get('formula_pattern')
    require_formula = expected.get('require_formula', True)
    if require_formula:
        if not result_formula:
            return 0.0
        if expected_formula_pattern:
            normalized_result = result_formula.upper().replace(' ', '')
            if isinstance(expected_formula_pattern, list):
                patterns = [p.upper().replace(' ', '') for p in expected_formula_pattern]
                if not any((normalized_result == p for p in patterns)):
                    return 0.0
            else:
                normalized_expected = expected_formula_pattern.upper().replace(' ', '')
                if normalized_result != normalized_expected:
                    return 0.0
    if expected_value is None:
        return 1.0
    if result_value is None and expected_value is None:
        return 1.0
    if result_value is None or expected_value is None:
        return 0.0
    if isinstance(result_value, (int, float)) and isinstance(expected_value, (int, float)):
        if abs(result_value - expected_value) < tolerance:
            return 1.0
        else:
            return 0.0
    if result_value == expected_value:
        return 1.0
    else:
        return 0.0

def check_xlsx_gross_profit_calculations__87606b1393cde1435f28787ed7fdd477(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Gross Profit column is correctly calculated and average is correct.

    Args:
        result: Dict containing gross_profit_values, net_sales_values, cogs_values, and average_in_j12
        expected: Dict containing expected_gross_profit_values and expected_average
        **options: Additional options (tolerance)

    Returns:
        float: 1.0 if all calculations are correct, 0.0 otherwise
    """
    if result is None:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    gross_profit_values = result.get('gross_profit_values', [])
    net_sales_values = result.get('net_sales_values', [])
    cogs_values = result.get('cogs_values', [])
    average_in_j12 = result.get('average_in_j12')
    expected_gp_values = expected.get('expected_gross_profit_values', [])
    expected_avg = expected.get('expected_average')
    if len(gross_profit_values) != len(expected_gp_values):
        return 0.0
    if len(net_sales_values) != len(gross_profit_values):
        return 0.0
    if len(cogs_values) != len(gross_profit_values):
        return 0.0
    for i in range(len(gross_profit_values)):
        gp = gross_profit_values[i]
        ns = net_sales_values[i]
        cogs = cogs_values[i]
        expected_gp = expected_gp_values[i]
        if gp is None or ns is None or cogs is None:
            return 0.0
        calculated_gp = ns - cogs
        if abs(gp - calculated_gp) > tolerance:
            return 0.0
        if abs(gp - expected_gp) > tolerance:
            return 0.0
    if average_in_j12 is None:
        return 0.0
    valid_gp_values = [gp for gp in gross_profit_values if gp is not None]
    if len(valid_gp_values) == 0:
        return 0.0
    calculated_avg = sum(valid_gp_values) / len(valid_gp_values)
    if abs(average_in_j12 - calculated_avg) > tolerance:
        return 0.0
    if abs(average_in_j12 - expected_avg) > tolerance:
        return 0.0
    return 1.0

