def check_xlsx_sorted_list__847027ee91d679e005aa3ad1dcb23d88(result, expected, **options):
    """Compare a list of values against an expected sorted list.

    Args:
        result: List of actual values from the getter
        expected: Dictionary containing the expected list of values
        **options: Additional comparison options

    Returns:
        float: 1.0 if lists match exactly, partial credit for partial matches
    """
    expected_list = expected.get('values', [])
    if not result and (not expected_list):
        return 1.0
    if not result or not expected_list:
        return 0.0
    result_normalized = [str(v).strip() for v in result]
    expected_normalized = [str(v).strip() for v in expected_list]
    if result_normalized == expected_normalized:
        return 1.0
    if len(result_normalized) != len(expected_normalized):
        return 0.0
    matches = sum((1 for (r, e) in zip(result_normalized, expected_normalized) if r == e))
    return matches / len(expected_normalized)

