def check_xlsx_content__4d5a7d17(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Excel table content matches expected values.

    Args:
        result: Table data from getter (list of lists)
        expected: Expected configuration with validation rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not result:
        return 0.0
    expected_rows = expected.get('rows', [])
    if not expected_rows:
        return 0.0
    data_rows = result[1:] if len(result) > 1 else []
    if len(data_rows) != len(expected_rows):
        return 0.0
    score = 0.0
    points_per_row = 1.0 / len(expected_rows) if expected_rows else 0.0
    for (idx, actual_row) in enumerate(data_rows):
        if idx >= len(expected_rows):
            break
        expected_row = expected_rows[idx]
        row_matches = True
        for (col_idx, expected_val) in enumerate(expected_row):
            if col_idx >= len(actual_row):
                row_matches = False
                break
            actual_val = actual_row[col_idx]
            if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                if abs(float(actual_val) - float(expected_val)) > 0.01:
                    row_matches = False
                    break
            elif actual_val != expected_val:
                row_matches = False
                break
        if row_matches:
            score += points_per_row
    return round(score, 2)

