    total_cells = len(cells_expected)
    correct_cells = 0
    for cell_spec in cells_expected:
        row = cell_spec['row']
        col = cell_spec['col']
        expected_value = cell_spec['value']
        key = f'{row},{col}'
        actual_value = result.get(key, '')
        if actual_value == expected_value:
            correct_cells += 1
    return correct_cells / total_cells if total_cells > 0 else 0.0

