def check_xlsx_cell_has_fill__9aee970f(result: str, expected: Any, **options) -> float:
    """Check if a specific cell in the result file has background fill color.

    Args:
        result: Path to the result Excel file
        expected: Dict with 'rules' containing 'cell' address to check
        **options: Additional options

    Returns:
        1.0 if cell has fill color, 0.0 otherwise
    """
    import tempfile
    import os
    if isinstance(expected, dict) and 'rules' in expected:
        rules = expected['rules']
    else:
        rules = expected if isinstance(expected, dict) else {}
    cell_addr = rules.get('cell')
    sheet_idx = rules.get('sheet', 0)
    if not cell_addr:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=False)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        has_fill = False
        if cell.fill and cell.fill.start_color:
            fill_type = cell.fill.fill_type
            if fill_type and fill_type != 'none':
                has_fill = True
            color_idx = cell.fill.start_color.index
            if color_idx and color_idx not in ['00000000', '00FFFFFF', 'FFFFFFFF']:
                has_fill = True
        wb.close()
        return 1.0 if has_fill else 0.0
    except Exception as e:
        return 0.0

