def check_xlsx_oldest_employee__6a0adc3d(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if the oldest employee task is completed correctly.

    This function verifies two requirements:
    1. Ages were calculated in column D (50% credit)
    2. The correct oldest employee name is in cell E2 (50% credit)

    Args:
        result: Dictionary with 'employee_name', 'ages_calculated', 'age_values', and 'birthdate_values'
        expected: Dictionary with 'employee_name' key for expected value
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 (0.5 for partial completion, 1.0 for full completion)
    """
    if result is None or not isinstance(result, dict):
        logger.error('Result is None or not a dictionary')
        return 0.0
    result_name = result.get('employee_name')
    expected_name = expected.get('employee_name')
    ages_calculated = result.get('ages_calculated', False)
    score = 0.0
    if ages_calculated:
        logger.info('Ages were correctly calculated in column D')
        score += 0.5
    else:
        logger.warning('Ages were NOT calculated in column D')
    if result_name is None:
        logger.error('No employee name found in result')
    elif expected_name is None:
        logger.error('No expected employee name provided')
    else:
        result_name_normalized = str(result_name).strip()
        expected_name_normalized = str(expected_name).strip()
        if result_name_normalized == expected_name_normalized:
            logger.info(f'Employee name matches: {result_name_normalized}')
            score += 0.5
        else:
            logger.info(f"Employee name mismatch: got '{result_name_normalized}', expected '{expected_name_normalized}'")
    logger.info(f'Final score: {score} (ages_calculated={ages_calculated}, name_match={score >= 1.0 or (score == 0.5 and (not ages_calculated))})')
    return score

