def check_xlsx_avg_passrate__08694a9dda332b4084eaa6c518085c0d(result: Dict[str, Any], expected: Dict[str, float], **options) -> float:
    """Compare extracted average pass rates against expected values.

    Verifies that:
    1. The spreadsheet contains data for expected years (2015-2023, excluding 2022)
    2. Each university has yearly data for those years
    3. The calculated averages match expected values

    Args:
        result: Dictionary with 'averages', 'years_present', and 'yearly_data'
        expected: Expected dictionary of university -> average pass rate
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or not expected:
        return 0.0
    tolerance = options.get('tolerance', 0.1)
    averages = result.get('averages', {})
    years_present = result.get('years_present', [])
    yearly_data = result.get('yearly_data', {})
    expected_years = {2015, 2016, 2017, 2018, 2019, 2020, 2021, 2023}
    years_present_set = set(years_present)
    if not expected_years.issubset(years_present_set):
        matching_years = years_present_set.intersection(expected_years)
        if len(matching_years) < len(expected_years):
            return 0.0
    universities = list(expected.keys())
    for uni in universities:
        if uni not in yearly_data:
            return 0.0
        uni_years = set(yearly_data[uni].keys())
        if not expected_years.issubset(uni_years):
            return 0.0
    correct_count = 0
    total_count = len(expected)
    for (uni, expected_avg) in expected.items():
        if uni in averages:
            if abs(averages[uni] - expected_avg) <= tolerance:
                correct_count += 1
    if correct_count < total_count:
        return correct_count / total_count
    return 1.0

