def check_xlsx_content__f0d1e78b(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """Check if Excel table content matches expected values.

    Args:
        result: Table data from getter (list of lists)
        expected: Expected configuration with validation rules
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or not result:
        return 0.0
    expected_rows = expected.get('rows', [])
    if not expected_rows:
        return 0.0
    if len(result) < 1:
        return 0.0
    header_row = result[0] if result else []
    expected_headers = ['Year Pair', 'Previous Rate (%)', 'Current Rate (%)', 'Change (%)']
    header_score = 0.0
    header_weight = 0.2
    data_weight = 0.8
    if header_row and len(header_row) >= len(expected_headers):
        actual_headers_normalized = [str(h).strip().lower() if h else '' for h in header_row[:len(expected_headers)]]
        expected_headers_normalized = [h.strip().lower() for h in expected_headers]
        headers_match = True
        for (exp_h, act_h) in zip(expected_headers_normalized, actual_headers_normalized):
            if exp_h not in act_h and act_h not in exp_h:
                if 'year' in exp_h and 'year' not in act_h:
                    headers_match = False
                    break
                elif 'previous' in exp_h and 'previous' not in act_h:
                    headers_match = False
                    break
                elif 'current' in exp_h and 'current' not in act_h:
                    headers_match = False
                    break
                elif 'change' in exp_h and 'change' not in act_h:
                    headers_match = False
                    break
        if headers_match:
            header_score = header_weight
    data_rows = result[1:] if len(result) > 1 else []
    if len(data_rows) != len(expected_rows):
        return header_score
    data_score = 0.0
    points_per_row = data_weight / len(expected_rows) if expected_rows else 0.0
    for (idx, actual_row) in enumerate(data_rows):
        if idx >= len(expected_rows):
            break
        expected_row = expected_rows[idx]
        row_matches = True
        for (col_idx, expected_val) in enumerate(expected_row):
            if col_idx >= len(actual_row):
                row_matches = False
                break
            actual_val = actual_row[col_idx]
            if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
                if abs(float(actual_val) - float(expected_val)) > 0.01:
                    row_matches = False
                    break
            elif actual_val != expected_val:
                row_matches = False
                break
        if row_matches:
            data_score += points_per_row
    return round(header_score + data_score, 2)

