def check_thunderbird_email_xlsx__5a2591df(result: str, expected: Dict[str, Any], **options) -> float:
    """
    Validate Thunderbird email extraction XLSX file.

    Args:
        result: Path to result XLSX file
        expected: Dict with 'email_data' (list of lists) and 'columns' (list of column names)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.active
        expected_data = expected.get('email_data', [])
        expected_columns = expected.get('columns', [])
        num_emails = len(expected_data)
        num_cols = len(expected_columns)
        if ws.max_row < num_emails + 1:
            return 0.0
        header_score = 0.0
        data_score = 0.0
        header_checks = 0
        for (col_idx, expected_col) in enumerate(expected_columns):
            actual_header = ws.cell(1, col_idx + 1).value
            if actual_header is not None:
                actual_header_str = str(actual_header).strip().lower()
            else:
                actual_header_str = ''
            expected_header_str = str(expected_col).strip().lower()
            if actual_header_str == expected_header_str:
                header_checks += 1
        header_score = header_checks / num_cols if num_cols > 0 else 0.0
        total_data_checks = num_emails * num_cols
        correct_data_checks = 0
        for row_idx in range(num_emails):
            expected_row = expected_data[row_idx]
            actual_row_idx = row_idx + 2
            for col_idx in range(num_cols):
                cell_value = ws.cell(actual_row_idx, col_idx + 1).value
                expected_value = expected_row[col_idx]
                if cell_value is not None:
                    cell_value_str = str(cell_value).strip()
                else:
                    cell_value_str = ''
                expected_value_str = str(expected_value).strip()
                if cell_value_str == expected_value_str:
                    correct_data_checks += 1
        data_score = correct_data_checks / total_data_checks if total_data_checks > 0 else 0.0
        final_score = 0.2 * header_score + 0.8 * data_score
        return final_score
    except Exception as e:
        return 0.0

