def check_xlsx_row_values__1e1c8fef409238e2677403d410317302(result, expected, **options):
    """Check if row values match the expected values.

    Args:
        result: List of actual cell values from getter
        expected: Dict with 'values' key containing expected list when type="rule"
        **options: Additional comparison options

    Returns:
        float: 1.0 if all match, partial score for partial matches, 0.0 otherwise
    """
    expected_values = expected.get('values', [])
    if not expected_values:
        return 0.0
    if not isinstance(result, list):
        return 0.0
    if len(result) != len(expected_values):
        return 0.0
    matches = 0
