def check_xlsx_valid__8e5ec6a12d03453e954276e7a0ba0dfb(result, expected, **options):
    """
    Check if .xlsx file is valid and properly formatted as a grades spreadsheet.
    Verifies semantic requirements: student names (text) and test scores (numbers).

    Args:
        result: Dict from getter with file validation info and content analysis
        expected: Dict with expected rules for grades spreadsheet structure
        **options: Additional options

    Returns:
        float: 1.0 if file is valid grades spreadsheet, 0.0 otherwise
    """
    if not isinstance(result, dict):
        return 0.0
    if not result.get('exists', False):
        return 0.0
    if not result.get('valid', False):
        return 0.0
    if not result.get('has_text_column', False):
        return 0.0
    if not result.get('has_numeric_column', False):
        return 0.0
    if result.get('row_count', 0) < 2:
        return 0.0
    if result.get('col_count', 0) < 2:
        return 0.0
    return 1.0

def check_xlsx_cell_text__84ebd0cc(result, expected, **options):
    """Check if cell text matches expected value.

    Args:
        result: Actual cell text from getter
        expected: Expected text value (can be dict with 'value' key or direct string)
        **options: Additional options (e.g., case_sensitive, strip_whitespace)

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if isinstance(expected, dict):
        expected_value = expected.get('value', '')
    else:
        expected_value = str(expected)
    case_sensitive = options.get('case_sensitive', True)
    strip_whitespace = options.get('strip_whitespace', True)
    actual = str(result) if result is not None else ''
    expected_str = str(expected_value)
    if strip_whitespace:
        actual = actual.strip()
        expected_str = expected_str.strip()
    if not case_sensitive:
        actual = actual.lower()
        expected_str = expected_str.lower()
    return 1.0 if actual == expected_str else 0.0

def check_xlsx_cell_value__1bc17300(result, expected, **options):
    """Check if cell value matches expected value."""
    if result is None:
        return 0.0
    expected_value = expected.get('expected_value') if isinstance(expected, dict) else expected
    if isinstance(expected_value, (int, float)) and isinstance(result, (int, float)):
        tolerance = options.get('tolerance', 0.01)
        return 1.0 if abs(result - expected_value) <= tolerance else 0.0
    return 1.0 if result == expected_value else 0.0

