def check_xlsx_title_row__160414d8(result: Any, expected: Dict[str, Any], **options) -> float:
    """Check if title cell has correct text and bold formatting, and row was inserted.

    Args:
        result: openpyxl Workbook object
        expected: Dict with 'sheet', 'cell', 'text_content', 'is_bold', 'row_inserted',
                  'original_row_1_content' keys
        **options: Additional options

    Returns:
        1.0 if all requirements met, partial score otherwise
    """
    if result is None:
        return 0.0
    try:
        sheet_idx = expected.get('sheet', 0)
        cell_addr = expected.get('cell', 'A1')
        text_content = expected.get('text_content', '')
        should_be_bold = expected.get('is_bold', False)
        check_row_inserted = expected.get('row_inserted', False)
        original_row_1_content = expected.get('original_row_1_content', {})
        if isinstance(sheet_idx, int):
            ws = result.worksheets[sheet_idx]
        else:
            ws = result[sheet_idx]
        cell = ws[cell_addr]
        score = 0.0
        if cell.value and str(cell.value).strip() == text_content.strip():
            score += 0.33
        else:
            result.close()
            return 0.0
        if should_be_bold:
            if cell.font and cell.font.bold:
                score += 0.33
            else:
                result.close()
                return 0.0
        else:
            score += 0.33
        if check_row_inserted and original_row_1_content:
            all_shifted = True
            for (cell_addr_orig, expected_value) in original_row_1_content.items():
                col_letter = ''.join((c for c in cell_addr_orig if c.isalpha()))
                cell_row2 = ws[f'{col_letter}2']
                if cell_row2.value is None or str(cell_row2.value).strip() != str(expected_value).strip():
                    all_shifted = False
                    break
            if all_shifted:
                score += 0.34
            else:
                result.close()
                return score
        elif check_row_inserted:
            row_2_has_content = False
            for col in range(1, 11):
                cell_row2 = ws.cell(row=2, column=col)
                if cell_row2.value is not None and str(cell_row2.value).strip() != '':
                    row_2_has_content = True
                    break
            if row_2_has_content:
                score += 0.34
            else:
                result.close()
                return score
        else:
            score += 0.34
        result.close()
        return min(score, 1.0)
    except Exception as e:
        if result:
            try:
                result.close()
            except:
                pass
        return 0.0

def check_xlsx_sorted_descending__75971d8335f90d2c29c457d822787380(result, expected, **options):
    """Check if data is sorted by marks in descending order.

    Args:
        result: list of dicts with 'order_id' and 'marks' keys
        expected: dict with 'rules' (not used, sorting verified by checking order)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, list) or len(result) == 0:
        return 0.0
    marks_sequence = []
    for item in result:
        mark = item.get('marks')
        if mark == '--' or mark is None:
            marks_sequence.append(None)
        else:
            try:
                marks_sequence.append(float(mark))
            except:
                marks_sequence.append(None)
    numeric_marks = [m for m in marks_sequence if m is not None]
    if not numeric_marks:
        return 0.0
    correctly_sorted = 0
    total_comparisons = len(numeric_marks) - 1
    for i in range(len(numeric_marks) - 1):
        if numeric_marks[i] >= numeric_marks[i + 1]:
            correctly_sorted += 1
    if total_comparisons > 0:
        score = correctly_sorted / total_comparisons
    else:
        score = 1.0 if len(numeric_marks) == 1 else 0.0
    rules = expected
    expected_top = rules.get('top_5_marks', [])
    if expected_top and len(numeric_marks) >= len(expected_top):
        top_actual = numeric_marks[:len(expected_top)]
        if top_actual == expected_top:
            score = min(1.0, score + 0.2)
    return min(1.0, score)

def check_xlsx_cell_fill__49c6ed3f(result, expected, **options):
    """Check if a cell has the expected fill color applied.

    Args:
        result: dict with 'has_fill' and 'color' from getter
        expected: dict with 'has_fill' (bool)
        **options: Additional options

    Returns:
        float: 1.0 if cell has fill, 0.0 otherwise
    """
    if not isinstance(result, dict):
        return 0.0
    expected_has_fill = expected.get('has_fill', True)
