def check_xlsx_column_values__042d725d749d513f8e050e7ccdf00eaf(result: List[Any], expected: List[Any], **options) -> float:
    """Check if column values match expected values including header.

    Args:
        result: List of values from getter (including header)
        expected: Expected values from rules (including header)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_values = expected.get('values', [])
    if not result or not expected_values:
        return 0.0
    if len(result) != len(expected_values):
        return 0.0
    score = 0.0
    points_per_match = 1.0 / len(expected_values)
    for (actual, expected_val) in zip(result, expected_values):
        if actual == expected_val:
            score += points_per_match
    return min(1.0, score)

def check_xlsx_row_highlight__a7f2e8c3(result, expected, **options):
    """Check if row highlighting matches expected (with fuzzy color matching).

    Args:
        result: Actual highlighting info dict
        expected: Expected highlighting dict
        **options: Additional options including color_tolerance

    Returns:
        float: 1.0 if match, 0.0 otherwise
    """
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    if not result.get('has_fill', False):
        return 0.0
    if 'color' in expected:
        result_color = result.get('color')
        expected_color = expected['color']
        if not result_color:
            return 0.0
        if isinstance(result_color, str) and len(result_color) == 8:
            result_color = result_color[2:]
        if isinstance(expected_color, str) and len(expected_color) == 8:
            expected_color = expected_color[2:]
        tolerance = options.get('color_tolerance', 20)
        strict = options.get('strict_color_match', False)
        if strict:
            return 1.0 if result_color.upper() == expected_color.upper() else 0.0
        else:
            try:
                r_r = int(result_color[0:2], 16) if result_color else 0
                r_g = int(result_color[2:4], 16) if result_color else 0
                r_b = int(result_color[4:6], 16) if result_color else 0
                e_r = int(expected_color[0:2], 16)
                e_g = int(expected_color[2:4], 16)
                e_b = int(expected_color[4:6], 16)
                dist = abs(r_r - e_r) + abs(r_g - e_g) + abs(r_b - e_b)
                if dist <= tolerance * 3:
                    return 1.0
            except:
                pass
            return 0.0
    return 1.0

def check_xlsx_data__ad2d10da(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    if 'has_headers' in expected and expected['has_headers']:
        total_checks += 1
        if len(result) > 0 and result[0]:
            score += 1.0
    if 'min_rows' in expected:
        total_checks += 1
        if len(result) >= expected['min_rows']:
            score += 1.0
    if 'column_headers' in expected:
        total_checks += 1
        expected_headers = expected['column_headers']
        if len(result) > 0 and result[0]:
            actual_headers = []
            for i in range(min(len(expected_headers), len(result[0]))):
                if result[0][i] is not None:
                    actual_headers.append(str(result[0][i]).strip())
                else:
                    actual_headers.append('')
            if len(actual_headers) >= len(expected_headers):
                matches = sum((1 for (i, exp_header) in enumerate(expected_headers) if i < len(actual_headers) and actual_headers[i].lower() == exp_header.lower()))
                if matches == len(expected_headers):
                    score += 1.0
    if 'filenames' in expected:
        total_checks += 1
        expected_filenames = expected['filenames']
        if isinstance(result, list) and len(result) > 1:
            actual_filenames = []
            for row in result[1:]:
                if row and len(row) > 0 and (row[0] is not None):
                    actual_filenames.append(str(row[0]).strip())
            expected_set = set((f.lower() for f in expected_filenames))
            actual_set = set((f.lower() for f in actual_filenames))
            if expected_set == actual_set:
                score += 1.0
    if 'has_underscore_values' in expected and 'filenames' in expected:
        total_checks += 1
        expected_filenames = expected['filenames']
        expected_underscore_vals = expected['has_underscore_values']
        if isinstance(result, list) and len(result) > 1:
            filename_to_underscore = {}
            for (fname, underscore_val) in zip(expected_filenames, expected_underscore_vals):
                filename_to_underscore[fname.lower()] = underscore_val.lower()
            all_correct = True
            for row in result[1:]:
                if row and len(row) >= 2:
                    if row[0] is not None and row[1] is not None:
                        filename = str(row[0]).strip().lower()
                        underscore_val = str(row[1]).strip().lower()
                        if filename in filename_to_underscore:
                            if underscore_val != filename_to_underscore[filename]:
                                all_correct = False
                                break
                        has_underscore = '_' in filename
                        expected_val = 'yes' if has_underscore else 'no'
                        if underscore_val != expected_val:
                            all_correct = False
                            break
            if all_correct:
                score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

