def check_xlsx_cell_text__f34c53b18d1e220995e8c85ed1c984b2(result, expected, **options):
    """Verify cell contains correct formula using TEXT function and produces expected output.

    Args:
        result: dict - Dictionary with 'formula' (str or None) and 'value' (str)
        expected: dict - Rules with 'text' key containing expected calculated text
        **options: Additional comparison options

    Returns:
        float: 1.0 if formula structure and value both match, 0.0 otherwise
    """
    expected_text = expected.get('text', '')
    formula = result.get('formula', None)
    value = result.get('value', '')
    if not formula:
        return 0.0
    if not formula.startswith('='):
        return 0.0
    if 'TEXT' not in formula.upper():
        return 0.0
    if 'C1' not in formula.upper():
        return 0.0
    text_pattern = re.compile('TEXT\\s*\\(\\s*C1\\s*,\\s*"0\\.00"\\s*\\)', re.IGNORECASE)
    if not text_pattern.search(formula):
        return 0.0
    result_normalized = ' '.join(value.split())
    expected_normalized = ' '.join(expected_text.split())
    if result_normalized != expected_normalized:
        return 0.0
    return 1.0

def check_xlsx_high_scorers__7f0af0e188b31bf7749a24911a13ada8(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if column N header is correct and high scorers are marked with 'Excellent'.

    Args:
        result: Dictionary with column_n_header and students data
        expected: Dictionary with 'student_ids' key containing expected high scorer IDs
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    column_n_header = result.get('column_n_header')
    if column_n_header != 'Performance Level':
        return 0.0
    expected_ids = set((str(id) for id in expected.get('student_ids', [])))
    students = result.get('students', [])
    for student in students:
        student_id = student.get('student_id')
        total_score = student.get('total_score')
        performance_level = student.get('performance_level')
        is_high_scorer = isinstance(total_score, (int, float)) and total_score > 80
        if is_high_scorer:
            if performance_level != 'Excellent':
                return 0.0
            if student_id not in expected_ids:
                return 0.0
        elif performance_level == 'Excellent':
            return 0.0
    marked_ids = set((s.get('student_id') for s in students if s.get('performance_level') == 'Excellent'))
    if marked_ids != expected_ids:
        return 0.0
    return 1.0

def check_xlsx_sorted_range__8f2cb9de(result: List, expected: Any, **options) -> float:
    """Check if range data is sorted correctly by verifying entire columns moved together."""
    if not result:
        return 0.0
    expected_order = expected.get('expected_order', [])
    expected_columns = expected.get('expected_columns', [])
    if len(result) < 4:
        return 0.0
    marks_row = result[3]
    if marks_row != expected_order:
        return 0.0
    if expected_columns:
        num_cols = len(result[0]) if result else 0
        num_rows = len(result)
        actual_columns = []
        for col_idx in range(num_cols):
            column = []
            for row_idx in range(num_rows):
                column.append(result[row_idx][col_idx])
            actual_columns.append(column)
        if len(actual_columns) != len(expected_columns):
            return 0.0
        for i in range(len(expected_columns)):
            if actual_columns[i] != expected_columns[i]:
                return 0.0
    for i in range(len(marks_row) - 1):
        if marks_row[i] < marks_row[i + 1]:
            return 0.0
    num_cols = len(marks_row)
    for row in result:
        if len(row) != num_cols:
            return 0.0
    for col_idx in range(num_cols):
        for row_idx in range(len(result)):
            if result[row_idx][col_idx] is None:
                return 0.0
    return 1.0

def check_xlsx_top_title__b985b2a4e8be32e6adbcbc28cd034e20(result, expected, **options):
    """Check if the top_10 sheet has exactly 10 highest-rated movies sorted correctly.

    Verifies:
    1. Sheet exists
    2. Exactly 10 data rows (movies)
    3. Headers are present (at least 3 columns: Title, Year/Genre, Rating)
    4. First movie is "The Shawshank Redemption" (highest rated at 9.3)
    5. Ratings are in descending order
    6. All top 10 movies match the expected highest-rated movies

    Args:
        result: dict from getter with 'headers', 'movies', 'row_count'
        expected: dict with 'title' (expected first movie title)
        **options: Additional options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if result is None:
        return 0.0
    row_count = result.get('row_count', 0)
    if row_count != 10:
        return 0.0
    movies = result.get('movies', [])
    if len(movies) != 10:
        return 0.0
    headers = result.get('headers', [])
    if len(headers) < 3:
        return 0.0
    expected_title = expected.get('title', '')
    if not movies or movies[0]['title'] != expected_title:
        return 0.0
    for i in range(len(movies) - 1):
        if movies[i]['rating'] < movies[i + 1]['rating']:
            return 0.0
    expected_top_movies = {'The Shawshank Redemption': 9.3, 'The Godfather': 9.2, '12th Fail': 9.1}
    for (title, expected_rating) in expected_top_movies.items():
        found = False
        for movie in movies[:3]:
            if movie['title'] == title and abs(movie['rating'] - expected_rating) < 0.01:
                found = True
                break
        if not found:
            return 0.0
    fight_club_found = False
    for movie in movies:
        if movie['title'] == 'Fight Club' and abs(movie['rating'] - 8.8) < 0.01:
            fight_club_found = True
            break
    if not fight_club_found:
        return 0.0
    if movies[0]['rating'] < 8.8:
        return 0.0
    return 1.0

