def check_xlsx_div5_highlights__ea0b86726c42fccb88e4653f98d2a571(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if all cells with dates divisible by 5 are highlighted AND other cells are NOT highlighted.

    This implements complete verification:
    1. All expected cells (dates divisible by 5) have the orange background
    2. All other date cells do NOT have the orange background (remain unmodified)

    Args:
        result: Dict with 'div5_cells' and 'non_div5_cells' mappings from getter
        expected: Dict with 'expected_color' (hex RGB string) and 'div5_cells' (list of cell coordinates)
        **options: Additional options including 'color_tolerance' for fuzzy matching

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_color = expected.get('expected_color', 'FFFFA500')
    expected_div5_cells = expected.get('div5_cells', [])
    color_tolerance = options.get('color_tolerance', 20)
    strict_color_match = options.get('strict_color_match', False)
    if not expected_div5_cells:
        return 0.0
    div5_cells = result.get('div5_cells', {})
    non_div5_cells = result.get('non_div5_cells', {})

    def colors_match(color1: str, color2: str) -> bool:
        """Check if two RGB hex colors match (with optional tolerance)."""
        if not color1 or not color2:
            return False
        if len(color1) == 8:
            color1 = color1[2:]
        if len(color2) == 8:
            color2 = color2[2:]
        if strict_color_match:
            return color1.upper() == color2.upper()
        try:
            (r1, g1, b1) = (int(color1[0:2], 16), int(color1[2:4], 16), int(color1[4:6], 16))
            (r2, g2, b2) = (int(color2[0:2], 16), int(color2[2:4], 16), int(color2[4:6], 16))
            distance = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** 0.5
            return distance <= color_tolerance
        except (ValueError, IndexError):
            return False
    positive_correct = 0
    for cell_coord in expected_div5_cells:
        actual_color = div5_cells.get(cell_coord)
        if actual_color and colors_match(actual_color, expected_color):
            positive_correct += 1
    positive_score = positive_correct / len(expected_div5_cells) if expected_div5_cells else 0.0
    negative_violations = 0
    for (cell_coord, actual_color) in non_div5_cells.items():
        if actual_color and colors_match(actual_color, expected_color):
            negative_violations += 1
    total_non_div5 = len(non_div5_cells)
    if total_non_div5 > 0:
        negative_score = 1.0 - negative_violations / total_non_div5
    else:
        negative_score = 1.0
    found_div5_cells = set(div5_cells.keys())
    expected_div5_set = set(expected_div5_cells)
    if not expected_div5_set.issubset(found_div5_cells):
        missing_cells = expected_div5_set - found_div5_cells
        completeness_penalty = len(missing_cells) / len(expected_div5_cells)
        positive_score *= 1.0 - completeness_penalty
    final_score = min(positive_score, negative_score)
    return final_score

def check_xlsx_sorted__f879a701adc4437a0bc9a0b0caafa6ee(result, expected, **options):
    """Check if column values are sorted in the expected order.

    Args:
        result: List of cell values from getter
        expected: Rules dict with 'order' key ('asc' or 'desc')
        **options: Additional options

    Returns:
        float: Score based on sorting correctness (0.0 to 1.0)
    """
    order = expected.get('order', 'desc')
    filtered_values = [v for v in result if v is not None and isinstance(v, (int, float))]
    if not filtered_values:
        return 0.0
    if order == 'desc':
        expected_sorted = sorted(filtered_values, reverse=True)
    else:
        expected_sorted = sorted(filtered_values)
    matches = sum((1 for (a, b) in zip(filtered_values, expected_sorted) if a == b))
    total = len(filtered_values)
    return matches / total if total > 0 else 0.0

