def check_xlsx_cells__cf730b17(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Excel cells contain expected values.
    
    Args:
        result: Dict mapping cell addresses to their actual values
        expected: Dict with 'cells' key containing expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', {})
