    if cell_value is None:
        return 0.0
    try:
        if abs(float(cell_value) - expected_value) > 0.0001:
            return 0.0
    except (ValueError, TypeError):
        return 0.0
    if not number_format or number_format == 'General':
        return 0.0
    decimal_pattern = '\\.([0#]+)'
    matches = re.findall(decimal_pattern, number_format)
    if not matches:
        return 0.0
    for match in matches:
        decimal_places = len(match)
        if decimal_places == 3:
            return 1.0
    return 0.0

