def check_xlsx_monthly_averages__eb50740fcad46322488405cbbbfc4363(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if monthly average sales are calculated correctly and row header is present.

    Verifies:
    - Cell A12 contains the correct row header (e.g., "Average")
    - Row 12 columns B-G contain correct average values

    Args:
        result: Dict from getter with 'row_header' and 'averages'
        expected: Dict with 'row_header' and 'averages' - expected values
        **options: Additional options (tolerance for floating point comparison)

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_averages = expected.get('averages', {})
    result_averages = result.get('averages', {})
    expected_row_header = expected.get('row_header', '')
    result_row_header = result.get('row_header', '')
    if not expected_averages:
        return 0.0
    header_correct = result_row_header.strip().lower() == expected_row_header.strip().lower()
    tolerance = options.get('tolerance', 0.1)
    correct_count = 0
    total_count = len(expected_averages)
    for (col_idx, expected_val) in expected_averages.items():
        result_val = result_averages.get(col_idx, 0)
        if abs(result_val - expected_val) <= tolerance:
            correct_count += 1
    total_checks = total_count + 1
    correct_checks = correct_count + (1 if header_correct else 0)
    score = correct_checks / total_checks if total_checks > 0 else 0.0
    return min(score, 1.0)

def check_xlsx_sheet_movies_rating_year__6a4580a32f0bf3d4b38c71fe86adb466(result: List[List[Any]], expected: Dict[str, Any], **options) -> float:
    """
    Check if a sheet contains movies filtered by rating and sorted by year.

    Args:
        result: List of rows from the Excel sheet (from getter)
        expected: Dict with 'min_rating' and 'sort_order' ('asc' or 'desc')
        **options: Additional options

    Returns:
        Score between 0.0 and 1.0
    """
    if not result or len(result) < 2:
        return 0.0
    min_rating = expected.get('min_rating', 9.0)
    sort_order = expected.get('sort_order', 'asc')
    expected_count = expected.get('expected_count', None)
    score = 0.0
    header = result[0]
    expected_header = ['title', 'release year', 'ratings', 'description']
    if header[:4] == expected_header:
        score += 0.3
    else:
        return 0.0
    data_rows = result[1:]
    all_ratings_valid = True
    for row in data_rows:
        if len(row) < 3:
            all_ratings_valid = False
            break
        rating = row[2]
        if rating is None or float(rating) < min_rating:
            all_ratings_valid = False
            break
    if all_ratings_valid:
        score += 0.3
    else:
        return score
    years = [int(row[1]) for row in data_rows if row[1] is not None]
    if sort_order == 'asc':
        is_sorted = all((years[i] <= years[i + 1] for i in range(len(years) - 1)))
    else:
        is_sorted = all((years[i] >= years[i + 1] for i in range(len(years) - 1)))
    if is_sorted:
        score += 0.2
    else:
        return score
    if expected_count is not None:
        if len(data_rows) == expected_count:
            score += 0.2
        else:
            return score
    return 1.0

