def check_xlsx_contains_values__533170be(result, expected, **options):
    """Check if result list contains all expected values with correct frequencies.

    Args:
        result: List of actual values
        expected: Dict with category frequencies OR list of required values
        **options: ignore_case option, expected_counts for category frequencies

    Returns:
        float: Score based on matching categories with correct frequencies
    """
    if not expected:
        return 1.0
    ignore_case = options.get('ignore_case', True)
    expected_counts = options.get('expected_counts', {})
    result_strs = [str(v).strip() for v in result if v is not None]
    if ignore_case:
        result_strs = [s.lower() for s in result_strs]
    if expected_counts:
        from collections import Counter
        result_counter = Counter(result_strs)
        total_required = 0
        correct_matches = 0
        for (category, min_count) in expected_counts.items():
            category_norm = category.strip()
            if ignore_case:
                category_norm = category_norm.lower()
            total_required += min_count
            actual_count = result_counter.get(category_norm, 0)
            if actual_count >= min_count:
                correct_matches += min_count
            else:
                correct_matches += actual_count
        if total_required == 0:
            return 1.0
        return correct_matches / total_required
    matches = 0
    for exp_val in expected:
        exp_str = str(exp_val).strip()
        if ignore_case:
            exp_str = exp_str.lower()
        if exp_str in result_strs:
            matches += 1
    return matches / len(expected)

def check_xlsx_sorted_desc__f2436e05(result, expected, **options):
    """Check if a specific column in an XLSX file is sorted in descending order.

    Args:
        result: Path to the result XLSX file
        expected: Dict with 'sheet' (int/str), 'column' (str), 'start_row' (int),
                  and 'end_row' (int) keys defining the range to check
        **options: Additional options

    Returns:
        float: 1.0 if the column is sorted in descending order, 0.0 otherwise
    """
    if result is None:
        logger.error('Result file path is None')
        return 0.0
    try:
        wb = openpyxl.load_workbook(filename=result)
        rules = expected
        sheet_idx = rules.get('sheet', 0)
        if isinstance(sheet_idx, int):
            sheet_names = wb.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available sheets: {sheet_names}')
                return 0.0
            sheet = wb[sheet_names[sheet_idx]]
        else:
            sheet = wb[sheet_idx]
        column_letter = rules.get('column')
        if not column_letter:
            logger.error('Column not specified in rules')
            return 0.0
        col_idx = column_index_from_string(column_letter)
        start_row = rules.get('start_row', 2)
        end_row = rules.get('end_row')
        if end_row is None:
            end_row = sheet.max_row
        values = []
        for row_idx in range(start_row, end_row + 1):
            cell = sheet.cell(row=row_idx, column=col_idx)
            value = cell.value
            if value is not None:
                try:
                    numeric_value = float(value)
                    values.append(numeric_value)
                except (ValueError, TypeError):
                    values.append(str(value))
            else:
                logger.warning(f'Cell {column_letter}{row_idx} is None, skipping')
                continue
        if len(values) == 0:
            logger.error('No values found in the specified range')
            return 0.0
        is_sorted_desc = True
        for i in range(len(values) - 1):
            if values[i] < values[i + 1]:
                logger.error(f'Values not in descending order: {values[i]} < {values[i + 1]} at position {i}')
                is_sorted_desc = False
                break
        if is_sorted_desc:
            logger.info(f'Column {column_letter} rows {start_row}-{end_row} is sorted in descending order: {values}')
            return 1.0
        else:
            logger.error(f'Column {column_letter} rows {start_row}-{end_row} is NOT sorted in descending order: {values}')
            return 0.0
    except Exception as e:
        logger.error(f'Error checking column sort: {e}')
        import traceback
        logger.error(traceback.format_exc())
        return 0.0

