def check_xlsx_sorted_order__86fac272(result: List[str], expected: Dict[str, Any], **options) -> float:
    """
    Check if the data has been sorted correctly by verifying the top employees.

    This function verifies that the data has been sorted by age in descending order
    (oldest to youngest) by checking if the expected top employees appear in the
    first few rows. The task requires calculating ages from birthdates and sorting.

    Args:
        result: List of employee names in the current order from the file
        expected: Dictionary containing:
            - 'top_employees': List of expected top employee names in order
            - 'check_count': Number of top employees to verify (default: 5)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
            - 1.0 if the top employees match in order
            - Partial score for partial matches
            - 0.0 if no match or errors
    """
    if result is None or not isinstance(result, list):
        logger.error('Result is None or not a list')
        return 0.0
    if not result:
        logger.error('Result list is empty')
        return 0.0
    if expected is None or not isinstance(expected, dict):
        logger.error('Expected is None or not a dictionary')
        return 0.0
    expected_top = expected.get('top_employees', [])
    check_count = expected.get('check_count', len(expected_top))
    if not expected_top:
        logger.error('No expected top employees provided in rules')
        return 0.0
    check_count = min(check_count, len(expected_top))
    actual_top = result[:check_count]
    logger.info(f'Checking top {check_count} employees')
    logger.info(f'Expected: {expected_top[:check_count]}')
    logger.info(f'Actual: {actual_top}')
    matches = 0
    for i in range(min(len(actual_top), check_count)):
        actual_name = actual_top[i].strip() if i < len(actual_top) else ''
        expected_name = expected_top[i].strip() if i < len(expected_top) else ''
        if actual_name == expected_name:
            matches += 1
            logger.info(f"Position {i + 1}: Match - '{actual_name}'")
        else:
            logger.warning(f"Position {i + 1}: Mismatch - got '{actual_name}', expected '{expected_name}'")
    if check_count > 0:
        score = matches / check_count
    else:
        score = 0.0
    logger.info(f'Final score: {score:.2f} ({matches}/{check_count} correct positions)')
    return 1.0 if score == 1.0 else score

