def check_xlsx_total_row__3f45fd7b(result_state, expected_state, **options):
    """
    Check if the total row in xlsx file matches expected values.

    This function verifies:
    1. The label "Total" is in the correct column of the specified row
    2. The revenue total matches the expected sum
    3. The expenses total matches the expected sum

    Args:
        result_state: Dict of row data from getter {row_num: [cell_values]}
        expected_state: Dict containing:
            - sheet: Sheet index (0-based)
            - row: Row number to check (1-based)
            - label_col: Column number for label (1-based)
            - label_text: Expected label text
            - revenue_col: Column number for revenue total (1-based)
            - revenue_total: Expected revenue sum
            - expenses_col: Column number for expenses total (1-based)
            - expenses_total: Expected expenses sum

    Returns:
        float: Score (1.0 if all checks pass, 0.0 otherwise)
    """
    if result_state is None:
        logger.error('Result state is None')
        return 0.0
    rules = expected_state
    row_num = rules['row']
    label_col = rules['label_col']
    label_text = rules['label_text']
    revenue_col = rules['revenue_col']
    revenue_total = rules['revenue_total']
    expenses_col = rules['expenses_col']
    expenses_total = rules['expenses_total']
    if row_num not in result_state:
        logger.error(f'Row {row_num} not found in result state')
        return 0.0
    row_data = result_state[row_num]
    if len(row_data) < label_col:
        logger.error(f'Row {row_num} does not have enough columns for label at column {label_col}')
        return 0.0
    actual_label = row_data[label_col - 1]
    if actual_label != label_text:
        logger.error(f"Label mismatch at row {row_num} column {label_col}: expected '{label_text}', got '{actual_label}'")
        return 0.0
    if len(row_data) < revenue_col:
        logger.error(f'Row {row_num} does not have enough columns for revenue at column {revenue_col}')
        return 0.0
    actual_revenue = row_data[revenue_col - 1]
    try:
        if isinstance(actual_revenue, (int, float)):
            if abs(actual_revenue - revenue_total) > 0.01:
                logger.error(f'Revenue mismatch at row {row_num} column {revenue_col}: expected {revenue_total}, got {actual_revenue}')
                return 0.0
        else:
            logger.error(f'Revenue value is not numeric at row {row_num} column {revenue_col}: {actual_revenue}')
            return 0.0
    except Exception as e:
        logger.error(f'Error comparing revenue: {e}')
        return 0.0
    if len(row_data) < expenses_col:
        logger.error(f'Row {row_num} does not have enough columns for expenses at column {expenses_col}')
        return 0.0
    actual_expenses = row_data[expenses_col - 1]
    try:
        if isinstance(actual_expenses, (int, float)):
            if abs(actual_expenses - expenses_total) > 0.01:
                logger.error(f'Expenses mismatch at row {row_num} column {expenses_col}: expected {expenses_total}, got {actual_expenses}')
                return 0.0
        else:
            logger.error(f'Expenses value is not numeric at row {row_num} column {expenses_col}: {actual_expenses}')
            return 0.0
    except Exception as e:
        logger.error(f'Error comparing expenses: {e}')
        return 0.0
    logger.info(f'All checks passed for total row {row_num}')
    return 1.0

