def check_xlsx_cell_colors__462e6eae(result: Dict[str, str], expected: Dict[str, Any], **options) -> float:
    """Check if specified cells have the expected background color.

    Args:
        result: Dict mapping cell coordinates to their hex color values (from getter)
        expected: Dict with 'cells' (list of cell coords) and 'color' (expected hex color)
        **options: Additional options (tolerance for color matching, etc.)

    Returns:
        float: Score between 0.0 and 1.0 (proportion of cells with correct color)
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', [])
    expected_color = expected.get('color', '').upper()
    if not expected_cells or not expected_color:
        return 0.0
    if not expected_color.startswith('#'):
        expected_color = f'#{expected_color}'
    expected_color = expected_color.upper()
    correct_count = 0
    total_count = len(expected_cells)
    for cell_coord in expected_cells:
        actual_color = result.get(cell_coord, '').upper()
        if actual_color and (not actual_color.startswith('#')):
            actual_color = f'#{actual_color}'
        if actual_color == expected_color:
            correct_count += 1
    if total_count == 0:
        return 0.0
    return correct_count / total_count

def check_xlsx_average_value__0ea2a1d3eca19edbbb06cd91771ccf92(result: Optional[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if the average was calculated correctly using a formula.

    Args:
        result: Dict with 'value', 'has_formula', 'formula', 'references_sheet1' keys
        expected: Rules dict with 'value' key containing expected average
        **options: Additional options (tolerance, etc.)

    Returns:
        Score between 0.0 and 1.0
    """
    if result is None:
        return 0.0
    expected_value = expected.get('value')
    if expected_value is None:
        return 0.0
    result_value = result.get('value')
    has_formula = result.get('has_formula', False)
    formula = result.get('formula', '')
    references_sheet1 = result.get('references_sheet1', False)
    if result_value is None:
        return 0.0
    try:
        expected_float = float(expected_value)
        result_float = float(result_value)
        tolerance = options.get('tolerance', 1.0)
        value_correct = abs(result_float - expected_float) <= tolerance
        if not value_correct:
            return 0.0
        if not has_formula:
            return 0.5
        formula_has_average = 'AVERAGE' in formula.upper() if formula else False
        if not formula_has_average:
            return 0.6
        if not references_sheet1:
            return 0.7
        return 1.0
    except (ValueError, TypeError):
        return 0.0

def check_xlsx_row_count__e4b27550(result, expected, **options):
    """Check if the XLSX file has the expected number of data rows.

    Args:
        result: Path to the result XLSX file
        expected: Dict with 'sheet' (int/str) and 'row_count' (int) keys
        **options: Additional options

    Returns:
        float: 1.0 if row count matches, 0.0 otherwise
    """
    if result is None:
        logger.error('Result file path is None')
        return 0.0
    try:
        wb = openpyxl.load_workbook(filename=result)
        sheet_idx = expected.get('sheet', 0)
        if isinstance(sheet_idx, int):
            sheet_names = wb.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available sheets: {sheet_names}')
                return 0.0
            sheet = wb[sheet_names[sheet_idx]]
        else:
            sheet = wb[sheet_idx]
        data_rows = 0
        max_row = sheet.max_row
        for row_idx in range(2, max_row + 1):
            row = sheet[row_idx]
            if any((cell.value is not None and str(cell.value).strip() != '' for cell in row)):
                data_rows += 1
        expected_count = expected.get('row_count')
        logger.info(f'Found {data_rows} data rows, expected {expected_count}')
        if data_rows == expected_count:
            return 1.0
        else:
            return 0.0
    except Exception as e:
        logger.error(f'Error checking row count: {e}')
        return 0.0

def check_calc_late_comers_highlight__bf0e9d8b(result, expected, **options):
    """Check if late comer employee cells are highlighted in yellow.

    Args:
        result: Path to the Excel file
        expected: Dict with 'late_comer_rows' (list of 1-based row indices) and 'employee_col'
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 with partial credit
    """
    if not os.path.exists(result):
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        sheet_idx = expected.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        late_comer_rows = expected.get('late_comer_rows', [])
        employee_col = expected.get('employee_col', 'B')
        if not late_comer_rows:
            return 0.0
        highlighted_count = 0
        for row_num in late_comer_rows:
            cell = ws[f'{employee_col}{row_num}']
            if cell.fill and cell.fill.patternType is not None and (cell.fill.patternType != 'none'):
                if cell.fill.fgColor and hasattr(cell.fill.fgColor, 'rgb'):
                    rgb = cell.fill.fgColor.rgb
                    if rgb:
                        if isinstance(rgb, str) and len(rgb) >= 6:
                            hex_color = rgb[-6:] if len(rgb) == 8 else rgb
                            r = int(hex_color[0:2], 16)
                            g = int(hex_color[2:4], 16)
                            b = int(hex_color[4:6], 16)
                            if r > 200 and g > 200 and (b < 100):
                                highlighted_count += 1
                            else:
                                highlighted_count += 0.5
        wb.close()
        total_late_comers = len(late_comer_rows)
        score = highlighted_count / total_late_comers
        return min(1.0, score)
    except Exception as e:
        print(f'Error checking late comers highlight: {e}')
        return 0.0

