def check_xlsx_cells__62a16582(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if Excel cells contain expected values.
    
    Args:
        result: Dict mapping cell addresses to their actual values
        expected: Dict with 'cells' key containing expected values
        **options: Additional options
        
    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    expected_cells = expected.get('cells', {})
    if not expected_cells:
        return 0.0
    score = 0.0
    tolerance = options.get('tolerance', 0.5)
    for (cell_addr, expected_val) in expected_cells.items():
        actual_val = result.get(cell_addr)
        if actual_val is None:
            continue
        if isinstance(expected_val, (int, float)) and isinstance(actual_val, (int, float)):
            if abs(actual_val - expected_val) <= tolerance:
                score += 1.0
        elif isinstance(expected_val, str) and isinstance(actual_val, str):
            if expected_val.strip().lower() == actual_val.strip().lower():
                score += 1.0
        elif actual_val == expected_val:
            score += 1.0
    return score / len(expected_cells) if len(expected_cells) > 0 else 0.0

