def check_xlsx_period_rate_sum__da315cf2edc339756d9b2f4defe564ad(result, expected, **options):
    """Check if period rates are correctly calculated with proper column header, numeric values, and sum.

    Args:
        result: dict from getter with keys: header, period_rate_values, sum_value, sum_row_label, total_data_rows
        expected: dict with keys: expected_sum
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    header = result.get('header')
    if header != 'Period Rate (%)':
        return 0.0
    total_data_rows = result.get('total_data_rows', 0)
    if total_data_rows != 24:
        return 0.0
    period_rate_values = result.get('period_rate_values', [])
    if len(period_rate_values) != 24:
        return 0.0
    tolerance = 0.01
    for row_data in period_rate_values:
        annual_rate = row_data.get('annual_rate')
        period_per_year = row_data.get('period_per_year')
        period_rate = row_data.get('period_rate')
        is_numeric = row_data.get('is_numeric', False)
        if annual_rate is None or period_per_year is None or period_rate is None:
            return 0.0
        if not is_numeric:
            return 0.0
        if period_per_year == 0:
            return 0.0
        expected_period_rate = annual_rate / period_per_year
        if abs(period_rate - expected_period_rate) >= tolerance:
            return 0.0
    sum_row_label = result.get('sum_row_label', '').lower()
    if not any((keyword in sum_row_label for keyword in ['sum', 'total'])):
        return 0.0
    sum_value = result.get('sum_value')
    expected_sum = expected.get('expected_sum')
    if sum_value is None or expected_sum is None:
        return 0.0
    if abs(sum_value - expected_sum) >= tolerance:
        return 0.0
    return 1.0

def check_xlsx_column_list__eab4dd2b(result, expected, **options):
    """
    Check if a list of values matches the expected list.

    Args:
        result: List of actual values from the getter
        expected: Dict with 'rules' containing 'values' key (list)

    Returns:
        float: Score between 0.0 and 1.0 based on match
    """
    try:
        expected_values = expected.get('values', [])
        if not isinstance(result, list):
            return 0.0
        result_normalized = [str(v).strip() for v in result]
        expected_normalized = [str(v).strip() for v in expected_values]
        if result_normalized == expected_normalized:
            return 1.0
        else:
            matches = sum((1 for (r, e) in zip(result_normalized, expected_normalized) if r == e))
            return matches / max(len(expected_normalized), 1)
    except Exception as e:
        print(f'Error in check_xlsx_column_list__eab4dd2b: {e}')
        return 0.0

def check_calc_column_sorted__97603c2aac57c1af54be56cd28b81bb2(result: List[Any], expected: Dict[str, Any], **options) -> float:
    """Check if column data is sorted in the expected order.

    Args:
        result: List of cell values from column
        expected: Expected configuration with 'order' ('ascending' or 'descending')
        **options: Additional options

    Returns:
        1.0 if sorted correctly, partial credit for partial sorting, 0.0 otherwise
    """
    order = expected.get('order', 'ascending')
    if not result:
        return 0.0
    filtered = [v for v in result if v is not None]
    if len(filtered) == 0:
        return 0.0
    is_sorted = True
    if order == 'ascending':
        for i in range(len(filtered) - 1):
            if filtered[i] > filtered[i + 1]:
                is_sorted = False
                break
    elif order == 'descending':
        for i in range(len(filtered) - 1):
            if filtered[i] < filtered[i + 1]:
                is_sorted = False
                break
    else:
        return 0.0
    return 1.0 if is_sorted else 0.0

