def check_xlsx_column_formula__a4efe2d1(result, expected, **options):
    """Check if column header exists, formulas are correct, and values match expected results.

    Args:
        result: Dict with 'header', 'formulas', and 'values' from getter
        expected: Dict with 'header' (string) and 'sample_values' (list of tuples with row and value)
        **options: tolerance for numeric comparison (default 0.01)

    Returns:
        float: Score based on header (20%) + formulas (60%) + sample values (20%)
    """
    tolerance = options.get('tolerance', 0.01)
    if not isinstance(result, dict) or not isinstance(expected, dict):
        return 0.0
    score = 0.0
    if result.get('header') == expected.get('header'):
        score += 0.2
    formulas = result.get('formulas', [])
    if formulas:
        start_row = 2
        formula_matches = 0
        total_formula_checks = len(formulas)
        for (idx, formula) in enumerate(formulas):
            row_num = start_row + idx
            if formula:
                normalized = formula.upper().replace(' ', '')
                pattern1 = f'=A{row_num}+C{row_num}'
                pattern2 = f'=C{row_num}+A{row_num}'
                if normalized == pattern1 or normalized == pattern2:
                    formula_matches += 1
                else:
                    regex = re.compile(f'^=(?:A{row_num}\\+C{row_num}|C{row_num}\\+A{row_num})$', re.IGNORECASE)
                    if regex.match(normalized):
                        formula_matches += 1
        if total_formula_checks > 0:
            score += 0.6 * (formula_matches / total_formula_checks)
    sample_values = expected.get('sample_values', [])
    if len(sample_values) > 0:
        result_values = result.get('values', [])
        matches = 0
        for (row_offset, exp_val) in sample_values:
            if row_offset < len(result_values):
                res_val = result_values[row_offset]
                if res_val is not None and exp_val is not None:
                    try:
                        res_num = float(res_val)
                        exp_num = float(exp_val)
                        if abs(res_num - exp_num) <= tolerance:
                            matches += 1
                    except (ValueError, TypeError):
                        if res_val == exp_val:
                            matches += 1
        score += 0.2 * (matches / len(sample_values))
    return score

