def check_xlsx_fullname_column__7f52c02b47ed466c5317abba8c7318a2(result, expected, **options):
    """Check if employee data task was completed correctly.

    Verifies three requirements:
    1. Column A data is preserved/unchanged
    2. Columns B, C, D contain split data (First Name, Last Name, Rank)
    3. Column E has 'Full Name' header and correct combined values

    Args:
        result: Dict with column data and headers from getter
        expected: Dict with expected values including:
            - full_names: list of expected full names
            - original_data: list of original column A values (format: "First/Last/Rank")

    Returns:
        float: Score between 0.0 and 1.0 (composite score of all checks)
    """
    if not isinstance(result, dict):
        return 0.0
    column_a_data = result.get('column_a_data', [])
    column_b_data = result.get('column_b_data', [])
    column_c_data = result.get('column_c_data', [])
    column_d_data = result.get('column_d_data', [])
    column_e_header = result.get('column_e_header', '')
    column_e_data = result.get('column_e_data', [])
    expected_full_names = expected.get('full_names', [])
    expected_original_data = expected.get('original_data', [])
    if not expected_full_names:
        return 0.0
    num_rows = len(expected_full_names)
    scores = []
    if expected_original_data:
        if len(column_a_data) == len(expected_original_data):
            a_correct = 0
            for i in range(len(expected_original_data)):
                if i < len(column_a_data):
                    if column_a_data[i].strip().lower() == expected_original_data[i].strip().lower():
                        a_correct += 1
            a_score = a_correct / len(expected_original_data) if len(expected_original_data) > 0 else 0.0
        else:
            a_score = 0.0
        scores.append(a_score)
    if expected_original_data and len(expected_original_data) == num_rows:
        b_correct = 0
        c_correct = 0
        d_correct = 0
        for i in range(num_rows):
            parts = expected_original_data[i].split('/')
            if len(parts) == 3:
                expected_first = parts[0].strip()
                expected_last = parts[1].strip()
                expected_rank = parts[2].strip()
                if i < len(column_b_data):
                    if column_b_data[i].strip().lower() == expected_first.lower():
                        b_correct += 1
                if i < len(column_c_data):
                    if column_c_data[i].strip().lower() == expected_last.lower():
                        c_correct += 1
                if i < len(column_d_data):
                    if column_d_data[i].strip().lower() == expected_rank.lower():
                        d_correct += 1
        split_score = (b_correct + c_correct + d_correct) / (num_rows * 3) if num_rows > 0 else 0.0
        scores.append(split_score)
    e_header_correct = column_e_header.strip().lower() == 'full name'
    scores.append(1.0 if e_header_correct else 0.0)
    if len(column_e_data) == len(expected_full_names):
        e_correct = 0
        for i in range(len(expected_full_names)):
            if i < len(column_e_data):
                if column_e_data[i].strip().lower() == expected_full_names[i].strip().lower():
                    e_correct += 1
        e_data_score = e_correct / len(expected_full_names) if len(expected_full_names) > 0 else 0.0
    else:
        e_data_score = 0.0
    scores.append(e_data_score)
    overall_score = sum(scores) / len(scores) if scores else 0.0
    return overall_score

