def check_xlsx_row_font_size__cae78dd8(result, expected, **options):
    """Check if row font sizes match expected.

    Args:
        result: dict with 'font_sizes' from getter
        expected: dict with 'min_size' or 'target_size'
        **options: 'tolerance' for size comparison

    Returns:
        float: Score based on match
    """
    tolerance = options.get('tolerance', 1.0)
    result_sizes = result.get('font_sizes', {})
    if 'min_size' in expected:
        min_size = expected['min_size']
        valid_cells = 0
        total_cells = 0
        for (col, size) in result_sizes.items():
            if size is not None:
                total_cells += 1
                if size >= min_size - tolerance:
                    valid_cells += 1
        if total_cells > 0:
            return valid_cells / total_cells
        else:
            return 0.0
    if 'target_size' in expected:
        target = expected['target_size']
        valid_cells = 0
        total_cells = 0
        for (col, size) in result_sizes.items():
            if size is not None:
                total_cells += 1
                if abs(size - target) <= tolerance:
                    valid_cells += 1
        if total_cells > 0:
            return valid_cells / total_cells
        else:
            return 0.0
    return 0.0

def check_calc_pivot_table__aec249c5da95a40917cfa74665da9b60(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """Check if LibreOffice Calc task was completed correctly:
    1. 'Discount Amount' column added to Sheet1
    2. Pivot table created in Sheet2 showing average discount percentage per product

    Args:
        result: Data from getter containing both Sheet1 and Sheet2 info
        expected: Expected validation rules including:
            - expected_products: List of products that should appear
            - expected_averages: Dict of product -> average discount (for verification)
        **options: Additional comparison options

    Returns:
        float: Score between 0.0 (fail) and 1.0 (pass) with partial credit
    """
    score = 0.0
    has_discount_column = result.get('has_discount_column', False)
    if has_discount_column:
        score += 0.15
        discount_col_idx = result.get('discount_column_index')
        sample_rows = result.get('sheet1_sample_rows', [])
        headers = result.get('sheet1_headers', [])
        quantity_idx = None
        price_idx = None
        discount_pct_idx = None
        for (idx, header) in enumerate(headers):
            if header:
                h = str(header).lower()
                if 'quantity' in h:
                    quantity_idx = idx
                elif 'price' in h or 'retail' in h:
                    price_idx = idx
                elif 'discount' in h and 'amount' not in h:
                    discount_pct_idx = idx
        if quantity_idx is not None and price_idx is not None and (discount_pct_idx is not None) and (discount_col_idx is not None):
            correct_calculations = 0
            total_checked = 0
            for row_info in sample_rows[:5]:
                row_data = row_info['data']
                if len(row_data) > max(quantity_idx, price_idx, discount_pct_idx, discount_col_idx):
                    qty = row_data[quantity_idx]
                    price = row_data[price_idx]
                    discount_pct = row_data[discount_pct_idx]
                    discount_amt = row_data[discount_col_idx]
                    if all((isinstance(v, (int, float)) for v in [qty, price, discount_pct, discount_amt])):
                        expected_discount_amt = qty * price * discount_pct
                        if abs(discount_amt - expected_discount_amt) / (expected_discount_amt + 0.0001) < 0.01:
                            correct_calculations += 1
                        total_checked += 1
            if total_checked > 0 and correct_calculations / total_checked >= 0.8:
                score += 0.15
    if result.get('has_sheet2'):
        score += 0.1
        pivot_data = result.get('pivot_data', [])
        if pivot_data and len(pivot_data) > 1:
            score += 0.1
    pivot_headers = result.get('pivot_headers', [])
    pivot_values = result.get('pivot_values', [])
    has_product_header = False
    has_aggregation_header = False
    for header in pivot_headers:
        if header:
            h = str(header).lower()
            if 'product' in h or 'name' in h:
                has_product_header = True
            if any((word in h for word in ['average', 'mean', 'avg', 'discount'])):
                has_aggregation_header = True
    if has_product_header:
        score += 0.1
    if has_aggregation_header:
        score += 0.1
    expected_products = expected.get('expected_products', [])
    expected_averages = expected.get('expected_averages', {})
    if expected_products and pivot_values:
        products_found = set()
        product_values = {}
        for row in pivot_values:
            if row and len(row) >= 2:
                product_name = str(row[0]) if row[0] is not None else None
                avg_value = None
                for cell in row[1:]:
                    if isinstance(cell, (int, float)):
                        avg_value = cell
                        break
                if product_name:
                    products_found.add(product_name)
                    if avg_value is not None:
                        product_values[product_name] = avg_value
        found_count = sum((1 for product in expected_products if product in products_found))
        if found_count > 0:
            score += 0.15 * (found_count / len(expected_products))
        if expected_averages and product_values:
            matching_values = 0
            total_checkable = 0
            for (product, expected_avg) in expected_averages.items():
                if product in product_values:
                    actual_avg = product_values[product]
                    tolerance = max(0.01, abs(expected_avg * 0.05))
                    if abs(actual_avg - expected_avg) <= tolerance:
                        matching_values += 1
                    total_checkable += 1
            if total_checkable > 0:
                score += 0.15 * (matching_values / total_checkable)
    return min(score, 1.0)

