def check_xlsx_autofilter__2ab3f8b42cd3028c3a38925ff15c7ec1(result, expected, **options):
    """Check if AutoFilter is properly enabled on the data range.

    Args:
        result: dict with 'enabled' and 'range' keys from getter
        expected: dict with 'rules' containing expected filter configuration
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not isinstance(result, dict):
        return 0.0
    rules = expected
    expected_enabled = rules.get('enabled', True)
    if not result.get('enabled'):
        return 0.0 if expected_enabled else 1.0
    filter_range = result.get('range', '')
    if not filter_range:
        return 0.5
    try:
        if ':' in filter_range:
            (start_cell, end_cell) = filter_range.split(':')
            start_row = int(''.join(filter(str.isdigit, start_cell)))
            end_row = int(''.join(filter(str.isdigit, end_cell)))
            if start_row == 1 and end_row >= 3:
                expected_range = rules.get('range')
                if expected_range:
                    if filter_range == expected_range:
                        return 1.0
                    start_col = ''.join(filter(str.isalpha, start_cell))
                    end_col = ''.join(filter(str.isalpha, end_cell))
                    exp_start = ''.join(filter(str.isalpha, expected_range.split(':')[0]))
                    exp_end = ''.join(filter(str.isalpha, expected_range.split(':')[1]))
                    if start_col == exp_start and end_col == exp_end:
                        return 1.0
                    return 0.8
                else:
                    return 1.0
            else:
                return 0.3
        else:
            return 0.3
    except (ValueError, IndexError):
        return 0.5
    return 0.5

