def check_xlsx_receipts_and_total__f94dfcd1(result, expected, **options):
    """Check if receipts were added to spreadsheet AND total in D15 is correct.

    This metric verifies BOTH requirements:
    1. Receipt transactions were added to the spreadsheet
    2. Cell D15 contains the correct total

    Args:
        result: Dict from getter containing 'cell_d15', 'all_rows', 'expense_amounts'
        expected: Dict with 'total' and 'receipt_amounts' keys
        **options: Additional options (tolerance, min_new_entries)

    Returns:
        float: Score from 0.0 to 1.0
            - 0.5 if only D15 is correct (missing receipt entries)
            - 1.0 if both D15 and receipts are verified
            - 0.0 if D15 is incorrect
    """
    if result is None:
        return 0.0
    tolerance = options.get('tolerance', 0.5)
    min_new_entries = options.get('min_new_entries', 5)
    expected_total = expected.get('total', 4024.79)
    expected_receipt_amounts = expected.get('receipt_amounts', [186.93, 3670.0, 5.7, 154.06, 8.1])
    cell_d15 = result.get('cell_d15')
    d15_correct = False
    if cell_d15 is not None:
        try:
            d15_val = float(cell_d15)
            if abs(d15_val - expected_total) <= tolerance:
                d15_correct = True
        except (ValueError, TypeError):
            pass
    if not d15_correct:
        return 0.0
    expense_amounts = result.get('expense_amounts', [])
    receipt_amounts_found = 0
    for expected_amt in expected_receipt_amounts:
        for actual_amt in expense_amounts:
            if abs(actual_amt - expected_amt) <= tolerance:
                receipt_amounts_found += 1
                break
    if receipt_amounts_found >= min_new_entries:
        return 1.0
    return 0.5

