def check_calc_sort__b23280c3(result, expected, **options):
    """Check if data is sorted correctly by a specific column.

    Args:
        result: Path to the Excel file
        expected: Dict with 'sheet_name', 'sort_column', 'sort_order'

    Returns:
        float: Score between 0.0 and 1.0
    """
    sheet_name = expected.get('sheet_name')
    sort_column = expected.get('sort_column')
    sort_order = expected.get('sort_order')
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        if sheet_name not in wb.sheetnames:
            return 0.0
        ws = wb[sheet_name]
        headers = [cell.value for cell in ws[1]]
        if sort_column not in headers:
            return 0.0
        sort_col_idx = headers.index(sort_column)
        data_values = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is not None:
                data_values.append(row[sort_col_idx])
        order_map = {val: idx for (idx, val) in enumerate(sort_order)}
        is_sorted = True
        for i in range(len(data_values) - 1):
            val1 = data_values[i]
            val2 = data_values[i + 1]
            if val1 in order_map and val2 in order_map:
                if order_map[val1] > order_map[val2]:
                    is_sorted = False
                    break
        return 1.0 if is_sorted else 0.0
    except Exception as e:
        return 0.0

def check_xlsx_conditional_fill__2b9f429d(result, expected, **options):
    """
    Check if Excel cells have fill color based on a condition.

    Args:
        result: Path to the Excel file
        expected: Dictionary with rules containing:
            - sheet: Sheet index (0-based) or name
            - column: Column letter to check
            - start_row: Starting row number
            - end_row: Ending row number
            - condition_threshold: Value threshold for condition
            - cells_should_have_fill: List of cells that should have fill
            - cells_should_not_have_fill: List of cells that should not have fill
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    try:
        sheet_idx = expected.get('sheet', 0)
        cells_should_have_fill = expected.get('cells_should_have_fill', [])
        cells_should_not_have_fill = expected.get('cells_should_not_have_fill', [])
        if not os.path.exists(result):
            return 0.0
        wb = openpyxl.load_workbook(result, data_only=False)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        total_checks = len(cells_should_have_fill) + len(cells_should_not_have_fill)
        if total_checks == 0:
            return 0.0
        passed_checks = 0
        for cell_coord in cells_should_have_fill:
            cell = ws[cell_coord]
            has_fill = cell.fill and cell.fill.start_color and (cell.fill.start_color.index != '00000000')
            if has_fill:
                passed_checks += 1
        for cell_coord in cells_should_not_have_fill:
            cell = ws[cell_coord]
            has_fill = cell.fill and cell.fill.start_color and (cell.fill.start_color.index != '00000000')
            if not has_fill:
                passed_checks += 1
        score = passed_checks / total_checks if total_checks > 0 else 0.0
        return score
    except Exception as e:
        return 0.0

