    for (birthdate, age, category) in result:
        birth_year = birthdate.year
        expected_age = current_year - birth_year
        age_is_correct = abs(age - expected_age) <= 1
        category_lower = category.lower()
        expected_category = None
        if age < young_max:
            expected_category = 'young'
        elif age <= middle_max:
            expected_category = 'middle'
        else:
            expected_category = 'senior'
        category_is_correct = expected_category in category_lower
        if age_is_correct and category_is_correct:
            correct_age_and_category += 1
    if total > 0:
        return correct_age_and_category / total
    return 0.0

