def check_xlsx_data__2985a4b2(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    if 'min_rows' in expected:
        total_checks += 1
        if len(result) >= expected['min_rows']:
            score += 1.0
    if 'has_headers' in expected and expected['has_headers']:
        total_checks += 1
        if 'headers' in expected:
            expected_headers = expected['headers']
            if len(result) > 0 and result[0]:
                actual_headers = [str(cell).strip() for cell in result[0] if cell is not None]
                expected_headers_normalized = [str(h).strip() for h in expected_headers]
                if len(actual_headers) >= len(expected_headers_normalized):
                    if all((actual_headers[i] == expected_headers_normalized[i] for i in range(len(expected_headers_normalized)))):
                        score += 1.0
        elif len(result) > 0 and result[0]:
            score += 1.0
    if 'filenames' in expected:
        total_checks += 1
        expected_filenames = expected['filenames']
        if isinstance(result, list) and len(result) > 1:
            actual_filenames = []
            for row in result[1:]:
                if row and len(row) > 0:
                    actual_filenames.append(str(row[0]).strip() if row[0] is not None else '')
            actual_filenames_normalized = [f.lower() for f in actual_filenames if f]
            expected_filenames_normalized = [str(f).strip().lower() for f in expected_filenames]
            if len(actual_filenames_normalized) >= len(expected_filenames_normalized):
                if set(expected_filenames_normalized).issubset(set(actual_filenames_normalized)):
                    score += 1.0
    if 'topics' in expected:
        total_checks += 1
        expected_topics = expected['topics']
        if isinstance(result, list) and len(result) > 1:
            actual_topics = []
            for row in result[1:]:
                if row and len(row) > 1:
                    actual_topics.append(str(row[1]).strip() if row[1] is not None else '')
            actual_topics_normalized = [t.lower() for t in actual_topics if t]
            expected_topics_normalized = [str(t).strip().lower() for t in expected_topics]
            if len(actual_topics_normalized) >= len(expected_topics_normalized):
                if set(expected_topics_normalized).issubset(set(actual_topics_normalized)):
                    score += 1.0
    if 'count' in expected:
        total_checks += 1
        if len(result) > 1 and len(result[1]) > 1:
            try:
                count_val = int(result[1][1])
                if count_val == expected['count']:
                    score += 1.0
            except:
                pass
    return score / total_checks if total_checks > 0 else 0.0

