def check_xlsx_vowels_replaced__b77c56f4(result, expected, **options):
    """Check if vowels are replaced with asterisks in result.

    Args:
        result: list of cell values from getter
        expected: dict from config['rules']
        **options: Additional options

    Returns:
        float: Score based on how many values have vowels replaced
    """
    if not result or len(result) < 20:
        return 0.0
    vowels = 'AEIOUaeiou'
    score = 0.0
    for value in result:
        if isinstance(value, str):
            has_asterisks = '*' in value
            has_vowels = any((v in value for v in vowels))
            if has_asterisks and (not has_vowels):
                score += 1.0 / len(result)
            elif not has_asterisks and (not has_vowels):
                score += 0.5 / len(result)
    return min(score, 1.0)

