def check_profit_calc__10951371(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Compare profit calculations against expected values.

    Args:
        result: Dict from getter with cell values
        expected: Dict with expected values
        **options: Additional options (tolerance for float comparison)

    Returns:
        Score between 0.0 and 1.0
    """
    if isinstance(result, dict) and 'error' in result:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    score = 0.0
    checks = 0
