def check_xlsx_period_rate_top3__0b4e7bcf218238ee895daa79b9295ba9(result, expected, **options):
    """Check period rate calculation, sorting, data integrity, and column header.

    This metric verifies:
    1. Column header "Period Rate (%)" exists
    2. All 24 data rows have calculated period rate values
    3. Top 3 rows are correctly sorted in descending order
    4. Data integrity: Each row's period rate matches Annual Rate / Period (verifies sorting didn't break row relationships)

    Args:
        result: dict from getter with keys:
            - header_exists: bool
            - top3_rows: list of dicts with annual_rate, period, period_rate
            - all_rows_calculated: bool
        expected: dict with keys:
            - expected_top3: list of expected period rate values in descending order
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    header_exists = result.get('header_exists', False)
    if not header_exists:
        return 0.0
    score = 0.0
    all_rows_calculated = result.get('all_rows_calculated', False)
    if all_rows_calculated:
        score += 0.2
    top3_rows = result.get('top3_rows', [])
    expected_top3 = expected.get('expected_top3', [])
    if len(top3_rows) < 3 or len(expected_top3) < 3:
        return score
    tolerance = 0.0001
    for i in range(3):
        row_data = top3_rows[i]
        expected_period_rate = expected_top3[i]
        annual_rate = row_data.get('annual_rate')
        period = row_data.get('period')
        period_rate = row_data.get('period_rate')
        if annual_rate is None or period is None or period_rate is None:
            continue
        if abs(period_rate - expected_period_rate) < tolerance:
            if period != 0:
                calculated_period_rate = annual_rate / period
                if abs(period_rate - calculated_period_rate) < tolerance:
                    score += 0.2
                else:
                    score += 0.1
    return min(score, 1.0)

def check_xlsx_sorted__b50dbd6e(result, expected, **options):
    """
    Check if data is sorted correctly.

    Args:
        result: List of values from getter
        expected: Expected sorting configuration (from rules)
        **options: Additional options

    Returns:
        float: 1.0 if sorted correctly, 0.0 otherwise
    """
    if not result:
        return 0.0
    order = expected.get('order', 'ascending')
    top_values = expected.get('top_values', [])
    if order == 'descending':
        is_sorted = all((result[i] >= result[i + 1] for i in range(len(result) - 1) if isinstance(result[i], (int, float)) and isinstance(result[i + 1], (int, float))))
    else:
        is_sorted = all((result[i] <= result[i + 1] for i in range(len(result) - 1) if isinstance(result[i], (int, float)) and isinstance(result[i + 1], (int, float))))
    if top_values:
        top_n = len(top_values)
        actual_top = result[:top_n]
        if actual_top != top_values:
            return 0.0
    if is_sorted:
        return 1.0
    return 0.0

def check_calc_time_value__02fa34d3(result, expected, **options):
    """Check if a cell contains the correct average clock-out time using a formula.

    This function verifies:
    1. Cell E16 contains a formula (NOT a manually entered value)
    2. The formula uses appropriate averaging functions (AVERAGE, AVERAGEIF, AVERAGEIFS)
    3. The calculated time is within ±5 minutes of the expected average (16:57:27)

    Args:
        result: Path to the Excel file
        expected: Dict with 'cell', 'min_time', 'max_time'
        **options: Additional options

    Returns:
        float: 1.0 if formula is correct and result is within tolerance, 0.0 otherwise
    """
    if not os.path.exists(result):
        return 0.0
    try:
        wb_formula = openpyxl.load_workbook(result, data_only=False)
        sheet_idx = expected.get('sheet', 0)
        ws_formula = wb_formula.worksheets[sheet_idx]
        cell_addr = expected.get('cell', 'E16')
        cell_formula = ws_formula[cell_addr]
        if not cell_formula.value or not isinstance(cell_formula.value, str) or (not cell_formula.value.startswith('=')):
            print(f'Cell {cell_addr} does not contain a formula. Manual entry is not allowed.')
            wb_formula.close()
            return 0.0
        formula_upper = cell_formula.value.upper()
        has_average_function = any((func in formula_upper for func in ['AVERAGE(', 'AVERAGEIF(', 'AVERAGEIFS(']))
        if not has_average_function:
            print(f'Formula in {cell_addr} does not use AVERAGE/AVERAGEIF/AVERAGEIFS functions.')
            print(f'Formula: {cell_formula.value}')
            wb_formula.close()
            return 0.0
        wb_formula.close()
        wb = openpyxl.load_workbook(result, data_only=True)
        ws = wb.worksheets[sheet_idx]
        cell = ws[cell_addr]
        min_time_str = expected.get('min_time', '16:52:27')
        max_time_str = expected.get('max_time', '17:02:27')
        (min_h, min_m, min_s) = map(int, min_time_str.split(':'))
        (max_h, max_m, max_s) = map(int, max_time_str.split(':'))
        min_time_obj = time(min_h, min_m, min_s)
        max_time_obj = time(max_h, max_m, max_s)
        cell_time = None
        if isinstance(cell.value, time):
            cell_time = cell.value
        elif isinstance(cell.value, datetime):
            cell_time = cell.value.time()
        elif isinstance(cell.value, (int, float)):
            total_seconds = int(cell.value * 86400)
            hours = total_seconds // 3600
            minutes = total_seconds % 3600 // 60
            seconds = total_seconds % 60
            cell_time = time(hours, minutes, seconds)
        if cell_time is None:
            print(f'Cell {cell_addr} does not contain a valid time value.')
            wb.close()
            return 0.0
        if min_time_obj <= cell_time <= max_time_obj:
            wb.close()
            return 1.0
        else:
            print(f'Cell {cell_addr} time {cell_time} is outside expected range {min_time_obj} to {max_time_obj}')
            wb.close()
            return 0.0
    except Exception as e:
        print(f'Error checking time value: {e}')
        return 0.0

def check_xlsx_cell_value__9db059d44308c11cf4b8667fcfae1ca4(result: Any, expected: dict, **options) -> float:
    """
    Check if a cell value matches the expected value with optional tolerance.

    Args:
        result: The actual cell value from the getter
        expected: Dict with key 'value' containing the expected value
        **options: Optional parameters:
                   - tolerance: Acceptable difference for numeric values (default: 0.01)

    Returns:
        1.0 if values match (within tolerance for numbers), 0.0 otherwise
    """
    expected_value = expected.get('value')
    tolerance = options.get('tolerance', 0.01)
    if result is None and expected_value is None:
        return 1.0
    if result is None or expected_value is None:
        return 0.0
    if isinstance(result, (int, float)) and isinstance(expected_value, (int, float)):
        if abs(result - expected_value) <= tolerance:
            return 1.0
        else:
            return 0.0
    if result == expected_value:
        return 1.0
    else:
        return 0.0

def check_xlsx_exact_match__003d46ef(result, expected, **options):
    """Check exact match with expected value.

    Args:
        result: Cell value from getter
        expected: dict with 'value' key
        **options: case_sensitive (default True)

    Returns:
        float: 1.0 if exact match, 0.0 otherwise
    """
    if result is None:
        return 0.0
    expected_value = expected.get('value')
    case_sensitive = options.get('case_sensitive', True)
    if not case_sensitive:
        result_str = str(result).strip().lower() if result is not None else ''
        expected_str = str(expected_value).strip().lower() if expected_value is not None else ''
        return 1.0 if result_str == expected_str else 0.0
