def check_xlsx_cells_match__ad0fa89c(result: Dict[str, Any], expected: dict, **options) -> float:
    """Check if multiple cells match their expected values with partial credit.
    
    Args:
        result: Dict of cell_ref -> value from getter
        expected: Dict with 'cells' mapping cell_ref -> expected_value
        
    Returns:
        Score from 0.0 to 1.0 based on proportion of matching cells
    """
    expected_cells = expected.get('cells', {})
    if not expected_cells:
        return 0.0
    total_cells = len(expected_cells)
    matched_cells = 0
    for (cell_ref, expected_value) in expected_cells.items():
        actual_value = result.get(cell_ref)
        if isinstance(expected_value, (int, float)) and isinstance(actual_value, (int, float)):
            if abs(actual_value - expected_value) < 0.001:
                matched_cells += 1
        elif actual_value == expected_value:
            matched_cells += 1
    return matched_cells / total_cells

def check_xlsx_column_values__7f77ed076bde0928b5bd349818f9e9dd(result, expected, **options):
    """Check if column values match the expected values.

    Args:
        result: List of actual cell values from the getter
        expected: List of expected values
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0 based on matching values
    """
    if not result or not expected:
        return 0.0
    if not isinstance(result, list):
        result = [result]
    if not isinstance(expected, list):
        expected = [expected]
    if len(result) != len(expected):
        return 0.0
    matches = 0
    for (r, e) in zip(result, expected):
        if str(r) == str(e):
            matches += 1
    return matches / len(expected) if expected else 0.0

def check_calc_dual_cell__6ccc187a(result, expected, **options):
    """Check if two cells contain expected label and value.

    Args:
        result: Path to the Excel file
        expected: Dict with 'sheet_name', 'label_cell', 'label_value', 'value_cell', 'value'

    Returns:
        float: Score between 0.0 and 1.0
    """
    sheet_name = expected.get('sheet_name')
    label_cell = expected.get('label_cell')
