def check_xlsx_cell_value__8b19e0a46112d77c948c80a533176073(result, expected, **options):
    """Compare a cell's formula and value against expected values.

    Args:
        result: Dict with 'formula' and 'value' from getter
        expected: Expected dict (from rules) with 'value' and optionally 'has_formula' and 'formula_contains'
        **options: Additional comparison options

    Returns:
        float: 1.0 if all checks pass, 0.0 otherwise
    """
    if not isinstance(result, dict):
        return 0.0
    has_formula = expected.get('has_formula', False)
    if has_formula:
        if not result.get('formula'):
            return 0.0
    formula_contains = expected.get('formula_contains')
    if formula_contains:
        formula = result.get('formula', '')
        if not formula:
            return 0.0
        formula_normalized = formula.upper().replace(' ', '')
        if isinstance(formula_contains, list):
            for required_text in formula_contains:
                required_normalized = required_text.upper().replace(' ', '')
                if required_normalized not in formula_normalized:
                    return 0.0
        elif isinstance(formula_contains, str):
            required_normalized = formula_contains.upper().replace(' ', '')
            if required_normalized not in formula_normalized:
                return 0.0
    expected_value = expected.get('value')
    if expected_value is not None:
        actual_value = result.get('value')
        if isinstance(actual_value, (int, float)) and isinstance(expected_value, (int, float)):
            tolerance = options.get('tolerance', 0.01)
            if abs(actual_value - expected_value) > tolerance:
                return 0.0
        elif actual_value != expected_value:
            return 0.0
    return 1.0

def check_xlsx_number_format_func__6e7ef195509486de3a1f8ba73f2685d9(result: str, expected: Dict[str, Any], **options) -> float:
    """Check if a cell formula uses TEXT or FIXED function for number formatting.

    Args:
        result: The actual cell formula (from getter)
        expected: Dict with 'accepts' key - list of acceptable function names
        **options: Additional options

    Returns:
        float: 1.0 if formula uses one of the acceptable functions correctly, 0.0 otherwise
    """
    if not result:
        return 0.0
    acceptable_funcs = expected.get('accepts', [])
    if not acceptable_funcs:
        return 0.0
    formula_upper = result.upper().strip()
    if not formula_upper.startswith('='):
        return 0.0
    if 'FIXED' in acceptable_funcs:
        fixed_pattern = 'FIXED\\s*\\(\\s*C1\\s*,\\s*2\\s*(?:,.*?)?\\)'
        if re.search(fixed_pattern, formula_upper):
            return 1.0
    if 'TEXT' in acceptable_funcs:
        text_pattern = 'TEXT\\s*\\(\\s*C1\\s*,\\s*["\\\'].*?\\.(?:00|##)["\\\'].*?\\)'
        if re.search(text_pattern, formula_upper):
            return 1.0
        text_pattern2 = 'TEXT\\s*\\(\\s*C1\\s*,\\s*["\\\'][^"\\\']*?(?:#,##)?0\\.00[^"\\\']*?["\\\'].*?\\)'
        if re.search(text_pattern2, formula_upper):
            return 1.0
    return 0.0

