def check_xlsx_sort_c61a195e(result, expected, **options):
    """Check if data is sorted correctly by reading the xlsx file"""
    import openpyxl
    import io
    if result is None:
        return 0.0
    try:
        if isinstance(result, str):
            wb = openpyxl.load_workbook(result, data_only=True)
        else:
            wb = openpyxl.load_workbook(io.BytesIO(result), data_only=True)
    except Exception as e:
        return 0.0
    rules = expected
    sheet_idx = rules.get('sheet', 0)
    check_rows = rules.get('check_rows', [])
    expected_order = rules.get('expected_order', [])
    verify_full_sort = rules.get('verify_full_sort', False)
    total_data_rows = rules.get('total_data_rows', 28)
    if not expected_order:
        wb.close()
        return 0.0
    ws = wb.worksheets[sheet_idx]
    result_data = []
    for row in check_rows:
        name = ws[f'B{row}'].value
        marks = ws[f'C{row}'].value
        result_data.append({'row': row, 'name': name, 'marks': marks})
    wb.close()
    correct = 0
    total = len(expected_order)
    for (i, expected_row) in enumerate(expected_order):
        if i >= len(result_data):
            break
        result_row = result_data[i]
        expected_marks = expected_row.get('marks')
        result_marks = result_row.get('marks')
        marks_match = False
        if expected_marks == '--' and result_marks == '--':
            marks_match = True
        elif expected_marks != '--' and result_marks != '--':
            try:
                if abs(float(result_marks) - float(expected_marks)) < 0.1:
                    marks_match = True
            except:
                pass
        if marks_match:
            correct += 1
    if verify_full_sort:
        all_marks = []
        for row in range(2, 2 + total_data_rows):
            marks_val = ws[f'C{row}'].value
            if marks_val is not None and marks_val != '--':
                try:
                    all_marks.append(float(marks_val))
                except:
                    pass
        is_sorted = all((all_marks[i] >= all_marks[i + 1] for i in range(len(all_marks) - 1)))
        if not is_sorted:
            return correct / total * 0.5 if total > 0 else 0.0
    return correct / total if total > 0 else 0.0

def check_xlsx_min__d4f5dd7f493a2bdcc0b057e599305b86(result, expected, **options):
    """Check if formulas were copied and minimum value is correct in B31.

    Args:
        result: Dict with 'b_formulas_copied', 'd_formulas_copied', 'b31_value', 'computed_min'
        expected: Dict with 'min_value' (expected value in B31)
        **options: tolerance (default 0.01)

    Returns:
        float: Partial credit scoring:
               - 0.33 if B column formulas copied (B3:B30)
               - 0.33 if D column formulas copied (D3:D30)
               - 0.34 if B31 contains correct min value
    """
    if result is None:
        return 0.0
    tolerance = options.get('tolerance', 0.01)
    expected_min = expected.get('min_value')
    if expected_min is None:
        return 0.0
    score = 0.0
    if result.get('b_formulas_copied', False):
        score += 0.33
    if result.get('d_formulas_copied', False):
        score += 0.33
    b31_value = result.get('b31_value')
    computed_min = result.get('computed_min')
    if b31_value is not None and abs(b31_value - expected_min) <= tolerance:
        if computed_min is not None and abs(b31_value - computed_min) <= tolerance:
            score += 0.34
    return min(score, 1.0)

