def check_numeric_value__c4d957b9ed4c029b04783deb70ccd213(result: Any, expected: Any, **options) -> float:
    """Compare numeric values with optional tolerance.

    Args:
        result: Result value (string or number)
        expected: Expected value from rules dict (should contain 'value' key)
        **options: Additional options including 'tolerance' (default: 0.01)

    Returns:
        float: 1.0 if values match within tolerance, 0.0 otherwise
    """
    tolerance = options.get('tolerance', 0.01)
    expected_value = expected.get('value') if isinstance(expected, dict) else expected
    if expected_value is None:
        logger.error('No expected value provided')
        return 0.0
    try:
        if isinstance(result, str):
            numbers = re.findall('-?\\d+\\.?\\d*', result)
            if not numbers:
                logger.warning(f'No number found in result: {result}')
                return 0.0
            result_value = float(numbers[0])
        else:
            result_value = float(result)
        expected_value = float(expected_value)
        diff = abs(result_value - expected_value)
        if diff <= tolerance:
            return 1.0
        else:
            logger.info(f'Value mismatch: result={result_value}, expected={expected_value}, diff={diff}')
            return 0.0
    except (ValueError, TypeError) as e:
        logger.error(f'Error comparing values: {e}')
        return 0.0

