def check_xlsx_cell_contains__adc491c6(result_state, expected_state, **options):
    """
    Check if the xlsx cell value contains the expected keywords/patterns.

    This function verifies that a cell contains both:
    1. The keyword "practical" (case-insensitive)
    2. A duration indicator for 3 hours (e.g., "3", "three", "3-hour", "three-hour")

    Args:
        result_state (str): The actual cell value from the getter
        expected_state (dict): Expected state with rules:
            - contains (str): keyword that must be present (e.g., "practical")
            - case_sensitive (bool): whether comparison is case-sensitive

    Returns:
        float: 1.0 if all requirements are met, 0.0 otherwise
    """
    if not isinstance(result_state, str):
        result_state = str(result_state)
    if not isinstance(expected_state, dict):
        return 0.0
    contains = expected_state.get('contains', '')
    case_sensitive = expected_state.get('case_sensitive', False)
    if not case_sensitive:
        result_lower = result_state.lower()
        contains_lower = contains.lower()
    else:
        result_lower = result_state
        contains_lower = contains
    if contains_lower not in result_lower:
        return 0.0
    duration_pattern = '(3[-\\s]?hours?|three[-\\s]?hours?|\\b3\\b|\\bthree\\b)'
    if not case_sensitive:
        if re.search(duration_pattern, result_state, re.IGNORECASE):
            return 1.0
    elif re.search(duration_pattern, result_state):
        return 1.0
    return 0.0

