def check_calc_rows_deleted__39358635(result, expected, **options):
    """Check if all employees who left early (before 5:00 PM) on 6/21/2023 have been deleted.

    This function verifies the deletion logic by checking that:
    1. NO remaining employees in the 6/21/2023 section have Clock-out < 5:00 PM
    2. All employees with Clock-out >= 5:00 PM or invalid times remain
    3. The deletion was based on actual leave times, not arbitrary criteria

    Args:
        result: Path to the Excel file
        expected: Dict with 'sheet' (sheet index), 'employee_col' (column with names)
        **options: Additional options

    Returns:
        float: 1.0 if all early leavers deleted and no false deletions, 0.0 otherwise
    """
    if not os.path.exists(result):
        return 0.0
    try:
        wb = openpyxl.load_workbook(result, data_only=True)
        sheet_idx = expected.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cutoff_time = time(17, 0, 0)
        employee_col_idx = 1
        clockout_col_idx = 3
        early_leavers_remaining = []
        for (row_idx, row) in enumerate(ws.iter_rows(min_row=12, values_only=True), start=12):
            if len(row) <= clockout_col_idx:
                continue
            employee_name = row[employee_col_idx]
            clockout_value = row[clockout_col_idx]
            if not employee_name or employee_name in ['Employees', 'Late Comers', 'Early Leavers']:
                continue
            if employee_name is None or str(employee_name).strip() == '':
                continue
            if isinstance(clockout_value, time):
                if clockout_value < cutoff_time:
                    early_leavers_remaining.append({'name': employee_name, 'clockout': clockout_value, 'row': row_idx})
        if early_leavers_remaining:
            print(f'ERROR: Found {len(early_leavers_remaining)} employees who left early but were not deleted:')
            for emp in early_leavers_remaining:
                print(f"  - {emp['name']} left at {emp['clockout']} (row {emp['row']})")
            wb.close()
            return 0.0
        wb.close()
        return 1.0
    except Exception as e:
        print(f'Error checking deleted rows: {e}')
        import traceback
        traceback.print_exc()
        return 0.0

