def check_xlsx_sorted_alphabetically__b24c34ca1a3702a8b63f2fe25f785d21(result: List[str], expected: Dict[str, Any], **options) -> float:
    """Check if restaurant names are sorted according to the specified order.

    Args:
        result: List of restaurant names from the getter
        expected: Rules dictionary containing 'sorted_order' key ('ascending' or 'descending')
                  When expected.type='rule' in config, expected IS the rules dict
        **options: Additional options

    Returns:
        float: 1.0 if sorted correctly, 0.0 otherwise
    """
    if not result:
        return 0.0
    non_empty_names = [name for name in result if name.strip()]
    if not non_empty_names:
        return 0.0
    sorted_order = expected.get('sorted_order', 'ascending')
    if sorted_order == 'ascending':
        sorted_names = sorted(non_empty_names, key=lambda x: x.lower())
    elif sorted_order == 'descending':
        sorted_names = sorted(non_empty_names, key=lambda x: x.lower(), reverse=True)
    else:
        return 0.0
    if non_empty_names == sorted_names:
        return 1.0
    else:
        return 0.0

def check_xlsx_cells_with_fill__da3f6b85(result, expected, **options):
    """Check if filled cells match expected cells.

    Args:
        result: dict with 'filled_cells' from getter
        expected: dict with 'expected_cells' (list of cell addresses)
        **options: 'min_match_count' - minimum cells that must have fill

    Returns:
        float: Score based on match
    """
    result_cells = set(result.get('filled_cells', []))
    expected_cells = set(expected.get('expected_cells', []))
    min_match = options.get('min_match_count', 0)
    if min_match > 0:
        if len(result_cells) >= min_match:
            if result_cells.issubset(expected_cells):
                return 1.0
            else:
                correct_count = len(result_cells.intersection(expected_cells))
                return correct_count / max(len(result_cells), len(expected_cells))
        else:
            return 0.0
    if result_cells == expected_cells:
        return 1.0
    elif len(expected_cells) > 0:
        intersection = len(result_cells.intersection(expected_cells))
        union = len(result_cells.union(expected_cells))
        return intersection / union if union > 0 else 0.0
    else:
        return 0.0

