def check_xlsx_period_rate_count__656c6899d94f241017f36c0eb361b3f6(result, expected, **options):
    """Check if period rates are calculated correctly, formatted as numbers, and counted correctly.

    Verifies all three requirements:
    1. Period rate calculations are correct (Annual Rate / Period per year)
    2. Values are formatted as numbers
    3. Count of period rates > 3.0 is correct

    Args:
        result: dict from getter with keys:
            - period_rates: list of period rate values
            - sample_calculations: dict of sample calculation verification
            - all_numeric: bool indicating if all values are numeric
            - count_above_threshold: int count from actual data
            - count_value_from_sheet: int count value written to sheet
        expected: dict with keys:
            - expected_count: int expected count value
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result:
        return 0.0
    all_numeric = result.get('all_numeric', False)
    if not all_numeric:
        return 0.0
    sample_calculations = result.get('sample_calculations', {})
    if not sample_calculations:
        return 0.0
    correct_calculations = 0
    total_samples = 0
    for (row, calc_data) in sample_calculations.items():
        if calc_data.get('calculated_period_rate') is None:
            continue
        total_samples += 1
        calculated = calc_data['calculated_period_rate']
        actual = calc_data['actual_period_rate']
        if actual is not None and isinstance(actual, (int, float)):
            if abs(calculated - actual) < 0.01 or abs((calculated - actual) / max(abs(calculated), 0.01)) < 0.0001:
                correct_calculations += 1
    if total_samples < 3 or correct_calculations < 3:
        return 0.0
    expected_count = expected.get('expected_count')
    if expected_count is None:
        return 0.0
    count_above_threshold = result.get('count_above_threshold', 0)
    if count_above_threshold != expected_count:
        return 0.0
    count_value_from_sheet = result.get('count_value_from_sheet')
    if count_value_from_sheet is not None and count_value_from_sheet != expected_count:
        return 0.0
    return 1.0

