def check_xlsx_hyperlinks__babf083e0503f34ac19120c95bb94f26(result: List[Dict[str, Any]], expected: Dict[str, Any], **options) -> float:
    """Check if cells have correct hyperlinks.

    Args:
        result: List of hyperlink info from getter
        expected: Expected hyperlink configuration from rules
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    expected_links = expected.get('hyperlinks', [])
    if not result or not expected_links:
        return 0.0
    if len(result) != len(expected_links):
        return 0.0
    score = 0.0
    points_per_match = 1.0 / len(expected_links)
    for (actual, expected_link) in zip(result, expected_links):
        expected_cell = expected_link.get('cell')
        expected_url = expected_link.get('url')
        if actual.get('cell') == expected_cell:
            if actual.get('hyperlink') == expected_url:
                score += points_per_match
    return min(1.0, score)

