def check_xlsx_data__5acaab75(result: Any, expected: Any, **options) -> float:
    """Check Excel data against expected values."""
    if not result:
        return 0.0
    score = 0.0
    total_checks = 0
    if 'has_headers' in expected and expected['has_headers']:
        total_checks += 1
        if len(result) > 0 and result[0]:
            if 'headers' in expected:
                expected_headers = expected['headers']
                actual_headers = [str(h).strip() if h else '' for h in result[0]]
                if len(actual_headers) >= len(expected_headers):
                    matches = sum((1 for (i, exp_h) in enumerate(expected_headers) if i < len(actual_headers) and actual_headers[i].lower() == str(exp_h).lower()))
                    if matches == len(expected_headers):
                        score += 1.0
            else:
                score += 1.0
    if 'label' in expected:
        total_checks += 1
        if len(result) > 1 and len(result[1]) > 0:
            actual_label = str(result[1][0]).strip() if result[1][0] else ''
            expected_label = str(expected['label']).strip()
            if actual_label.lower() == expected_label.lower():
                score += 1.0
    if 'count' in expected:
        total_checks += 1
        if len(result) > 1 and len(result[1]) > 1:
            try:
                count_val = int(result[1][1])
                if count_val == expected['count']:
                    score += 1.0
            except:
                pass
    if 'num_columns' in expected:
        total_checks += 1
        if len(result) > 0:
            actual_num_columns = len([h for h in result[0] if h is not None])
            if actual_num_columns == expected['num_columns']:
                score += 1.0
    if 'min_rows' in expected:
        total_checks += 1
        if len(result) >= expected['min_rows']:
            score += 1.0
    for key in ['filenames', 'authors', 'topics', 'sorted_lengths']:
        if key in expected:
            total_checks += 1
            expected_list = expected[key]
            if isinstance(result, list) and len(result) > 1:
                col_idx = 0
                actual_values = [row[col_idx] if len(row) > col_idx else None for row in result[1:] if row]
                actual_values = [str(v).strip().lower() if v else '' for v in actual_values]
                expected_values = [str(v).strip().lower() for v in expected_list]
                if len(actual_values) == len(expected_values):
                    matches = sum((1 for (a, e) in zip(actual_values, expected_values) if a == e))
                    if matches == len(expected_values):
                        score += 1.0
    return score / total_checks if total_checks > 0 else 0.0

