def check_xlsx_age_and_highlighting__7528d7b4(result, expected, **options):
    """
    Check both age calculation and highlighting are correct.

    Verifies:
    1. Ages are correctly calculated in the age column
    2. Correct rows are highlighted based on age range 25-35

    Args:
        result: Dict with 'ages' and 'highlighted_rows' from getter
        expected: Dict with expected 'ages' and 'highlighted_rows'

    Returns:
        float: Combined score (average of age score and highlighting score)
    """
    result_ages = result.get('ages', {})
    result_highlighted = result.get('highlighted_rows', [])
    expected_ages = expected.get('ages', {})
    expected_highlighted = expected.get('highlighted_rows', [])
    age_score = 0.0
    if expected_ages:
        total_rows = len(expected_ages)
        correct_ages = 0
        for (row, expected_age) in expected_ages.items():
            row_int = int(row) if isinstance(row, str) else row
            actual_age = result_ages.get(row_int)
            if actual_age is not None and actual_age == expected_age:
                correct_ages += 1
        age_score = correct_ages / total_rows if total_rows > 0 else 0.0
    highlighting_score = 0.0
    if expected_highlighted:
        total_expected = len(expected_highlighted)
        correct = sum((1 for row in expected_highlighted if row in result_highlighted))
        false_positives = sum((1 for row in result_highlighted if row not in expected_highlighted))
        highlighting_score = correct / total_expected
        penalty = false_positives / max(total_expected, 1) * 0.1
        highlighting_score = max(0.0, highlighting_score - penalty)
    combined_score = age_score * 0.5 + highlighting_score * 0.5
    return combined_score

def check_xlsx_rep_totals__31fece5ebadbc8a9d152ebc50d1167b1(result: Dict[str, Any], expected: Dict[str, Any], **options) -> float:
    """
    Check if total sales per rep are calculated correctly and top performer is highlighted.

    Scoring:
    - 0.6: All totals in column H are correct
    - 0.4: Top performer row is highlighted

    Args:
        result: Dict from getter with 'totals', 'top_row', 'highlighted_rows'
        expected: Dict with 'totals' (expected values), 'top_row' (expected top row)
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    score = 0.0
    expected_totals = expected.get('totals', {})
    expected_top_row = expected.get('top_row')
    result_totals = result.get('totals', {})
    result_top_row = result.get('top_row')
    highlighted_rows = result.get('highlighted_rows', [])
    if expected_totals and result_totals:
        correct_totals = 0
        total_count = len(expected_totals)
        for (row_idx, expected_val) in expected_totals.items():
            result_val = result_totals.get(row_idx, 0)
            if abs(result_val - expected_val) < 0.01:
                correct_totals += 1
        if total_count > 0:
            score += 0.6 * (correct_totals / total_count)
    if expected_top_row and expected_top_row in highlighted_rows:
        score += 0.4
    return min(score, 1.0)

