def check_cell_extraction__a8e6d3b2(result, expected, **options):
    """
    Validate extracted cell code with content verification.

    Args:
        result: File content from getter
        expected: Dict with separator, code line, and content requirements
        **options: Additional options

    Returns:
        float: Score between 0.0 and 1.0
    """
    if not result or not isinstance(result, str):
        return 0.0
    must_contain_separator = expected.get('must_contain_separator', False)
    separator_pattern = expected.get('separator_pattern', '# --- Cell')
    min_separators = expected.get('min_separators', 0)
    min_code_lines = expected.get('min_code_lines', 0)
    expected_snippets = expected.get('expected_code_snippets', [])
    verify_numbering = expected.get('verify_separator_numbering', False)
    score = 0.0
    if must_contain_separator:
        if separator_pattern in result:
            score += 0.15
    else:
        score += 0.15
    separator_count = result.count(separator_pattern)
    if separator_count >= min_separators:
        score += 0.15
    if verify_numbering:
        has_cell_1 = '# --- Cell 1 ---' in result
        has_cell_2 = '# --- Cell 2 ---' in result
        has_cell_3 = '# --- Cell 3 ---' in result
        if has_cell_1 and has_cell_2 and has_cell_3:
            score += 0.2
        elif has_cell_1 or has_cell_2 or has_cell_3:
            score += 0.1
    lines = result.splitlines()
    non_empty_lines = [l for l in lines if l.strip() and (not l.strip().startswith('#'))]
    if len(non_empty_lines) >= min_code_lines:
        score += 0.2
    if expected_snippets:
        snippet_score = 0.0
        snippets_found = 0
        for snippet in expected_snippets:
            if snippet.strip() in result or re.search(re.escape(snippet.strip()), result, re.IGNORECASE):
                snippets_found += 1
        if len(expected_snippets) > 0:
            snippet_score = 0.3 * (snippets_found / len(expected_snippets))
        score += snippet_score
    else:
        score += 0.3
    return min(1.0, score)

